-- MT-L2 Module 2 — Advanced Magnetic Theory (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Domain magnetik & kurva magnetisasi awal', '{"slides":[{"heading":"Domain Weiss & magnetisasi","body":"Material ferromagnetik (besi, baja, nikel, kobalt) tersusun dari magnetic domain (domain Weiss) — region mikroskopis dimana magnetic moment atom sudah teratur sejajar. Pada material yang belum dimagnetisasi, orientasi domain acak sehingga net flux = 0. Saat applied field H (magnetizing force, satuan A/m atau Oersted; 1 Oe = 79.6 A/m) dinaikkan, domain yang sejajar dengan H tumbuh melalui domain wall movement, lalu seluruh moment rotasi searah H, menghasilkan flux density B (satuan Tesla atau Gauss; 1 T = 10000 G) di dalam material. Inilah dasar mengapa MT memerlukan field cukup kuat untuk membentuk leakage field di diskontinuitas permukaan/near-surface."},{"heading":"Kurva magnetisasi awal (virgin curve)","body":"Plot B terhadap H dari kondisi fully demagnetized menghasilkan initial magnetization curve berbentuk S. Tahap awal (low H) kenaikan B lambat (reversible domain wall movement), lalu region steep dimana domain wall bergerak ireversibel (Barkhausen jumps) sehingga sedikit kenaikan H memberi lonjakan B besar, dan akhirnya knee menuju saturasi. Permeability material μ = B/H bukan konstan — μ maksimum berada di sekitar region steep dan turun drastis mendekati saturasi. Untuk MT praktis kita ingin bekerja di atas knee agar permukaan cukup jenuh dan leakage field maksimal di crack."},{"heading":"Saturasi magnetik","body":"Pada saturation, hampir semua domain sudah sejajar H sehingga penambahan H lagi tidak menambah B secara signifikan — kurva mendatar. Untuk baja karbon, intrinsic saturation flux density tipikal sekitar 1.6-2.1 Tesla. Operasi MT tidak perlu mencapai saturasi penuh; over-magnetization justru merugikan karena meningkatkan furry/non-relevant background dan menyulitkan interpretasi. Target praktis: tangential field strength 2.4-4.8 kA/m (≈ 30-60 Oersted / 30-60 Gauss tangensial) di permukaan, diverifikasi dengan Hall-effect tangential-field probe atau shim/QQI sesuai ASTM E1444/E709."}]}', 460, NULL),
  (2, 'reading', 'Kurva histeresis (B-H loop) mendalam', '{"slides":[{"heading":"Mengapa terbentuk hysteresis loop","body":"Ketika H dinaikkan ke saturasi lalu diturunkan kembali ke nol, B tidak mengikuti jalur naik yang sama — B tertinggal (lag) karena domain wall yang sudah bergerak ireversibel tidak kembali ke posisi semula. Fenomena ketertinggalan inilah hysteresis (Yunani: ''terlambat''). Plot B-H membentuk loop tertutup. Luas loop merepresentasikan energy loss (hysteresis loss) per siklus magnetisasi — penting untuk memahami pemanasan part pada AC magnetisasi dan kebutuhan energi pada demagnetisasi."},{"heading":"Retentivity (Br) & residual field","body":"Titik dimana kurva memotong sumbu B saat H sudah nol disebut retentivity atau residual flux density (Br). Inilah dasar Residual Technique: part dimagnetisasi lalu media diaplikasikan setelah arus dimatikan, mengandalkan field sisa. Material dengan retentivity tinggi (high-carbon, hardened steel, mis. baja bantalan) cocok untuk residual method; material soft (low-carbon, annealed) retentivity rendah sehingga harus pakai Continuous Technique. Residual field pada part jadi setelah inspeksi dibatasi tipikal ≤ 3 Gauss (≈ 240 A/m) bila dicek dengan calibrated field indicator."},{"heading":"Coercivity (Hc) & arti praktisnya","body":"Coercive force (Hc) adalah besar reverse field H yang diperlukan untuk mengembalikan B ke nol setelah saturasi — lebar loop pada sumbu H. Coercivity tinggi berarti material ''keras secara magnetik'' (sulit di-demagnetize, butuh reverse field besar); coercivity rendah berarti ''lunak secara magnetik'' (mudah didemagnetisasi). Kekerasan mekanik biasanya berkorelasi dengan coercivity: baja yang di-quench/hardened punya Hc tinggi. Ini menjelaskan mengapa part keras butuh demagnetisasi lebih agresif (initial reversing field tinggi)."},{"heading":"Membaca empat kuadran loop","body":"Loop lengkap mencakup titik kunci: +Bs dan -Bs (saturasi positif/negatif), +Br dan -Br (retentivity dua arah), serta +Hc dan -Hc (coercivity dua arah). Soft magnetic material menghasilkan loop sempit dan kurus (low Br, low Hc, low loss) sedangkan hard magnetic material loop lebar dan gemuk (high Br, high Hc, high loss). Level II harus dapat memetakan jenis material part ke pilihan teknik (continuous vs residual) dan strategi demagnetisasi berdasarkan bentuk loop ini."}]}', 500, NULL),
  (3, 'reading', 'Permeability, reluktansi & leakage field', '{"slides":[{"heading":"Permeability vs reluctance","body":"Permeability (μ) mengukur seberapa mudah material membawa flux; relative permeability μr baja bisa ratusan sampai ribuan dibanding udara (μr ≈ 1). Reluctance (R) adalah lawan dari permeance — analog resistansi pada rangkaian magnetik: R = l/(μ·A), dimana l panjang lintasan magnetik dan A luas penampang. Diskontinuitas (crack, void) atau air gap punya reluctance sangat tinggi sehingga flux terpaksa membelok keluar permukaan — inilah magnetic flux leakage yang menahan partikel dan membentuk indikasi."},{"heading":"Orientasi diskontinuitas vs field","body":"Leakage field maksimum bila diskontinuitas tegak lurus (90°) terhadap arah flux. Crack yang sejajar arah flux (0°) hampir tidak mengganggu lintasan flux sehingga leakage minimal/tak terdeteksi. Sensitivitas turun signifikan saat sudut < 45° terhadap field. Karena orientasi defect tidak diketahui di lapangan, Level II wajib menerapkan dua arah magnetisasi yang saling tegak lurus (mis. circular + longitudinal) atau multi-directional, dengan verifikasi adequacy memakai QQI shim di kedua arah."},{"heading":"Demagnetizing field & efek geometri","body":"Bentuk part menciptakan demagnetizing field internal yang melawan applied field, terutama pada part pendek-gemuk (L/D kecil). Inilah alasan formula coil ampere-turns memasukkan rasio L/D: low fill-factor NI = 45000/(L/D), high fill-factor NI = 35000/(L/D + 2) per ASTM E1444 (rentang efektif L/D umumnya dibatasi 2-15). Part dengan L/D rendah perlu effective L/D ditingkatkan (mis. pakai pole pieces/extension bars) agar demagnetizing effect tidak membuat longitudinal field tak memadai."}]}', 440, NULL),
  (4, 'reading', 'Teori demagnetisasi mendalam', '{"slides":[{"heading":"Prinsip: hysteresis loop yang mengecil","body":"Demagnetisasi mengembalikan orientasi domain menjadi acak sehingga residual field ≈ 0. Caranya: kenakan medan bolak-balik (reversing) yang membalik polaritas sambil amplitudonya diturunkan bertahap menuju nol. Setiap pembalikan menggambar loop B-H yang semakin kecil mengarah ke origin, sehingga Br akhirnya tinggal mendekati nol. Field awal harus ≥ field yang dipakai saat magnetisasi (dan harus melampaui coercivity material) agar benar-benar ''mengaduk'' seluruh domain. Alternatif lain adalah pemanasan di atas Curie temperature, namun jarang praktis di lapangan."},{"heading":"Metode AC demagnetization","body":"AC coil demag: part dilewatkan perlahan melalui koil AC ber-energi lalu ditarik menjauh (jarak ≥ 1 m / 3 ft) sehingga part mengalami field reversing 50/60 Hz yang amplitudonya meluruh seiring jarak. Cepat dan efektif untuk part kecil, tetapi skin effect membuat AC hanya efektif di lapisan permukaan — part tebal mungkin tetap menyimpan residual di inti. Untuk itu part berat/tebal sering perlu metode lain atau diproses bertahap."},{"heading":"DC step-down & reversing DC","body":"Untuk part tebal atau yang dimagnetisasi DC, gunakan reversing DC dengan step-down current: polaritas dibalik berulang sambil arus dikurangi bertahap ke nol. DC menembus lebih dalam dibanding AC (tanpa keterbatasan skin effect) sehingga mendemagnetisasi cross-section penuh. Beberapa unit modern menyediakan automatic decaying-reversing-DC cycle. Aturan kunci: amplitudo awal harus melampaui level magnetisasi sebelumnya, dan penurunan harus halus/bertahap agar tidak meninggalkan residual pada salah satu polaritas."},{"heading":"Verifikasi & batas residual field","body":"Setelah demag, ukur residual dengan calibrated field indicator (Gauss/Hall meter) di beberapa titik, terutama ujung dan area massa terkonsentrasi. Batas umum yang diterima: ≤ 3 Gauss (≈ 240 A/m) kecuali spesifikasi pelanggan lebih ketat. Demagnetisasi wajib bila: part akan dilas/dimesin (busur tertarik / chip menempel), bergerak dekat kompas/instrumen sensitif, atau berpotensi jadi pengumpul serbuk besi saat servis. Medan Bumi (~0.25-0.65 Gauss) dan orientasi part terhadap arah magnetisasi sebelumnya memengaruhi pembacaan — re-orient part saat re-check."}]}', 500, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Magnetic Theory', '{"description":"8 soal teori magnetik lanjutan: hysteresis/B-H curve, retentivity & coercivity, permeability/reluktansi, leakage field, dan teori demagnetisasi Level II.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 2 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada kurva B-H, titik dimana flux density B masih tersisa saat magnetizing force H sudah kembali ke nol disebut?',
   '["Retentivity / residual flux (Br)","Coercivity (Hc)","Saturation (Bs)","Permeability (μ)"]', 0,
   'Retentivity (residual flux density Br) adalah perpotongan kurva dengan sumbu B saat H = 0 — field sisa yang menjadi dasar Residual Technique. Coercivity (Hc) justru adalah besar reverse H yang membuat B = 0, bukan field sisa.', 'theory', 'easy'),
  ('Coercive force (Hc) yang tinggi pada suatu material baja menunjukkan bahwa material tersebut?',
   '["Memiliki permeability sangat tinggi","Tidak dapat menahan residual field sama sekali","Sulit didemagnetisasi sehingga butuh reverse field besar (magnetically hard)","Mudah didemagnetisasi dan selalu memakai continuous technique"]', 2,
   'Coercivity tinggi = loop lebar pada sumbu H = material magnetically hard yang sulit didemagnetisasi (butuh reverse field besar). Biasanya berkorelasi dengan kekerasan mekanik (hardened/quenched steel) dan retentivity tinggi.', 'theory', 'medium'),
  ('Mengapa Residual Technique hanya cocok untuk material seperti high-carbon atau hardened steel?',
   '["Karena retentivity-nya rendah sehingga field cepat hilang","Karena permeability-nya mendekati nol","Karena hanya material lunak yang menahan flux","Karena retentivity (Br) tinggi sehingga menahan field sisa cukup kuat setelah arus dimatikan"]', 3,
   'Residual Technique mengandalkan field sisa setelah arus mati, jadi membutuhkan retentivity (Br) tinggi seperti pada baja keras. Material soft/low-carbon retentivity rendah sehingga harus memakai Continuous Technique.', 'theory', 'medium'),
  ('Apa prinsip dasar proses demagnetisasi yang benar?',
   '["Menerapkan DC konstan satu arah hingga part jenuh","Menerapkan medan bolak-balik (reversing) dengan amplitudo yang diturunkan bertahap menuju nol","Menaikkan H secara terus-menerus melampaui saturasi tanpa pembalikan","Menerapkan satu pulsa tunggal berlawanan arah lalu berhenti"]', 1,
   'Demagnetisasi menggambar hysteresis loop yang makin mengecil ke origin: medan dibalik polaritasnya berulang sambil amplitudonya diturunkan bertahap ke nol, mengacak ulang orientasi domain sehingga Br ≈ 0. Field awal harus ≥ level magnetisasi sebelumnya (melampaui Hc).', 'demagnetization', 'medium'),
  ('Untuk part yang tebal dan dimagnetisasi DC, mengapa AC coil demagnetization mungkin tidak sepenuhnya efektif?',
   '["AC mengalami skin effect sehingga hanya efektif di lapisan permukaan, meninggalkan residual di inti","AC menghasilkan field yang terlalu kuat untuk part tebal","AC tidak membalik polaritas sehingga tidak mengacak domain","AC tidak dapat diturunkan amplitudonya secara bertahap"]', 0,
   'Karena skin effect, arus AC terkonsentrasi di permukaan dan kurang menembus inti part tebal, sehingga residual bisa tertinggal di cross-section dalam. Reversing DC step-down penetrasinya lebih dalam dan lebih sesuai untuk part tebal.', 'demagnetization', 'hard'),
  ('Magnetic flux leakage yang menahan partikel paling kuat terjadi ketika diskontinuitas berorientasi bagaimana terhadap arah flux?',
   '["Sejajar (0°) terhadap arah flux","Pada sudut 30° terhadap arah flux","Tegak lurus (90°) terhadap arah flux","Orientasi tidak berpengaruh terhadap leakage"]', 2,
   'Leakage field maksimum saat crack tegak lurus (90°) terhadap flux. Crack yang sejajar flux (0°) hampir tidak mengganggu lintasan sehingga leakage minimal — inilah alasan diperlukan dua arah magnetisasi yang saling tegak lurus.', 'theory', 'easy'),
  ('Setelah demagnetisasi, batas residual field yang umum diterima (kecuali spesifikasi lebih ketat) dan cara verifikasinya adalah?',
   '["≤ 10 Gauss, diverifikasi dengan QQI shim","≤ 50 Gauss, diverifikasi dengan lift test yoke","0 Gauss absolut, diverifikasi dengan ammeter","≤ 3 Gauss (≈ 240 A/m), diverifikasi dengan calibrated field indicator / Hall-effect gaussmeter"]', 3,
   'Batas residual field yang lazim diterima adalah ≤ 3 Gauss (≈ 240 A/m), diukur dengan field indicator / Hall-effect gaussmeter terkalibrasi di beberapa titik (terutama ujung dan area massa). QQI shim memverifikasi adequacy magnetisasi, dan lift test mengecek gaya angkat yoke — bukan residual field.', 'demagnetization', 'medium'),
  ('Mengapa formula coil ampere-turns ASTM E1444 (mis. low fill-factor NI = 45000/(L/D)) bergantung pada rasio L/D part?',
   '["Karena rasio L/D menentukan resistansi listrik kabel koil","Karena part dengan L/D rendah memiliki demagnetizing field internal lebih besar sehingga butuh kompensasi ampere-turns","Karena L/D menentukan warna partikel yang dipakai","Karena L/D hanya relevan untuk circular magnetization, bukan longitudinal"]', 1,
   'Part pendek-gemuk (L/D rendah) menghasilkan demagnetizing field internal besar yang melawan applied longitudinal field. Formula mengaitkan L/D agar ampere-turns memadai; part L/D rendah sering memerlukan pole pieces/extension bars untuk menaikkan effective L/D.', 'field-calculation', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 3 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Konsep & dasar multi-directional magnetization', '{"slides":[{"heading":"Mengapa multi-directional","body":"Diskontinuitas hanya terdeteksi bila orientasinya membentuk sudut besar terhadap arah magnetic flux; sensitivitas maksimum ketika defect tegak lurus (90°) terhadap flux dan praktis hilang ketika defect sejajar field (0°). Aturan praktis ASTM E709/E1444: defect dengan orientasi 45°-90° terhadap arah field masih terdeteksi andal (yaitu dalam ±45° dari posisi tegak lurus). Itu sebabnya inspeksi konvensional memerlukan minimal dua arah magnetisasi yang saling tegak lurus — circular field untuk longitudinal defect dan longitudinal field untuk transverse defect. Multi-directional menggabungkan kedua arah dalam satu siklus sehingga seluruh rentang orientasi tercover sekaligus."},{"heading":"Definisi simultaneous vs sequential","body":"Sequential (two-shot): dua atau lebih field diaplikasikan bergantian dalam langkah terpisah — misalnya headshot/circular dulu, lalu coil/longitudinal — masing-masing dengan bath flow saat arah tersebut aktif. Simultaneous (true multidirectional): dua atau tiga field di-energize dalam pulse yang sangat cepat dan saling overlap sehingga partikel mengalami efek vektor resultan yang seakan berputar; satu aplikasi mendeteksi semua arah secara bersamaan. Keduanya berbeda dari single-direction yang hanya menangkap satu orientasi defect."},{"heading":"Prinsip vector switching","body":"Pada unit multidirectional modern, dua atau tiga sirkuit di-pulse bergiliran pada frekuensi tinggi (umumnya berbasis line frequency 50/60 Hz, sehingga tiap arah aktif beberapa kali per detik). Karena partikel basah (wet method) bergerak relatif lambat dibanding kecepatan switching, partikel sempat menyusun diri (build-up) pada setiap field sebelum switch berikutnya, menghasilkan indikasi pada semua arah dalam satu aplikasi. Kunci: switching harus cukup cepat agar tidak ada arah yang kehilangan build-up, sekaligus tiap pulse harus cukup kuat untuk membentuk indikasi yang adekuat."},{"heading":"Wet continuous adalah wajib","body":"Multidirectional secara praktis hanya berfungsi dengan teknik wet continuous: bath diaplikasikan tepat sebelum dan dihentikan tepat saat arus mengalir, sehingga partikel mobile saat field aktif. Residual method tidak cocok karena residual field di material bersifat single-direction (hanya menyimpan magnetisasi terakhir/dominan), sehingga arah lain hilang. Selalu pastikan aliran bath dihentikan sebelum arus mati agar partikel tidak tersapu (wash-out) dari indikasi yang baru terbentuk."}]}', 460, NULL),
  (2, 'reading', 'Verifikasi field balance & efektivitas', '{"slides":[{"heading":"Masalah ketidakseimbangan field","body":"Pada multidirectional, jika satu arah jauh lebih kuat dari arah lain, field resultan menjadi terlalu condong (biased) ke arah dominan dan defect pada orientasi lemah bisa tidak terdeteksi. Karena itu setiap setup multidirectional WAJIB diverifikasi keseimbangannya secara aktual pada part — bukan diasumsikan dari setting arus saja. Inilah perbedaan kunci antara Level I (apply pre-set) dan Level II (verifikasi dan adjust balance, lalu sign-off)."},{"heading":"QQI / shim — verifikasi utama","body":"ASTM E1444 mensyaratkan penggunaan artificial flaw shim (QQI — Quantitative Quality Indicator, mis. tipe 3C2 atau 4C2 dengan slot melingkar atau cross/plus) untuk membuktikan adequacy multidirectional. Beberapa shim ditempel pada beberapa lokasi part dengan slot menghadap arah berbeda; bila seluruh arah field adekuat dan seimbang, semua kaki slot pada shim akan terisi indikasi secara merata. Bila satu arah lemah, kaki slot pada arah itu tidak terbentuk — sinyal langsung untuk menaikkan arus arah tersebut."},{"heading":"Pie gauge & magnetic field indicator","body":"Pie gauge (segmen baja lunak yang disambung dengan copper face) berguna untuk menunjukkan arah field di permukaan pada single-direction, tetapi pada multidirectional pie gauge kurang ideal karena field yang berganti cepat membuat pembacaan arah menjadi ambigu. Untuk itu shim QQI lebih dianjurkan. Gaussmeter/Hall probe digunakan untuk mengukur kuat tangential field, tetapi tidak menggantikan shim untuk membuktikan flux benar-benar masuk ke part dan membentuk indikasi pada tiap arah."},{"heading":"Adequacy: bukan sekadar amperage","body":"Field adequacy pada part nyata dipengaruhi geometri, fill factor, dan jalur reluktansi — bukan hanya angka arus. ASME V Article 7 dan ASTM E1444 menetapkan adequacy ditunjukkan dengan artificial flaw (shim) atau dengan tangential field strength 30-60 Gauss (3-6 mT) di area inspeksi, diukur dengan Hall-effect (tangential) probe. Pada multidirectional, tiap arah harus mencapai threshold ini, sehingga verifikasi sebaiknya dilakukan untuk setiap arah dan dipastikan tetap terbentuk saat keduanya aktif bergantian."}]}', 480, NULL),
  (3, 'reading', 'Metode kombinasi & konfigurasi peralatan', '{"slides":[{"heading":"Kombinasi circular + longitudinal","body":"Konfigurasi paling umum: headshot (direct current melewati part, menghasilkan circular field untuk longitudinal defect) dikombinasikan dengan coil atau cable wrap (longitudinal field untuk transverse defect). Pada bench unit multidirectional, headstock/tailstock memberi circular sementara built-in coil memberi longitudinal; controller men-switch keduanya secara bergiliran. Hasilnya satu part diperiksa untuk longitudinal dan transverse defect tanpa reposisi."},{"heading":"Three-phase full-wave DC (3-fasa FWDC)","body":"Sebagian besar unit multidirectional produksi menggunakan three-phase full-wave rectified DC. Alasannya: ripple rendah dan penetrasi lebih dalam dibanding half-wave atau single-phase, serta tiga fasa memudahkan pembangkitan beberapa output field independen yang bisa di-balance secara terpisah. FWDC memberi field yang stabil sehingga build-up partikel konsisten pada tiap arah. Half-wave DC (HWDC) memberi getaran partikel yang membantu mobilitas pada single-direction, tetapi produksi multidirectional lebih memilih FWDC demi kestabilan balance."},{"heading":"Vector / tri-directional","body":"Untuk part kompleks (mis. crankshaft, landing gear), unit dapat memakai tiga output: dua circular pada bidang berbeda plus satu longitudinal, sehingga membentuk field yang mendekati ''all-direction''. Tiap output di-pulse bergiliran. Tantangannya adalah meng-balance tiga arah sekaligus; verifikasi memerlukan shim ditempatkan pada beberapa lokasi dan orientasi karena distribusi flux sangat bergantung geometri lokal."},{"heading":"Demagnetisasi setelah multidirectional","body":"Karena part menerima field dari beberapa arah, residual field bisa kompleks dan terperangkap. Demagnetisasi tetap memakai prinsip membalik arah field sambil menurunkan amplitudo secara bertahap — AC step-down (reversing) atau coil pass-through dengan amplitudo menurun. Verifikasi residual dengan field indicator/gaussmeter; batas umum residual ≤ 3 Gauss (kriteria aerospace sering lebih ketat, mis. ≤ 2 G sesuai spec part tertentu). Residual dari DC lebih sulit di-demag daripada AC, sehingga unit FWDC kadang dilengkapi rangkaian demag AC terpisah."}]}', 470, NULL),
  (4, 'reading', 'Automated production lines & process control', '{"slides":[{"heading":"Automated bench & inline systems","body":"Pada produksi volume tinggi (otomotif, aerospace forging), part dimuat ke fixture, bath diaplikasikan otomatis (flood/spray), shot multidirectional di-fire oleh PLC, lalu part berpindah ke inspection booth (kabin UV untuk fluorescent). Otomatisasi mengontrol urutan, durasi shot (umumnya 0,5-1,5 detik atau beberapa pulse), dan timing flow agar konsisten antar part — mengurangi variabilitas operator."},{"heading":"System performance check (E1444)","body":"Sistem otomatis harus diverifikasi tiap awal shift dan setelah perubahan signifikan: akurasi ammeter (dalam ±10% per ASTM E1444), quick-break check, lift test untuk yoke jika ada, UV-A intensity ≥ 1000 µW/cm² pada 38 cm (15 in) dengan ambient white light ≤ 2 fc (≈ 20 lux) di booth, konsentrasi suspensi (settling test 0,1-0,4 mL/100 mL untuk fluorescent, 1,2-2,4 mL untuk visible), dan shim test pada part referensi untuk membuktikan field tiap arah masih adequate."},{"heading":"Quick-break & timing kritis","body":"Quick-break circuit (pemutusan arus yang cepat) penting terutama untuk longitudinal/coil field karena menjaga ketajaman field di ujung part dan membantu pembentukan indikasi di end region. Pada multidirectional otomatis, controller harus menjaga jumlah pulse per arah dan rasio on-time tiap arah; jika satu arah di-truncate, balance rusak. Karena itu monitoring arus tiap arah (peak amperage readout per channel) menjadi bagian dari QC harian."},{"heading":"Batasan & jebakan multidirectional","body":"Multidirectional menghemat waktu tetapi tidak menggantikan kebutuhan verifikasi balance pada tiap geometri baru; field bisa lemah di lokasi tertentu (mis. lubang, perubahan penampang, sudut tajam) sehingga shim harus ditempel di beberapa titik kritis. Part dengan geometri berbeda tidak boleh diasumsikan menerima balance yang sama. Level II bertanggung jawab memvalidasi setup multidirectional untuk tiap part number sebelum dilepas ke produksi."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Multi-directional magnetization', '{"description":"7 soal: simultaneous vs sequential, verifikasi balance dengan QQI shim, konfigurasi peralatan, dan kontrol proses produksi otomatis.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 3 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa inspeksi MT konvensional minimal memerlukan dua arah magnetisasi yang saling tegak lurus?',
   '["Karena defect terdeteksi paling baik saat tegak lurus terhadap field dan praktis tak terdeteksi saat sejajar, sehingga arah kedua mencakup orientasi yang terlewat","Untuk menggandakan kuat field agar penetrasi lebih dalam","Agar residual field tersimpan lebih kuat di material","Karena satu arah hanya bekerja untuk material feromagnetik dan arah lain untuk non-feromagnetik"]', 0,
   'Sensitivitas maksimum ketika defect tegak lurus (90°) terhadap flux dan hilang saat sejajar (0°). Aturan praktis E709/E1444: defect masih terdeteksi andal pada orientasi 45°-90° terhadap field. Maka diperlukan circular field (untuk longitudinal defect) dan longitudinal field (untuk transverse defect).', 'Multi-Directional Theory', 'easy'),
  ('Apa perbedaan inti antara metode sequential (two-shot) dan simultaneous (true multidirectional)?',
   '["Sequential memakai AC sedangkan simultaneous selalu memakai HWDC","Sequential hanya untuk part kecil, simultaneous hanya untuk part besar","Sequential mengaplikasikan tiap field secara terpisah bergantian, sementara simultaneous men-switch dua/tiga field dengan cepat dan overlapping sehingga partikel mendeteksi semua arah dalam satu aplikasi","Sequential tidak memerlukan wet bath sedangkan simultaneous memerlukannya"]', 2,
   'Sequential = field diaplikasikan satu per satu dalam langkah terpisah. Simultaneous/true multidirectional = beberapa field di-pulse sangat cepat dan overlapping sehingga partikel basah sempat build-up pada tiap arah, menghasilkan deteksi semua orientasi dalam satu shot.', 'Multi-Directional Theory', 'medium'),
  ('Mengapa multidirectional magnetization hampir selalu menggunakan teknik wet continuous dan tidak cocok dengan residual method?',
   '["Karena residual method tidak bisa dipakai pada material feromagnetik","Karena wet continuous lebih murah daripada residual","Karena residual field di material bersifat single-direction (hanya menyimpan magnetisasi dominan/terakhir) sehingga arah lain hilang, sedangkan wet continuous menjaga partikel mobile saat tiap field aktif","Karena residual method memerlukan dry powder yang dilarang pada produksi otomatis"]', 2,
   'Residual field hanya menyimpan satu arah magnetisasi dominan, sehingga orientasi lain tidak terdeteksi. Multidirectional perlu partikel yang mobile bersamaan dengan field aktif di setiap arah — itulah wet continuous (bath dihentikan tepat sebelum arus mati untuk menghindari wash-out).', 'Technique', 'medium'),
  ('Menurut ASTM E1444, alat utama yang disyaratkan untuk memverifikasi bahwa seluruh arah field pada shot multidirectional adekuat dan seimbang adalah:',
   '["Pengukuran arus puncak saja dengan ammeter","QQI / artificial flaw shim (mis. 3C2/4C2) yang ditempel pada beberapa lokasi dengan slot menghadap arah berbeda","Pie gauge tunggal di tengah part","Visual estimate dari kepadatan partikel"]', 1,
   'E1444 mensyaratkan QQI/artificial flaw shim untuk verifikasi multidirectional. Bila semua arah field adekuat dan seimbang, seluruh kaki slot shim terisi indikasi merata; bila satu arah lemah, kaki slot pada arah itu tidak terbentuk — sinyal untuk menaikkan arus arah tersebut.', 'Verification', 'medium'),
  ('Mengapa pie gauge kurang ideal sebagai verifikasi arah field pada shot multidirectional dibanding QQI shim?',
   '["Pie gauge hanya bekerja pada arus AC murni","Field yang berganti arah dengan cepat membuat pembacaan arah pada pie gauge menjadi ambigu, sedangkan shim membuktikan flux benar membentuk indikasi pada tiap arah","Pie gauge terbuat dari aluminium yang tidak feromagnetik","Pie gauge tidak boleh menyentuh permukaan part"]', 1,
   'Pada multidirectional, field berganti cepat sehingga pie gauge memberi pembacaan arah yang ambigu. QQI shim ditempel langsung dan membuktikan flux masuk part serta membentuk indikasi pada setiap orientasi, sehingga lebih andal untuk verifikasi balance.', 'Verification', 'hard'),
  ('Jenis arus yang paling umum dipakai pada unit multidirectional produksi dan alasannya adalah:',
   '["Single-phase half-wave DC karena getaran partikel meningkatkan mobilitas di semua arah","AC murni karena hanya AC yang bisa memberi field dua arah sekaligus","Pulsed DC kapasitor karena durasi sangat singkat menghemat energi","Three-phase full-wave rectified DC (3-fasa FWDC) karena ripple rendah, penetrasi dalam, dan memudahkan menghasilkan beberapa output field independen yang bisa di-balance"]', 3,
   'Unit multidirectional produksi umumnya memakai 3-fasa FWDC: ripple rendah memberi field stabil sehingga build-up partikel konsisten pada tiap arah, penetrasi dalam, dan tiga fasa memudahkan output field independen yang dapat di-balance.', 'Equipment', 'medium'),
  ('Pada lini MT otomatis dengan multidirectional, apa konsekuensi paling kritis jika controller men-truncate (memotong) on-time salah satu arah field?',
   '["Konsentrasi suspensi akan naik di atas batas settling test","Field balance rusak sehingga defect pada orientasi arah yang dipotong bisa lolos tak terdeteksi","UV-A intensity di booth akan turun di bawah 1000 µW/cm²","Demagnetisasi menjadi tidak diperlukan lagi"]', 1,
   'Jika satu arah di-truncate, rasio on-time antar arah berubah dan balance rusak; arah yang melemah tidak membentuk indikasi sehingga defect pada orientasi tersebut bisa lolos. Itulah mengapa monitoring peak amperage per channel menjadi bagian QC harian.', 'Process Control', 'hard'),
  ('Saat melakukan system performance check harian pada booth inspeksi fluorescent MT otomatis, nilai yang benar untuk intensitas UV-A dan batas white light adalah:',
   '["UV-A ≥ 100 µW/cm² pada 38 cm dengan white light ≤ 200 fc","UV-A ≥ 5000 µW/cm² pada 10 cm dengan white light tidak dibatasi","UV-A ≥ 1000 µW/cm² pada 38 cm (15 in) dengan white light ≤ 2 fc (≈ 20 lux)","UV-A ≥ 1000 µW/cm² pada 1 m dengan white light ≤ 50 fc"]', 2,
   'Per ASTM E1444, UV-A minimal 1000 µW/cm² diukur pada jarak ~38 cm (15 in) dari permukaan, dan ambient white light di area inspeksi fluorescent maksimal sekitar 2 fc (≈ 20 lux) agar kontras indikasi memadai.', 'Process Control', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 4 — Field Strength Calculation (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Konsep Field Strength & Tangential Field', '{"slides":[{"heading":"Mengapa field strength dihitung","body":"Part yang under-magnetized gagal membentuk leakage field yang cukup sehingga indikasi tidak terbentuk; sebaliknya yang over-magnetized menyebabkan furring (akumulasi partikel non-relevant di sepanjang sudut/edge) dan masking indikasi halus. Level II tidak boleh menebak arus — wajib menghitung atau memverifikasi tangential field strength. Target praktis untuk continuous wet method per ASTM E1444/E709 adalah tangential field 30-60 Gauss (2.4-4.8 kA/m) di permukaan, diverifikasi dengan Hall-probe Gaussmeter atau artificial-flaw shim (QQI)."},{"heading":"Tangential field vs applied current","body":"Yang membentuk indikasi adalah komponen tangential (sejajar permukaan) dari magnetic field, bukan arus itu sendiri. Arus hanya parameter proxy yang kita kontrol. Geometri part, permeability material, dan teknik (circular vs longitudinal) menentukan konversi arus menjadi tangential field. Karena itu rumus amp-turn / amperage adalah titik awal (starting point), lalu divalidasi dengan QQI shim atau Hall-probe Gaussmeter pada lokasi kritis."},{"heading":"Satuan & konversi","body":"Field strength H dinyatakan dalam Oersted (cgs) atau A/m (SI); flux density B dalam Gauss (cgs) atau Tesla (SI). Konversi: 1 Tesla = 10,000 Gauss; 1 Oersted = 1000/(4π) ≈ 79.58 A/m; di udara 1 Oe menghasilkan kira-kira 1 Gauss. Level II harus nyaman bolak-balik: 45 Gauss tangential di udara ≈ 45 Oe ≈ 3,581 A/m ≈ 3.58 kA/m, masih di dalam window 30-60 G."},{"heading":"Metode verifikasi lapangan","body":"Tiga alat utama: (1) Gaussmeter Hall-effect probe untuk membaca tangential field langsung di permukaan part; (2) QQI/shim artificial flaw — jika indikasi shim terbentuk jelas, berarti besar field dan arah magnetisasi memadai; (3) Pie gauge / centering ring untuk mengecek arah field secara cepat (indikator arah, bukan besar field). Hitungan amp-turn memberi setting awal, sedangkan alat verifikasi mengkonfirmasi bahwa setting nyata menghasilkan field cukup pada part spesifik."}]}', 440, NULL),
  (2, 'reading', 'Circular Magnetization — Head Shot, Central Conductor & Prod', '{"slides":[{"heading":"Head shot (direct circular)","body":"Untuk magnetisasi sirkular dengan mengalirkan arus langsung lewat part (head shot), rule praktis ASTM E1444 adalah 300-800 A per inch outside diameter (OD), umumnya mulai ~500 A/inch lalu disesuaikan dengan QQI/shim. Contoh: poros baja solid OD 2 inch → 500 × 2 = 1,000 A (range 300-800 A/in → 600-1,600 A). Field sirkular tegak lurus arah arus dan mendeteksi diskontinuitas longitudinal (sejajar sumbu/arah arus)."},{"heading":"Central conductor","body":"Untuk part berlubang (pipa, ring, hollow shaft), masukkan conductor di tengah lubang dan alirkan arus; field sirkular terbentuk di permukaan dalam (ID) dan luar (OD) part tanpa kontak listrik sehingga tidak ada risiko arc burn pada part. Centered conductor memberi coverage merata keliling penuh sekali shot. Offset conductor (menyentuh ID, teknik distributed/multiple-pass) hanya efektif pada sektor terbatas sehingga butuh beberapa rotasi posisi."},{"heading":"Central conductor — perhitungan & coverage","body":"Centered central conductor: besar arus diperlakukan seperti head-shot pada total diameter part — gunakan 300-800 A/inch (mulai ~500) berdasarkan OD untuk memastikan field cukup di permukaan luar, lalu verifikasi dengan QQI di OD. Contoh: ring ID 4 inch, OD 6 inch, conductor centered → basis OD 6 inch (500 × 6 = 3,000 A awal), konfirmasi shim di OD. Offset/distributed: bila conductor menempel ID, satu shot hanya menginspeksi efektif sektor ≈4× diameter conductor (dihitung dari titik kontak ke kedua sisi); putar part beberapa kali untuk full circumferential coverage."},{"heading":"Prod technique","body":"Prods menghasilkan field sirkular lokal di antara dua titik kontak. Aturan amperage prod per ASTM E709/E1444: 90-110 A per inch spacing untuk material thickness < 0.75 inch (3/4\"), dan 100-125 A per inch spacing untuk thickness ≥ 0.75 inch. Prod spacing dijaga 2-8 inch (jangan < 2\" agar field tidak terlalu terkonsentrasi/over di antara prod; jangan > 8\" agar field di tengah tidak terlalu lemah). Contoh: pelat tebal 1 inch, spacing 6 inch → 125 × 6 = 750 A. Risiko utama: arc burn — jaga kontak prod baik dan jangan mengalirkan arus saat lift atau kontak buruk."}]}', 460, NULL),
  (3, 'reading', 'Longitudinal Magnetization — Coil & Ampere-Turns', '{"slides":[{"heading":"Coil menghasilkan field longitudinal","body":"Part di dalam coil mendapat field longitudinal (sejajar sumbu coil), yang mendeteksi diskontinuitas transverse (tegak lurus sumbu part). Parameter kunci adalah Ampere-Turns (NI) = jumlah lilitan (N) × arus (I). Coil 5-turn pada 1,000 A menghasilkan 5,000 ampere-turns. Efektivitas tergantung L/D ratio part (panjang dibagi diameter atau dimensi penampang efektif) dan fill factor (rasio luas penampang part terhadap luas dalam coil)."},{"heading":"Low fill-factor formula","body":"Low fill factor (luas penampang part < 10% luas dalam coil), part diletakkan dekat dinding dalam coil (offset): NI = 45,000 / (L/D). Untuk part diletakkan di tengah/sumbu coil (centered): NI = 43,000 × R / (6(L/D) − 5), dengan R = radius dalam coil (inch). L/D harus dalam range 2-15; jika L/D < 2 gunakan L/D = 2 (kurang efektif, perlu teknik tambahan); jika L/D > 15 gunakan L/D = 15."},{"heading":"High fill-factor formula","body":"High fill factor (luas penampang part > 50% luas dalam coil, mis. part dililit rapat dengan cable/coil): NI = 35,000 / (L/D + 2). Untuk intermediate fill factor (10%-50%), lakukan interpolasi linear antara hasil low fill dan high fill berdasarkan rasio luas penampang. Kecuali rumus centered low-fill di atas, semua formula mengasumsikan part diletakkan dekat dinding dalam coil."},{"heading":"Koreksi L/D untuk part pendek-gemuk","body":"Untuk part dengan L/D rendah (pendek-gemuk), perpanjang magnetic path dengan menambah pole pieces (ferromagnetic extensions) atau menempatkan part di antara dua part identik agar L efektif bertambah dan L/D naik. Untuk part tidak silindris, hitung D efektif = perimeter penampang ÷ π (pendekatan), atau gunakan diagonal terpanjang penampang. Quick-break (fast decay) circuit membantu distribusi residual field longitudinal lebih merata; selalu verifikasi hasil akhir dengan QQI/shim."}]}', 500, NULL),
  (4, 'reading', 'Worked Example & Verifikasi', '{"slides":[{"heading":"Contoh terhitung — coil low fill factor","body":"Diketahui: shaft baja panjang L = 10 inch, diameter D = 2 inch, diinspeksi dalam coil 5-turn, part dekat dinding coil (low fill factor, offset). Langkah 1: L/D = 10/2 = 5 (dalam range 2-15, OK). Langkah 2: NI = 45,000 / (L/D) = 45,000 / 5 = 9,000 ampere-turns. Langkah 3: I = NI / N = 9,000 / 5 = 1,800 A. Set coil pada 1,800 A, 5 turn. Verifikasi QQI: bila indikasi shim lemah, naikkan arus bertahap dan dokumentasikan."},{"heading":"Contoh terhitung — high fill factor","body":"Part yang sama (L/D = 5) tapi dililit rapat dalam cable wrap (high fill factor). NI = 35,000 / (L/D + 2) = 35,000 / (5 + 2) = 35,000 / 7 = 5,000 ampere-turns. Dengan coil/wrap 5-turn: I = 5,000 / 5 = 1,000 A. Perhatikan: high fill factor butuh arus jauh lebih kecil (1,000 A vs 1,800 A) karena magnetic coupling part-coil lebih efisien. Selalu nyatakan asumsi fill factor di dalam written procedure."},{"heading":"Contoh terhitung — prod & head shot","body":"Prod pada pelat tebal 1.5 inch (≥ 0.75\"), spacing 5 inch: I = 125 A/inch × 5 inch = 625 A. Head shot poros solid OD 3 inch: I = 500 A/inch × 3 = 1,500 A (range 300-800 A/inch → 900-2,400 A). Untuk multi-directional, field circular dan longitudinal di-balance sehingga QQI three-bar / star shim menunjukkan indikasi di semua arah secara bersamaan — bukan sekadar memenuhi rumus masing-masing arah."},{"heading":"Dari hitungan ke acceptance","body":"Rumus = starting point; QQI/shim dan Gaussmeter = bukti aktual. Written procedure harus mencatat: arus aktual, jumlah turn, fill factor yang diasumsikan, metode verifikasi, dan pembacaan tangential field (window 30-60 G). Jika tangential field di luar window, sesuaikan arus dan dokumentasikan. Setelah inspeksi, lakukan demagnetization dan verifikasi residual field memenuhi spec (umumnya ≤ 3 G); residual tinggi mengganggu machining, welding, dan instrumentasi sekitar."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Field Strength Calculation', '{"description":"8 soal perhitungan ampere-turns, prod amperage, central conductor, dan field strength Level II.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 4 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Untuk coil dengan low fill factor dan part diletakkan dekat dinding coil (offset), rumus ampere-turns yang benar adalah:',
   '["NI = 35,000 / (L/D + 2)","NI = 45,000 / (L/D)","NI = 43,000 × R / (6(L/D) − 5)","NI = 500 × OD"]', 1,
   'Low fill factor (luas penampang part < 10% luas dalam coil), part offset dekat dinding: NI = 45,000/(L/D). Rumus 35,000/(L/D+2) untuk high fill factor; 43,000×R/(6(L/D)−5) untuk low fill factor centered; 500×OD adalah head shot circular.', 'Coil / Ampere-Turns', 'medium'),
  ('Shaft L = 12 inch, D = 3 inch diinspeksi dalam coil 4-turn dengan low fill factor (offset). Berapa arus yang harus di-set?',
   '["2,812 A","11,250 A","2,250 A","9,000 A"]', 0,
   'L/D = 12/3 = 4. NI = 45,000/(L/D) = 45,000/4 = 11,250 ampere-turns. I = NI/N = 11,250/4 = 2,812.5 A ≈ 2,812 A. (11,250 A adalah NI bukan arus; 2,250 A salah hitung.)', 'Coil / Ampere-Turns', 'hard'),
  ('Untuk prod technique pada material dengan tebal ≥ 0.75 inch (3/4"), amperage yang direkomendasikan ASTM E709/E1444 adalah:',
   '["90-110 A per inch spacing","300-800 A per inch OD","100-125 A per inch spacing","35,000 A per inch"]', 2,
   'Prod amperage: 90-110 A/inch spacing untuk tebal < 0.75", dan 100-125 A/inch spacing untuk tebal ≥ 0.75". 300-800 A/inch OD adalah untuk head shot (direct circular).', 'Prod Technique', 'medium'),
  ('Pelat baja tebal 1 inch diinspeksi dengan prods berjarak (spacing) 6 inch. Arus yang sesuai memakai 125 A/inch adalah:',
   '["540 A","750 A","600 A","1,250 A"]', 1,
   'Tebal 1" ≥ 0.75" → gunakan 100-125 A/inch. Pada 125 A/inch: 125 × 6 = 750 A. (90 A/inch hanya berlaku untuk tebal < 0.75".)', 'Prod Technique', 'easy'),
  ('Komponen medan yang sebenarnya menghasilkan indikasi MT dan menjadi target window 30-60 Gauss adalah:',
   '["Applied current density dalam part","Residual flux density setelah demagnetisasi","Tangential field strength di permukaan","Coercive force material"]', 2,
   'Indikasi terbentuk dari leakage field yang dihasilkan komponen tangential (sejajar permukaan) field. Window 30-60 G mengacu pada tangential field, diukur dengan Hall-probe Gaussmeter atau diverifikasi via QQI/shim. Arus hanya proxy yang dikontrol.', 'Field Concepts', 'medium'),
  ('Part dengan L/D = 5 dililit rapat dalam cable wrap (high fill factor) menggunakan coil 5-turn. Berapa arus yang dibutuhkan?',
   '["1,800 A","9,000 A","1,000 A","5,000 A"]', 2,
   'High fill factor: NI = 35,000/(L/D+2) = 35,000/(5+2) = 35,000/7 = 5,000 ampere-turns. I = NI/N = 5,000/5 = 1,000 A. (1,800 A adalah hasil low fill factor untuk L/D=5; 5,000 A adalah NI bukan arus.)', 'Coil / Ampere-Turns', 'hard'),
  ('Jika L/D part yang dihitung adalah 18, nilai L/D yang dipakai dalam rumus ampere-turns adalah:',
   '["18, dipakai apa adanya","15, karena dibatasi maksimum 15","2, karena dibatasi minimum","9, yaitu setengahnya"]', 1,
   'Rumus ampere-turns valid untuk L/D antara 2 dan 15. Jika L/D > 15 gunakan 15; jika L/D < 2 gunakan 2. L/D = 18 di-cap menjadi 15.', 'Coil / Ampere-Turns', 'medium'),
  ('Pada magnetisasi sirkular dengan central conductor offset (menempel ID part berlubang), kapan coverage keliling penuh tercapai?',
   '["Selalu — satu shot mencakup seluruh keliling part","Hanya sektor efektif ≈4× diameter conductor per shot, sehingga part harus diputar beberapa posisi","Hanya jika arus dinaikkan 2×","Tidak pernah — teknik offset dilarang oleh ASTM"]', 1,
   'Central conductor adalah teknik magnetisasi sirkular. Offset (distributed) conductor hanya efektif menginspeksi sektor ≈4× diameter conductor di sekitar titik kontak per shot; part harus diputar beberapa kali untuk full circumferential coverage. Centered conductor memberi coverage merata dalam satu shot.', 'Central Conductor', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 5 — Specialty Techniques (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Underwater MT — Subsea Inspection', '{"slides":[{"heading":"Konteks aplikasi subsea","body":"Underwater MT dipakai untuk inspeksi struktur offshore: jacket node weld, riser, conductor, mooring chain, dan subsea pipeline tie-in. Karena akses ROV/diver mahal, MT dipilih karena cepat dan toleran terhadap surface prep yang lebih ringan dibanding PT. Standar pemandu utama adalah AWS D3.6M (Underwater Welding Code) untuk acceptance, dengan ASTM E709 sebagai general guide teknik MT. Level II harus paham bahwa wet MT bawah air punya kendala unik: visibilitas rendah, arus (current), dan kehilangan kontras."},{"heading":"Wet fluorescent vs visible underwater","body":"Di kedalaman dangkal dengan ambient light, kontras particle visible (hitam/merah) terhadap weld gelap buruk. Solusinya adalah wet fluorescent dengan UV-A waterproof lamp (365 nm) dan diver memakai amber/UV viewing filter. Particle disuplai sebagai pre-mixed bath dalam squeeze-bottle aplikator yang tahan tekanan; dry particle jelas tidak bisa dipakai di air. Carrier khusus dengan wetting agent diperlukan agar particle tidak langsung tersapu arus sebelum membentuk indikasi."},{"heading":"Encapsulated yoke & equipment","body":"Yoke bawah air umumnya menggunakan permanent magnet atau AC/DC electromagnet ber-housing kedap (encapsulated, IP68, sering oil-filled untuk kompensasi tekanan). AC electromagnet sering disukai karena menghasilkan surface field yang kuat untuk crack permukaan dan AC magnetic agitation membantu mobilitas particle di air. Lift test tetap wajib: AC yoke minimal 4,5 kg (10 lb) dan DC yoke 18 kg (40 lb) pada spasi kaki (leg spacing) maksimum yang dipakai, diverifikasi di permukaan sebelum dive."},{"heading":"Prosedur & dokumentasi diver","body":"Karena diver/ROV adalah ''mata'' inspektor Level II di topside, prosedur harus eksplisit: cleaning dengan wire brush atau water jet, magnetisasi dua arah berurutan (longitudinal lalu transverse, beda ~90 derajat untuk meng-cover discontinuity segala orientasi), perekaman video real-time, dan marking indikasi pakai cat bawah air. CCTV dan voice-link memungkinkan Level II topside menginterpretasi langsung. Demagnetisasi sering di-skip jika komponen tetap di laut, tetapi residual field harus dicatat bila ada repair welding berikutnya."}]}', 460, NULL),
  (2, 'reading', 'Cryogenic & Low-Temperature MT', '{"slides":[{"heading":"Mengapa low-temp MT diperlukan","body":"Aplikasi cryogenic muncul pada LNG storage tank (operasi sekitar -162 derajat C), liquid nitrogen/oxygen vessel, dan weld 9% Ni steel yang kadang harus diinspeksi mendekati suhu kerja. Tantangan utama: bath konvensional (carrier oil atau air) akan membeku, dan kondensasi/ice film menutup permukaan sehingga particle tidak mencapai metal. Level II harus memilih teknik dan material yang masih fungsional pada suhu rendah."},{"heading":"Catatan feromagnetisme & material","body":"Ingat: hanya material feromagnetik yang bisa di-MT. Banyak komponen cryogenic dibuat dari austenitic stainless (300-series) yang non-magnetik sehingga TIDAK bisa di-MT — gunakan PT atau ET. Namun 9% Ni steel dan beberapa martensitic/duplex tetap feromagnetik dan valid untuk MT. Pada suhu sangat rendah, permeability dan retentivity dapat sedikit berubah, tetapi efek dominan tetap masalah carrier yang membeku, bukan hilangnya sifat magnet baja feromagnetik."},{"heading":"Teknik praktis suhu rendah","body":"Untuk suhu di bawah titik beku air, gunakan dry magnetic particle method dengan continuous magnetization, karena dry powder tidak membeku dan mobilitasnya baik pada permukaan kering dingin. Bila wet method wajib, pakai carrier non-aqueous low-pour-point (petroleum distillate khusus) yang tetap cair di bawah 0 derajat C. Permukaan harus bebas frost/ice — keringkan dengan warm air atau biarkan komponen ''sweat'' lalu lap. Hindari heating berlebih yang menimbulkan thermal shock pada weld cryogenic."},{"heading":"QC & keterbatasan","body":"Verifikasi flux dengan QQI/shim atau Pie gauge (lebih reliabel daripada sekadar Gauss meter), dan lift test, idealnya pada kondisi yang merepresentasikan suhu aktual. Field indicator tangential biasanya menargetkan sekitar 30 G, tetapi shim/QQI tetap acuan utama. Dokumentasikan suhu komponen pada laporan; di luar range yang divalidasi, prosedur tidak boleh diklaim. Contrast aid (white background paint) tetap dipakai. Untuk kasus suhu tinggi sebaliknya, ingat batas WET method sekitar 57 derajat C (carrier menguap); dry method justru toleran hingga sekitar 315 derajat C dengan high-temperature dry particle khusus."}]}', 440, NULL),
  (3, 'reading', 'AC vs DC — Trade-off Mendalam', '{"slides":[{"heading":"Skin effect — kunci pemahaman AC","body":"Arus bolak-balik (AC) terkonsentrasi di permukaan konduktor (skin effect), sehingga AC menghasilkan magnetic flux yang sangat kuat tepat di permukaan tetapi penetrasi dangkal — hanya orde sepersepuluhan mm. Karena itu AC adalah pilihan terbaik untuk surface-breaking discontinuity (fatigue crack, grinding crack, weld toe crack). DC (atau full-wave/half-wave rectified DC) menghasilkan flux yang lebih dalam, sehingga lebih sensitif terhadap subsurface discontinuity. Namun deteksi subsurface dengan particle realistis tetap dangkal — umumnya hanya defek yang relatif dekat permukaan (orde 1-3 mm, tergantung ukuran defek, amperage, dan geometri)."},{"heading":"Particle mobility & residual","body":"AC memberi ''magnetic agitation'' — medan yang berosilasi 50/60 Hz menggetarkan particle sehingga mereka bergulir mencari leakage field dan membentuk indikasi yang lebih tajam, sangat membantu dengan dry powder. DC tidak punya agitation ini tetapi menghasilkan residual field yang lebih tinggi, sehingga DC cocok untuk teknik residual dan biasanya butuh demagnetisasi lebih agresif setelahnya. Half-wave DC (HWDC) menggabungkan agitation pulsatil dengan penetrasi sedang — favorit untuk dry powder pada permukaan cast/forging kasar."},{"heading":"Demagnetisasi & frekuensi","body":"Demagnetisasi paling efektif dengan AC karena pembalikan polaritas alami 50/60 Hz; komponen ditarik perlahan melalui koil AC atau amplitudo diturunkan bertahap (AC decay). Untuk DC, demag butuh DC reversing dengan step-down current secara progresif — lebih lambat dan rumit, tetapi perlu untuk material tebal karena AC sulit menjangkau residual di dalam. Residual field setelah selesai harus diverifikasi: target umum di bawah 3 G (atau sesuai spec), khususnya untuk komponen yang akan di-machining, di-las ulang, atau dekat sensor elektronik."},{"heading":"Memilih waveform per aplikasi","body":"Aturan praktis Level II: AC untuk crack permukaan dan komponen yang harus mudah didemag; HWDC + dry powder untuk weld, casting, forging dengan crack permukaan/dangkal pada permukaan kasar; FWDC (full-wave DC) + wet fluorescent untuk subsurface dan inspeksi presisi di lab; permanent magnet/battery yoke untuk lapangan tanpa listrik (tetapi tidak bisa demag dan field strength tidak adjustable). Selalu validasi pilihan dengan QQI/shim atau Pie gauge dan dokumentasikan rasional pemilihan dalam prosedur tertulis."}]}', 480, NULL),
  (4, 'reading', 'Specialty Equipment & Field Applications', '{"slides":[{"heading":"Multidirectional & specialty bench","body":"Untuk produksi tinggi, specialty bench multidirectional menggabungkan head shot (circular) dan coil shot (longitudinal) yang di-fire bergantian dengan cepat sehingga seolah simultan; particle harus tetap mobile (continuous method) saat semua shot berlangsung agar indikasi segala arah terbentuk. Verifikasi balance medan dengan QQI shim di beberapa lokasi karena satu arah yang terlalu kuat dapat menutupi (mask) indikasi arah lain. Penetapan parameter dan sign-off teknik multidirectional adalah ranah Level II."},{"heading":"Central conductor & komponen berlubang","body":"Untuk pipa, ring, dan komponen berlubang, central conductor (rod/cable melewati bore) menghasilkan circular field melingkari ID dan OD tanpa kontak listrik langsung — menghindari arc burn. Aturan praktis bila conductor di-offset menempel ke ID: tiap posisi conductor hanya menginspeksi efektif sekitar 4x diameter conductor diukur sepanjang keliling part dari titik kontak, sehingga dibutuhkan multiple indexed shots dengan overlap untuk cakupan penuh keliling. Untuk menaikkan field, cable dapat dililit beberapa turn (amp-turn naik)."},{"heading":"Aplikasi lapangan khusus","body":"Prod technique (90-125 A per inch spacing) berguna untuk area besar tanpa bench, tetapi risiko arc burn tinggi sehingga dilarang pada material kritis seperti aerospace alloy dan high-strength steel yang sensitif terhadap heat-affected damage. Flexible cable wrap mengubah komponen apa pun menjadi koil improvisasi untuk longitudinal field di lapangan. Untuk in-service hot weld, ingat batas WET method sekitar 57 derajat C; gunakan dry method yang toleran lebih tinggi, dengan high-temp dry particle bila perlu (rating umumnya hingga sekitar 315 derajat C)."}]}', 420, NULL),
  (5, 'quiz', 'Mini-quiz — Specialty Techniques', '{"description":"7 soal tentang underwater MT, cryogenic MT, dan trade-off AC vs DC pada level teknis Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 5 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa AC (alternating current) lebih unggul daripada DC untuk mendeteksi surface-breaking crack pada MT?',
   '["AC menembus jauh lebih dalam ke bawah permukaan daripada DC","Skin effect membuat flux AC terkonsentrasi di permukaan, menguatkan leakage field crack permukaan","AC menghasilkan residual field yang jauh lebih tinggi sehingga indikasi lebih kuat","AC tidak memerlukan particle untuk membentuk indikasi"]', 1,
   'Karena skin effect, arus AC terkonsentrasi di permukaan konduktor, sehingga flux magnetik paling kuat tepat di permukaan dan optimal untuk surface-breaking discontinuity. Penetrasi AC justru dangkal; DC yang lebih sensitif untuk subsurface.', 'AC vs DC', 'easy'),
  ('Komponen cryogenic dari austenitic stainless steel 304 perlu diperiksa retak permukaan. Metode yang tepat adalah?',
   '["MT dengan dry powder karena tidak membeku","MT dengan wet fluorescent dan UV lamp","PT atau ET karena 304 bersifat non-magnetik (tidak feromagnetik)","MT dengan central conductor untuk field melingkar"]', 2,
   'Austenitic stainless 300-series umumnya non-magnetik (non-feromagnetik), sehingga MT tidak berlaku. Gunakan PT (penetrant) atau ET (eddy current). MT hanya valid pada material feromagnetik seperti 9% Ni steel.', 'Cryogenic MT', 'medium'),
  ('Mengapa wet fluorescent lebih dipilih daripada visible particle pada underwater MT di perairan dengan ambient light?',
   '["Kontras particle visible terhadap weld gelap buruk; fluorescent dengan UV jauh lebih terlihat","Particle fluorescent lebih murah daripada particle visible","Visible particle tidak bisa dibasahi oleh air laut","Fluorescent tidak memerlukan magnetisasi"]', 0,
   'Di bawah air dengan visibilitas dan kontras rendah, particle visible (hitam/merah) terhadap weld gelap sulit dilihat. Wet fluorescent dengan UV-A waterproof lamp dan viewing filter memberi kontras jauh lebih tinggi.', 'Underwater MT', 'medium'),
  ('Mengapa AC adalah pilihan terbaik untuk demagnetisasi komponen tipis-menengah setelah MT?',
   '["AC menghasilkan medan searah yang menetap di material","AC tidak menginduksi residual field sama sekali","Pembalikan polaritas alami 50/60 Hz memungkinkan field di-cycle dan diturunkan bertahap (AC decay)","AC hanya bekerja pada material non-feromagnetik"]', 2,
   'AC membalik polaritas 50/60 Hz secara alami, sehingga komponen dapat ditarik perlahan melalui koil atau amplitudo diturunkan progresif (AC decay) untuk meng-cycle domain magnet ke residual mendekati nol. Demag DC butuh DC reversing step-down yang lebih rumit, namun perlu untuk penampang tebal.', 'AC vs DC', 'medium'),
  ('Pada underwater MT, mengapa AC electromagnet yoke sering lebih disukai daripada DC yoke?',
   '["AC yoke jauh lebih ringan sehingga lift test tidak diperlukan","DC yoke tidak bisa di-encapsulate untuk kedap air","AC menembus lebih dalam sehingga cocok untuk subsurface bawah air","AC memberi surface field kuat dan magnetic agitation yang membantu mobilitas particle di air"]', 3,
   'AC menghasilkan flux permukaan yang kuat untuk crack permukaan dan magnetic agitation yang membantu particle bergerak mencari leakage field meski di lingkungan air berarus. Lift test tetap wajib (AC yoke min 4,5 kg / 10 lb).', 'Underwater MT', 'hard'),
  ('Untuk inspeksi crack permukaan pada casting/forging berpermukaan kasar di lapangan, kombinasi waveform dan media yang paling tepat adalah?',
   '["FWDC dengan wet fluorescent","Half-wave DC (HWDC) dengan dry magnetic powder","AC dengan wet visible bath","Permanent magnet dengan central conductor"]', 1,
   'HWDC memberi penetrasi sedang plus agitation pulsatil yang membuat dry powder bergulir mencari indikasi, ideal untuk permukaan kasar casting/forging dengan crack permukaan hingga dangkal. Itulah kombinasi klasik untuk aplikasi ini.', 'AC vs DC', 'hard'),
  ('Saat melakukan MT pada permukaan in-service yang panas (>57 derajat C), pernyataan mana yang BENAR mengenai batas suhu metode?',
   '["Dry powder otomatis menghilangkan ice film pada permukaan","57 derajat C adalah batas WET method (carrier menguap); dry method toleran lebih tinggi, high-temp dry particle hingga sekitar 315 derajat C","Baik wet maupun dry method sama-sama dibatasi 57 derajat C","Di atas 57 derajat C baja kehilangan sifat feromagnetik sehingga MT tidak bisa dilakukan"]', 1,
   'Batas ~57 derajat C (135 derajat F) berlaku untuk WET method karena carrier menguap. Dry powder method jauh lebih toleran terhadap panas; high-temperature dry particle khusus berfungsi hingga sekitar 315 derajat C. Curie point baja jauh di atas itu (~770 derajat C), jadi material belum kehilangan feromagnetisme pada suhu ini.', 'Cryogenic MT', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 6 — Indication Sizing & Evaluation (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'True vs apparent indication — dasar sizing', '{"slides":[{"heading":"Indikasi bukan ukuran fisik diskontinuitas","body":"Pada MT, lebar akumulasi serbuk magnetik (build-up) hampir selalu LEBIH BESAR dari lebar fisik crack. Magnetic leakage field melebar di atas permukaan, sehingga lebar indikasi tidak boleh dipakai langsung sebagai lebar cacat. Level II wajib memahami bahwa parameter yang diukur untuk acceptance adalah PANJANG indikasi (length of accumulation), bukan lebar. Width hanya dipakai untuk klasifikasi: linear jika length > 3 x width, rounded jika length <= 3 x width (per ASME V Article 7 / Section VIII App 6)."},{"heading":"Faktor yang melebarkan indikasi","body":"Field strength berlebih (over-magnetization) memperkuat leakage dan menebalkan build-up sehingga crack halus terlihat seolah lebar. Particle berlebih (excess applied bath) menutupi detail. Continuous method (current ON saat aplikasi serbuk) menghasilkan indikasi lebih lebar dan lebih sensitif dibanding residual method. Karena itu sizing harus dilakukan pada kondisi field tangential terverifikasi (30-60 G / 3-6 mT), bukan pada field maksimum yang membuat semua indikasi tampak besar."},{"heading":"Verifikasi field sebelum sizing","body":"Sebelum menilai ukuran, Level II memverifikasi adequacy field dengan tangential-field (Hall-effect) Gauss meter, target 30-60 G (3-6 mT) di permukaan, atau dengan QQI/shim artificial flaw. Lift test BUKAN untuk sizing maupun verifikasi field kuantitatif — hanya pemeriksaan kemampuan angkat yoke (AC 4.5 kg / 10 lb; DC atau half-wave DC 18 kg / 40 lb pada spasi kaki maksimum). Sizing yang dilakukan pada field tidak terverifikasi tidak sah karena lebar/ketebalan build-up berubah terhadap kuat medan."}]}', 460, NULL),
  (2, 'reading', 'Akurasi pengukuran panjang & lebar', '{"slides":[{"heading":"Mengukur panjang indikasi","body":"Panjang diukur dengan steel scale atau caliper digital sepanjang sumbu indikasi yang berkelanjutan (continuous accumulation), pada kondisi cahaya terkontrol dan setelah field terverifikasi. Untuk indikasi yang segaris/sejajar, terapkan aturan summing: per konvensi ASME (Section VIII App 6 / E1444), indikasi yang segaris dan dipisah gap <= 1.6 mm (1/16 in) edge-to-edge diperlakukan sebagai SATU indikasi tunggal dan panjangnya dijumlahkan termasuk gap. Ini krusial karena indikasi rejectable bisa keliru lolos bila tiap segmen diukur terpisah."},{"heading":"Aturan klasifikasi linear vs rounded","body":"Linear indication: length > 3 x width. Rounded indication: length <= 3 x width (circular atau elliptical). Klasifikasi menentukan acceptance criteria yang berbeda. Per ASME VIII Div 1 App 6: hanya indikasi dengan dimensi > 1.6 mm (1/16 in) yang dianggap RELEVANT; SEMUA relevant linear indication adalah rejectable (tidak ada batas panjang linear yang acceptable); relevant rounded > 5 mm (3/16 in) rejectable; serta empat atau lebih relevant rounded dalam satu garis dengan jarak edge-to-edge <= 1.6 mm (1/16 in) = rejectable. Salah klasifikasi langsung mengubah keputusan accept/reject."},{"heading":"Relevant vs non-relevant vs false","body":"False indication: bukan leakage field nyata (mis. serbuk tertahan di scale/karat, fingerprint, magnetic writing, holding di perubahan geometri). Non-relevant: leakage nyata tapi dari fitur geometri/desain (perubahan section, keyway, threaded area, dissimilar permeability di las atau fusion line). Relevant: dari diskontinuitas aktual. Hanya relevant indication yang diukur dan dievaluasi terhadap acceptance criteria. Level II membedakan dengan re-magnetisasi arah berbeda, demagnetisasi/cleaning lalu re-inspeksi, dan mencocokkan terhadap geometri benda."},{"heading":"Sumber error pengukuran","body":"Build-up width melebih-lebihkan ukuran (ukur dari inti/tepi terang indikasi, bukan halo serbuk). Parallax pada scale, sudut pandang, dan kondisi pencahayaan mempengaruhi akurasi: white light >= 1000 lux untuk visible/colour-contrast; UV-A >= 1000 microW/cm2 di permukaan dengan ambient white light <= 20 lux untuk fluorescent. Best practice: ukur di bawah kondisi cahaya terkontrol, catat orientasi, dan ulangi pada arah magnetisasi tegak lurus untuk mengkonfirmasi panjang sebenarnya."}]}', 480, NULL),
  (3, 'reading', 'Estimasi kedalaman & karakterisasi', '{"slides":[{"heading":"MT tidak mengukur kedalaman secara langsung","body":"MT adalah metode permukaan/dekat-permukaan; ia TIDAK memberikan kedalaman kuantitatif seperti UT atau ECT. Kedalaman hanya diestimasi secara kualitatif dari karakter indikasi. Level II wajib jujur menyatakan keterbatasan ini di report: depth ditandai sebagai estimasi, dan untuk keputusan repair true depth diverifikasi dengan UT atau teknik grind-and-recheck, bukan diklaim dari MT saja."},{"heading":"Indikator kualitatif kedalaman","body":"Crack yang lebih dalam umumnya menghasilkan leakage field lebih kuat sehingga build-up serbuk lebih TINGGI, lebih TEBAL, lebih tajam/terdefinisi, dan cenderung bertahan saat field diturunkan. Indikasi dangkal/permukaan menghasilkan build-up tipis dan mudah hilang saat field dikurangi. Subsurface discontinuity menghasilkan indikasi yang lebih fuzzy, lebar, dan kurang tegas (broad dan diffuse) dibanding surface crack yang sharp dan rapat."},{"heading":"Surface vs subsurface dan batas deteksi","body":"MT hanya andal mendeteksi subsurface hingga kira-kira 6 mm (1/4 in) di bawah permukaan pada kondisi optimal, dan hanya untuk diskontinuitas yang relatif besar. DC dan half-wave DC memberikan penetrasi lebih dalam (deteksi subsurface lebih baik) sedangkan AC terkonsentrasi di permukaan akibat skin effect — AC justru lebih unggul untuk surface crack halus. Pemilihan jenis arus karena itu mempengaruhi apa yang terdeteksi dan bagaimana indikasi tampak."},{"heading":"Grinding/blending untuk verifikasi & disposisi","body":"Untuk konfirmasi kedalaman dapat dipakai teknik lokal grind-and-recheck: material digerinda sedikit, area di-MT ulang; jika indikasi hilang, cacat dangkal dan dapat di-blend dalam batas wall thickness/code; jika tetap muncul, cacat lebih dalam dan butuh evaluasi engineering atau weld repair. Setiap iterasi harus tetap dalam minimum wall / corrosion allowance. Hasil estimasi kedalaman dan tindakan didokumentasikan di report yang ditandatangani Level II."}]}', 480, NULL),
  (4, 'reading', 'Evaluasi terhadap acceptance criteria & disposisi', '{"slides":[{"heading":"Memilih acceptance code yang benar","body":"Evaluasi selalu mengacu pada code/spec yang ditentukan kontrak: ASME V Article 7 (metode) dipasangkan dengan acceptance dari ASME VIII Div 1 App 6 atau ASME B31.x; AWS D1.1 untuk struktur baja (statically vs cyclically loaded — pada edisi 2020 di Clause 6/Table 6.1, pada edisi 2025 dipindah ke Clause 8/Table 8.1); ASTM E1444/E709 sebagai metode, dan ISO 9934 / ISO 23278 untuk acceptance level (mis. ISO 23278 level 1/2/3). Level II memilih criteria yang tepat SEBELUM mengukur — bukan setelah."},{"heading":"Contoh angka acceptance","body":"ASME VIII App 6: indikasi relevant adalah yang berdimensi > 1.6 mm (1/16 in); semua relevant linear indication = reject; relevant rounded > 5 mm (3/16 in) = reject; empat atau lebih relevant rounded dalam garis dengan jarak edge-to-edge <= 1.6 mm = reject. AWS D1.1 (statically loaded): crack apapun = reject; linear/rounded dievaluasi terhadap ukuran dan distribusi pada tabel visual yang berlaku. ISO 23278 menyediakan beberapa acceptance level. Karena ambang antar-code berbeda, indikasi yang sama bisa accept di satu code dan reject di code lain — code & edisi wajib dicatat di report."},{"heading":"Keputusan accept / reject / repair","body":"Setelah measure dan classify, Level II membuat disposisi: ACCEPT (memenuhi criteria), REJECT (gagal -> repair atau scrap), atau REPAIR & RE-INSPECT (grind/weld repair lalu MT ulang penuh, termasuk demagnetisasi dan verifikasi residual field). Re-inspeksi setelah repair adalah inspeksi baru lengkap, bukan spot-check. Hanya personnel Level II (atau lebih tinggi) yang berhak menandatangani final accept/reject; Level I tidak boleh sign-off."},{"heading":"Dokumentasi sizing di report","body":"Report wajib mencatat: lokasi (sketch/peta), panjang & klasifikasi tiap relevant indication, orientasi, arah magnetisasi, field strength terverifikasi (G/mT), teknik (wet/dry, fluorescent/visible, continuous/residual, AC/DC/HWDC), code & acceptance level beserta edisi, disposisi, dan estimasi kedalaman bila relevan dengan catatan keterbatasan MT. Demagnetisasi pasca-inspeksi diverifikasi (residual field tipikal <= 3 G / 240 A/m sesuai spec) dan dicatat. Report bertanda tangan Level II adalah quality record yang dapat diaudit."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Indication Sizing & Evaluation', '{"description":"7 soal: pengukuran panjang/lebar, klasifikasi linear vs rounded, summing aturan segaris, estimasi kedalaman kualitatif, verifikasi field, dan disposisi acceptance Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 6 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada evaluasi MT, mengapa lebar build-up serbuk magnetik tidak boleh dipakai langsung sebagai lebar fisik crack?',
   '["Karena leakage field melebar di atas permukaan sehingga build-up lebih lebar dari crack","Karena serbuk selalu lebih sempit dari crack sebenarnya","Karena lebar tidak pernah dapat diukur dengan scale","Karena lebar hanya relevan pada subsurface indication"]', 0,
   'Magnetic leakage field menyebar di atas permukaan, sehingga lebar akumulasi serbuk hampir selalu lebih besar dari lebar fisik crack. Karena itu evaluasi acceptance memakai PANJANG indikasi; lebar hanya untuk klasifikasi linear vs rounded.', 'Indication Sizing', 'easy'),
  ('Sebuah indikasi memiliki panjang 9 mm dan lebar 2 mm. Bagaimana klasifikasinya menurut aturan ASME (linear bila length > 3 x width)?',
   '["Rounded, karena lebar < 3 mm","Non-relevant, karena disebabkan geometri","Linear, karena 9 mm > 3 x 2 mm (6 mm)","False indication, karena rasio terlalu besar"]', 2,
   'Linear bila length > 3 x width. Di sini 9 mm > 3 x 2 mm = 6 mm (rasio L/W = 4.5), jadi linear, dan dievaluasi dengan acceptance criteria untuk linear indication.', 'Classification', 'medium'),
  ('Dua indikasi segaris dipisahkan gap 1.2 mm (kurang dari 1/16 in) edge-to-edge. Menurut konvensi summing ASME (Section VIII App 6 / E1444), bagaimana keduanya dievaluasi?',
   '["Sebagai dua indikasi terpisah, masing-masing diukur sendiri","Diabaikan karena gap menandakan non-relevant","Otomatis reject tanpa pengukuran","Sebagai satu indikasi tunggal dengan panjang dijumlahkan termasuk gap"]', 3,
   'Indikasi segaris yang dipisah gap <= 1.6 mm (1/16 in) edge-to-edge diperlakukan sebagai satu indikasi tunggal dan panjangnya dijumlahkan termasuk gap. Mengukurnya terpisah bisa keliru meloloskan indikasi yang sebenarnya rejectable.', 'Evaluation Rules', 'medium'),
  ('Manakah pernyataan yang BENAR tentang kemampuan MT mengukur kedalaman diskontinuitas?',
   '["MT memberikan kedalaman kuantitatif akurat seperti UT","MT mengukur kedalaman dari lebar build-up secara presisi","MT tidak mengukur kedalaman secara langsung; hanya estimasi kualitatif dari karakter indikasi","MT hanya bisa mengukur kedalaman pada material non-feromagnetik"]', 2,
   'MT adalah metode permukaan/dekat-permukaan dan tidak memberi kedalaman kuantitatif. Kedalaman hanya diestimasi kualitatif (tinggi/ketebalan/ketajaman dan persistensi build-up); verifikasi true depth memakai UT atau grind-and-recheck.', 'Depth Estimation', 'easy'),
  ('Indikasi yang TINGGI, tebal, tajam, dan bertahan saat field diturunkan paling mungkin menandakan apa?',
   '["Crack permukaan yang sangat dangkal","Non-relevant indication dari geometri","False indication dari fingerprint","Diskontinuitas yang relatif lebih dalam (leakage field lebih kuat)"]', 3,
   'Cacat lebih dalam menghasilkan leakage field lebih kuat sehingga build-up lebih tinggi, tebal, tajam, dan bertahan meski field dikurangi. Indikasi dangkal menghasilkan build-up tipis yang mudah hilang saat field diturunkan.', 'Depth Estimation', 'medium'),
  ('Mengapa Level II harus memverifikasi field strength tangential (mis. 30-60 G / 3-6 mT) SEBELUM melakukan sizing indikasi?',
   '["Karena lift test menggantikan semua pengukuran lain","Karena lebar/ketebalan build-up berubah terhadap kuat medan, sehingga field berlebih melebih-lebihkan ukuran","Karena field tinggi selalu menyembunyikan indikasi","Karena Gauss meter mengukur panjang crack secara langsung"]', 1,
   'Build-up serbuk membesar pada over-magnetization, membuat crack halus tampak lebih besar. Sizing yang sah dilakukan pada field tangential terverifikasi (30-60 G / 3-6 mT), bukan pada field maksimum. Lift test hanya cek kemampuan angkat yoke (AC 4.5 kg / DC 18 kg), bukan sizing.', 'Field Verification', 'hard'),
  ('Per ASME VIII Div 1 App 6, manakah pernyataan acceptance yang BENAR untuk relevant indication?',
   '["Linear indication acceptable selama panjangnya <= 1.6 mm","Semua relevant linear indication adalah rejectable; relevant rounded rejectable bila > 5 mm (3/16 in)","Rounded indication selalu rejectable, linear selalu acceptable","Hanya indikasi subsurface yang dievaluasi terhadap acceptance criteria"]', 1,
   'Per ASME VIII App 6, indikasi relevant adalah yang berdimensi > 1.6 mm (1/16 in). Semua relevant linear indication adalah rejectable (tidak ada batas panjang linear yang acceptable), sedangkan relevant rounded acceptable kecuali > 5 mm (3/16 in), atau bila ada empat atau lebih rounded segaris dengan jarak edge-to-edge <= 1.6 mm.', 'Acceptance Criteria', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — MT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
