-- MT-L2 Module 7 — Procedure Development (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi Written Procedure MT', '{"slides":[{"heading":"Kenapa procedure wajib","body":"ASME Section V Article 7 (T-721) mengharuskan setiap pemeriksaan MT dilakukan menurut written procedure yang terdokumentasi. Procedure mengikat semua essential variable supaya hasil reproducible antar operator dan antar shift. Level II adalah yang berwenang menyusun dan me-review procedure, tetapi approval procedure tingkat sistem umumnya kewenangan Level III; Level I hanya menjalankannya. Tanpa procedure yang ter-approve, report MT tidak punya dasar audit."},{"heading":"Elemen wajib (T-721.1.1)","body":"ASME V Article 7 (T-721.1.1) menuntut minimum elemen berikut tercatat: identifikasi part/material & range tebal, magnetizing method (yoke / prod / coil / central conductor / multidirectional), tipe arus (AC / HWDC / FWDC / DC), karakteristik & range arus atau field strength, tipe media (dry powder / wet, fluorescent / visible), surface preparation, teknik aplikasi & timing, lighting requirement, demagnetization, dan acceptance criteria. Sebagian besar elemen ini didefinisikan sebagai essential atau nonessential variable di Tabel T-721 (Mandatory Appendix)."},{"heading":"Essential vs nonessential variable","body":"Essential variable = perubahan yang mengubah hasil/sensitivitas sehingga butuh requalifikasi (mis. ganti dari fluorescent ke visible, turun di bawah range arus minimum, ganti dari continuous ke residual technique, ganti method magnetisasi). Nonessential variable = boleh diubah tanpa requalifikasi tetapi tetap di-update di dokumen (mis. merek peralatan setara, nama operator, nomor halaman). Daftar essential variable per ASME V Article 7 (Tabel T-721) harus dipahami sebelum menulis."},{"heading":"Hierarki dokumen","body":"Code/spec (ASME V, ASTM E1444/E709, AWS D1.1) menetapkan WHAT yang minimum. Written procedure menerjemahkan ke HOW spesifik untuk part. Technique sheet / traveler menetapkan setting konkret untuk satu part number. Susun dari atas ke bawah: pastikan procedure tidak pernah kurang ketat dari code yang direferensikan, dan technique sheet selalu berada di dalam range yang ditetapkan procedure."}]}', 460, NULL),
  (2, 'reading', 'Menetapkan Range — Field Strength & Arus', '{"slides":[{"heading":"Range arus untuk longitudinal (coil)","body":"ASTM E1444 memberi rumus coil shot. Untuk low-fill-factor (part menempel dinding coil, area part <10% area coil) dengan L/D 2-15: ampere-turn (NI) = 45000 / (L/D). Untuk high-fill-factor (part di tengah, area part >=50% area coil) dengan L/D 2-15: NI = 35000 / (L/D + 2). L (length) dan D (diameter) part. Saat menulis range, tetapkan nilai nominal lalu verifikasi batas bawah tetap menghasilkan field adekuat lewat shim/QQI atau pie gauge."},{"heading":"Range arus untuk circular (head shot / central conductor)","body":"Pedoman umum ASTM E1444: 300-800 A per inch diameter (sekitar 12-31 A/mm). Praktik tipikal mulai 500 A/in lalu naik bila indikasi lemah. Untuk central conductor offset, gunakan jarak efektif (distance from conductor) bukan OD part. Tulis range, mis. ''500-700 A/in OD'' continuous, bukan satu titik, agar operator bisa menyesuaikan kondisi part tanpa keluar prosedur. Selalu cantumkan apakah continuous atau residual technique."},{"heading":"Tangential field strength sebagai alternatif","body":"ASTM E1444 mengizinkan verifikasi langsung dengan Hall-effect tangential-field gaussmeter: tangential field 30-60 gauss (2.4-4.8 kA/m) pada permukaan saat magnetizing current ON. Ini cara paling defensible untuk geometri kompleks dimana rumus arus tidak akurat. Dalam procedure, nyatakan secara eksplisit metode adekuasi yang dipakai: rumus ampere-turn, ATAU pie gauge / shim, ATAU pengukuran tangential 30-60 G."},{"heading":"Verifikasi adekuasi lapangan","body":"Range arus saja tidak cukup; procedure harus menetapkan tool verifikasi: QQI/shim (artificial flaw) ditempel pada area kritis, pie gauge untuk indikasi arah & kecukupan field, atau Ketos (Betz) ring standard per ASTM E1444 untuk system performance overall. Tetapkan acceptance: indikasi shim/ring terlihat jelas pada batas BAWAH range. Untuk multidirectional, verifikasi tiap arah dengan shim cross (QQI dua arah) atau pie gauge."}]}', 500, NULL),
  (3, 'reading', 'Variabel Media, Lighting & Demag dalam Procedure', '{"slides":[{"heading":"Spesifikasi media & konsentrasi","body":"Procedure harus mengunci tipe media dan, untuk wet method, konsentrasi via settling test (ASTM E1444): fluorescent 0.1-0.4 mL per 100 mL, visible 1.2-2.4 mL per 100 mL, diukur dalam pear-shaped centrifuge tube setelah settle (umumnya 30 menit untuk petroleum-based, 60 menit untuk water-based). Cantumkan frekuensi cek konsentrasi (mis. tiap shift / 8 jam atau tiap 40 jam operasi), water break test untuk water-based carrier, dan kriteria buang bath bila kontaminasi/banding."},{"heading":"Lighting requirement","body":"Untuk fluorescent: UV-A minimum 1000 uW/cm2 di permukaan part pada jarak 38 cm (15 in), ambient white light maksimum 20 lux (2 fc), dan eye adaptation gelap minimal 1 menit sebelum inspeksi. Untuk visible (color contrast): white light minimum 1000 lux (100 fc) di permukaan part. Procedure harus menyebut alat ukur (UV-A radiometer / lux meter), frekuensi verifikasi, dan pengecekan UV-A bulb (filter tidak retak, lensa bersih, intensitas distabilkan)."},{"heading":"Surface preparation & sequence","body":"Tetapkan kondisi permukaan: bersih dari oli/karat/scale berat; coating/cat tipis kering boleh ditoleransi hanya bila adekuasi field dibuktikan dengan shim melalui coating tersebut (E1444 mensyaratkan verifikasi, bukan satu angka tebal universal); kondisi yang menutup discontinuity harus dihilangkan. Urutkan langkah continuous magnetization: apply media SAAT arus masih ON lalu matikan arus; untuk residual technique, magnetize dahulu lalu apply media. Salah urutan = essential variable berubah."},{"heading":"Demagnetization & residual field","body":"Procedure wajib menetapkan demag bila sisa medan mengganggu machining, welding, akurasi instrumen, atau service part. Metode: AC step-down, DC reversing & decay, atau coil pass-through. Kriteria penerimaan residual field yang lazim <= 3 gauss (sekitar 240 A/m) diukur dengan field indicator/gaussmeter pada titik yang ditetapkan. Cantumkan titik ukur dan nilai batas; bila part akan di-MT ulang multidirectional, demag antar arah mungkin diperlukan."}]}', 480, NULL),
  (4, 'reading', 'Kualifikasi, Demonstrasi & Approval Procedure', '{"slides":[{"heading":"Demonstrasi kualifikasi (T-721.2)","body":"ASME V Article 7 (T-721.2) mensyaratkan procedure didemonstrasikan kepada Inspector/owner sebelum dipakai: tunjukkan bahwa setting yang ditulis benar-benar menghasilkan deteksi indikasi pada part representatif (atau dengan QQI/shim) di seluruh area kritis. Demonstrasi membuktikan field adekuat pada batas BAWAH range yang dikualifikasi — bukan hanya pada setting nominal. Rekam hasil sebagai bukti kualifikasi dan simpan bersama procedure."},{"heading":"Acceptance criteria yang benar","body":"Procedure harus mereferensikan acceptance code yang tepat dan menuliskannya, bukan menyalin salah code. Contoh: AWS D1.1 (edisi terbaru) menempatkan acceptance MT/visual di Clause 8 (Inspection), membedakan koneksi statically loaded vs cyclically loaded; ASME VIII Div 1 Mandatory Appendix 6 menolak antara lain relevant linear indication > 1.6 mm (1/16 in) dan rounded indication > 5 mm (3/16 in). Tetapkan juga definisi relevant vs nonrelevant indication dan ambang evaluasi (mis. indikasi >= 1.6 mm dievaluasi sebagai relevant)."},{"heading":"Requalifikasi saat essential variable berubah","body":"Bila satu essential variable keluar dari range yang dikualifikasi — turun di bawah arus minimum, ganti tipe media, ganti method magnetisasi, lighting di bawah batas, ubah continuous ke residual — procedure harus di-revisi dan didemonstrasikan ulang. Buat tabel essential variable dengan range qualified-nya supaya auditor cepat melihat batas. Revisi diberi nomor & tanggal; revisi lama di-superseded (ditarik dari peredaran), bukan sekadar dibuang tanpa jejak."},{"heading":"Review, approval & kontrol revisi","body":"Procedure final harus di-review dan disetujui oleh Level III (atau yang ditunjuk Responsible Level III / owner) dan diberi nomor dokumen, nomor revisi, tanggal efektif, serta daftar referensi code lengkap dengan edisi/tahun spesifik. Document control mencegah operator memakai revisi usang. Level II men-develop procedure dan dapat menandatangani technique sheet, tetapi approval procedure tingkat sistem umumnya kewenangan Level III sesuai SNT-TC-1A / ANSI/ASNT CP-189."}]}', 470, NULL),
  (5, 'quiz', 'Mini-quiz — Procedure Development', '{"description":"8 soal penyusunan written procedure MT Level II: essential variable, range arus/field, media, lighting, demag, acceptance criteria, kualifikasi & approval.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 7 mini-quiz (9 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Standar mana yang secara eksplisit mengharuskan setiap pemeriksaan MT mengikuti written procedure yang terdokumentasi dan menetapkan elemen minimum-nya?',
   '["ISO 6520 saja","ASME Section V, Article 7","ASME Section VIII, Division 1","AWS D1.1 Clause 3"]', 1,
   'ASME Section V Article 7 (T-721) mensyaratkan written procedure dan mencantumkan elemen wajib seperti method, arus/field, media, lighting, demag, dan acceptance criteria. ASME VIII menetapkan acceptance untuk pressure vessel tetapi merujuk ke Section V untuk metode; ISO 6520 hanya klasifikasi diskontinuitas; AWS D1.1 Clause 3 adalah prequalification.', 'Procedure Development', 'easy'),
  ('Manakah yang merupakan ESSENTIAL VARIABLE, sehingga bila diubah mewajibkan requalifikasi/demonstrasi ulang procedure?',
   '["Mengganti nama operator yang menjalankan inspeksi","Memperbarui nomor halaman pada dokumen","Mengganti media dari wet fluorescent menjadi dry visible powder","Mengganti merek yoke dengan model setara berkemampuan sama"]', 2,
   'Mengganti tipe media (fluorescent ke visible) mengubah sensitivitas dan merupakan essential variable di Tabel T-721. Nama operator, nomor halaman, dan merek peralatan setara adalah nonessential variable.', 'Procedure Development', 'medium'),
  ('Menurut ASTM E1444, range tangential field strength yang harus ada di permukaan part saat magnetizing current ON, diukur dengan Hall-effect gaussmeter, adalah:',
   '["3-6 gauss","100-150 gauss","300-800 gauss","30-60 gauss (2.4-4.8 kA/m)"]', 3,
   'E1444 menetapkan tangential field 30-60 gauss (2.4-4.8 kA/m) sebagai verifikasi adekuasi field di permukaan; ini metode defensible untuk geometri kompleks. 300-800 adalah pedoman arus circular (A/in), bukan gauss.', 'Field Strength', 'medium'),
  ('Untuk circular magnetization (head shot / central conductor), pedoman umum arus per ASTM E1444 adalah:',
   '["300-800 A per inch diameter","35-60 A per inch diameter","1000-2000 A per inch diameter","Tetap 1000 A tanpa memperhatikan diameter"]', 0,
   'Pedoman circular magnetization adalah 300-800 A/in diameter (sekitar 12-31 A/mm), dengan praktik tipikal mulai 500 A/in lalu naik bila indikasi lemah. Arus harus diskalakan terhadap diameter, bukan nilai tetap.', 'Field Strength', 'medium'),
  ('Sebuah part silinder solid L/D = 5 akan di-magnetisasi longitudinal dengan part menempel pada dinding coil (low-fill-factor). Ampere-turn (NI) yang ditetapkan rumus ASTM E1444 mendekati:',
   '["5.000 ampere-turn","7.000 ampere-turn","9.000 ampere-turn","45.000 ampere-turn"]', 2,
   'Low-fill-factor: NI = 45000 / (L/D) = 45000 / 5 = 9.000 ampere-turn. Rumus high-fill-factor 35000/(L/D+2) = 35000/7 ~ 5.000 ampere-turn hanya berlaku bila part di tengah coil.', 'Field Strength', 'hard'),
  ('Saat menetapkan konsentrasi media wet fluorescent dalam procedure, settling test (ASTM E1444) harus menghasilkan rentang berapa per 100 mL?',
   '["5-10 mL","1.2-2.4 mL","0.1-0.4 mL","0.01-0.05 mL"]', 2,
   'Wet fluorescent: 0.1-0.4 mL per 100 mL via centrifuge settling test. Rentang 1.2-2.4 mL per 100 mL berlaku untuk visible (non-fluorescent) suspension.', 'Process Variables', 'medium'),
  ('Procedure untuk inspeksi fluorescent harus menetapkan persyaratan lighting yang mana?',
   '["White light minimum 1000 lux dan UV-A tidak relevan","UV-A minimum 1000 uW/cm2 pada 38 cm dan ambient white light maksimum 20 lux","UV-A minimum 100 uW/cm2 dan ambient white light maksimum 1000 lux","UV-A maksimum 1000 uW/cm2 dan ambient bebas"]', 1,
   'Fluorescent membutuhkan UV-A >= 1000 uW/cm2 di permukaan pada jarak 38 cm dan ambient white light <= 20 lux. White light >= 1000 lux justru syarat untuk metode visible/color contrast, bukan fluorescent.', 'Lighting', 'medium'),
  ('Procedure menetapkan demagnetization dengan kriteria penerimaan residual field. Nilai batas yang lazim diterima adalah:',
   '["<= 30 gauss","<= 3 gauss (sekitar 240 A/m)","<= 60 gauss","<= 0.3 gauss"]', 1,
   'Kriteria residual field yang lazim adalah <= 3 gauss (sekitar 240 A/m), diukur dengan field indicator/gaussmeter pada titik yang ditetapkan procedure. 30 dan 60 gauss terlalu tinggi; 0.3 gauss tidak praktis dan tidak disyaratkan.', 'Demagnetization', 'easy'),
  ('Sebelum dipakai produksi, ASME V Article 7 (T-721.2) mensyaratkan procedure harus:',
   '["Cukup ditandatangani operator Level I yang akan menjalankannya","Hanya menampilkan setting nominal tanpa perlu demonstrasi","Didemonstrasikan kualifikasinya membuktikan field adekuat pada batas BAWAH range, lalu di-review/approve","Disetujui lisan oleh supervisor tanpa rekaman tertulis"]', 2,
   'T-721.2 menuntut demonstrasi bahwa procedure mendeteksi indikasi pada part representatif/QQI, khususnya pada batas bawah range, lalu di-review dan disetujui (umumnya oleh Level III) dengan rekaman tertulis dan kontrol revisi.', 'Qualification & Approval', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 8 (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'ASME V Article 7 — Struktur & Mandatory Requirements', '{"slides":[{"heading":"Anatomi Article 7","body":"ASME BPVC Section V Article 7 mengatur Magnetic Particle Examination. Struktur paragraf utama: T-710 Scope, T-720 General (personnel & written procedure), T-730 Equipment, T-740 Miscellaneous Requirements (surface preparation & technique restrictions), T-750 Technique, T-760 Calibration, T-770 Examination, T-780 Evaluation, T-790 Documentation. Acceptance standard TIDAK ada di Article 7 — harus diambil dari referencing Code Section (mis. Section VIII Div 1 Mandatory Appendix 6, atau B31.3 Chapter VI). Article 7 hanya menetapkan CARA (how-to); referencing code menetapkan accept/reject."},{"heading":"Written Procedure & Essential Variables","body":"T-721.2: written procedure wajib didemonstrasikan kemampuan deteksinya. Perubahan suatu essential variable di luar range yang dikualifikasi memerlukan rekualifikasi prosedur dan revisi tertulis. Essential variables a.l.: magnetizing technique, magnetizing current type, surface preparation, particle (warna/fluorescent, dry/wet), method (continuous), serta ampere/field strength range. Nonessential variable (mis. nomor part, lokasi pemeriksaan, personel) hanya butuh revisi prosedur tanpa rekualifikasi."},{"heading":"Mandatory Techniques (T-750)","body":"Article 7 mengakui teknik magnetisasi utama: yoke (T-752), prod (T-753), longitudinal/coil-cable (T-755), central conductor & direct/indirect contact head shot (T-756). Continuous method WAJIB untuk wet & dry (T-754) — arus dialirkan SAAT partikel diaplikasikan dan dihentikan SEBELUM aliran partikel berhenti, agar field maksimum saat indikasi terbentuk. Residual method TIDAK diizinkan kecuali secara spesifik diperbolehkan referencing code. Dua arah magnetisasi yang saling tegak lurus wajib pada tiap area agar diskontinuitas segala orientasi terdeteksi."}]}', 460, NULL),
  (2, 'reading', 'ASME V Article 7 — Kalibrasi, Verifikasi & Lighting', '{"slides":[{"heading":"Lifting Power & Yoke Calibration (T-762)","body":"Yoke harus dikalibrasi minimal sekali per tahun, ATAU setiap kali rusak/diperbaiki, ATAU bila menjatuhkan/membentur. AC yoke harus mengangkat berat minimal 10 lb (4.5 kg) pada jarak antar-kaki maksimum yang akan dipakai. DC/permanent yoke harus mengangkat minimal 40 lb (18 kg). Test weight harus tertelusur (calibrated, weighed). Setiap kali jarak antar-kaki diubah saat pemakaian, lifting power harus dipenuhi pada jarak tersebut. Catatan: lift test memverifikasi KEMAMPUAN, bukan menjamin field strength aktual di part — itu diverifikasi terpisah."},{"heading":"Gaussmeter & Ammeter (T-761/T-763)","body":"Ammeter (jika dipakai membaca arus) diverifikasi akurasinya minimal sekali per tahun terhadap calibrated reference, toleransi +/- 10% pembacaan. Gaussmeter/Hall-effect probe untuk verifikasi tangential field strength dikalibrasi minimal sekali per tahun. Tangential field strength umumnya ditargetkan 30-60 G (2.4-4.8 kA/m) di permukaan part; verifikasi ini MELENGKAPI (bukan menggantikan) penggunaan QQI/shim atau pie gauge sebagai field-adequacy indicator."},{"heading":"Light Intensity (T-777)","body":"Visible (color contrast): white light minimal 1000 lux (100 fc) pada permukaan yang diperiksa, diverifikasi minimal sekali per tahun dan saat lampu diganti. Fluorescent: UV-A irradiance minimal 1000 uW/cm2 pada permukaan part (UV meter terkalibrasi), ambient white light maksimal 20 lux (2 fc). Lampu UV-A harus warm-up sesuai rekomendasi pabrik (umumnya >= 5 menit) sebelum digunakan/diukur. Mata inspektor wajib adaptasi gelap minimal 1 menit sebelum interpretasi fluorescent."},{"heading":"System Performance / Settling Test","body":"Untuk wet method, konsentrasi bath diverifikasi via settling test memakai pear-shaped centrifuge tube (ASTM E1444): fluorescent 0.1-0.4 mL per 100 mL bath, visible 1.2-2.4 mL per 100 mL bath, dibaca setelah 30 menit pengendapan (60 menit untuk petroleum-based carrier). ASME V mensyaratkan verifikasi konsentrasi serta pemeriksaan kontaminasi/brightness bath. Overall system performance kerap diverifikasi dengan Ketos/tool-steel ring standard (ASTM E1444) berisi lubang berjarak terkontrol untuk memvalidasi sensitivitas keseluruhan sistem."}]}', 480, NULL),
  (3, 'reading', 'ASME V Article 7 — Evaluasi & Acceptance Linkage', '{"slides":[{"heading":"Klasifikasi Indikasi (T-780)","body":"Hanya indikasi dengan dimensi mayor > 1/16 in (1.6 mm) yang dianggap relevant dan harus dievaluasi. Indikasi diklasifikasi linear (length >= 3x width) atau rounded (length < 3x width). Broad/diffuse area yang sulit diinterpretasi harus dibersihkan ulang lalu diperiksa kembali. Nonrelevant indications (perubahan section, magnetic writing, permeability boundary) harus dibedakan dari relevant — bila ragu: demagnetize, bersihkan, dan re-test. Magnetic writing dihindari dengan tidak membiarkan part saling bersentuhan saat termagnetisasi."},{"heading":"Acceptance dari Referencing Code","body":"Contoh acceptance standard ASME Section VIII Div 1, Mandatory Appendix 6: TOLAK bila — (a) setiap relevant linear indication; (b) rounded indication > 3/16 in (4.8 mm); (c) empat atau lebih rounded indication dalam satu garis berjarak <= 1/16 in (1.6 mm) edge-to-edge. Untuk weld piping rujuk B31.3 masing-masing. Level II HARUS paham bahwa kriteria angka berasal dari construction code, BUKAN dari Article 7."},{"heading":"Demagnetization & Documentation (T-790)","body":"Demagnetisasi diperlukan bila residual magnetism dapat mengganggu proses berikutnya (machining, welding/arc blow), operasi part (mengganggu instrumen), atau menarik chip. Residual field umumnya dibatasi <= 3 G (~240 A/m) diukur dengan field indicator/gaussmeter. Dokumentasi (T-792) mencakup: prosedur & revisi, teknik, arus & jenis, peralatan, hasil, mapping indikasi, identifikasi inspektor & level, dan tanggal. Level II menandatangani report final; Level I tidak boleh sign-off accept/reject."}]}', 440, NULL),
  (4, 'reading', 'ASTM E709 Mendalam & ASTM E1444', '{"slides":[{"heading":"ASTM E709 — Standard Guide","body":"E709 adalah GUIDE (bukan specification): menjelaskan opsi teknik MT tanpa memerintahkan accept/reject. Mencakup dry & wet, continuous & residual, AC/HWDC/FWDC/DC, dan semua teknik (yoke, prod, coil, central conductor, head shot, induced current). Karena bersifat guide, E709 dipakai sebagai referensi pendidikan dan dasar penyusunan prosedur; untuk pekerjaan kontrak, persyaratan wajib & acceptance biasanya datang dari E1444/E3024 atau code aplikatif. Level II harus tahu kapan E709 cukup dan kapan butuh spesifikasi yang enforceable."},{"heading":"Field Direction & Coverage di E709","body":"E709 menegaskan diskontinuitas terdeteksi optimal bila orientasinya 45-90 derajat terhadap arah field; deteksi minim bila hampir paralel (0-15 derajat). Karena itu tiap area wajib dimagnetisasi dua arah saling tegak lurus. Circular magnetization (head shot/central conductor) menghasilkan field melingkar yang mendeteksi cacat LONGITUDINAL. Longitudinal magnetization (coil) menghasilkan field aksial yang mendeteksi cacat TRANSVERSAL. L/D ratio part penting untuk coil shot; demagnetize antar arah bila perlu untuk mencegah field interaction."},{"heading":"Coil Formula (Fill-Factor)","body":"E709/E1444 memberi formula amp-turns untuk longitudinal magnetization. Low fill-factor, part menempel dinding coil: NI = 45000 / (L/D). High fill-factor (cable-wrap, part di tengah, fill >= 0.9): NI = 35000 / ((L/D) + 2). Contoh: part L/D = 4, low fill factor: NI = 45000/4 = 11250 amp-turns; bila coil 5 lilitan maka arus = 11250/5 = 2250 A. L/D dibatasi 2-15 untuk validitas formula; bila L/D < 2 gunakan pole pieces/extension untuk efektif menaikkan L. Verifikasi akhir tetap dengan QQI/shim atau pie gauge."},{"heading":"ASTM E1444/E1444M — Standard Practice","body":"E1444 adalah PRACTICE yang enforceable (sering dipanggil di kontrak aerospace/defense, menggantikan MIL-STD-1949). Mengatur: konsentrasi bath (settling test fluorescent 0.1-0.4 mL, visible 1.2-2.4 mL per 100 mL), water-break test untuk wettability, system performance dengan Ketos ring, verifikasi UV-A >= 1000 uW/cm2, demagnetisasi residual <= 3 G, dan dokumentasi. E1444 mereferensi E709 untuk teknik dan E1316 untuk terminologi. Acceptance criteria pada E1444 sendiri dirujuk dari drawing/spec part."}]}', 480, NULL),
  (5, 'reading', 'ISO 9934, AWS D1.1 & Reconciliation Antar-Code', '{"slides":[{"heading":"ISO 9934 Series","body":"ISO 9934 terdiri tiga bagian: Part 1 (General principles — teknik, magnetisasi, viewing, demagnetisasi), Part 2 (Detection media — persyaratan partikel & suspensi, sensitivity testing), Part 3 (Equipment — magnetizing equipment & verifikasi). ISO 9934-1 menetapkan tangential field strength 2-6 kA/m (25-75 G) pada permukaan; viewing fluorescent: UV-A >= 1000 uW/cm2 (10 W/m2) pada permukaan, ambient <= 20 lux; visible white light >= 500 lux (banyak code aplikatif menaikkan ke >= 1000 lux). Overall performance diverifikasi dengan reference block (mis. type 1 cross / type 2 shim)."},{"heading":"ISO 9712 & Acceptance via ISO 23278","body":"Sertifikasi personel MT pada skema ISO mengikuti ISO 9712 (Level 1/2/3). Untuk weld, acceptance levels MT diberikan oleh ISO 23278 (acceptance levels 1, 2, 3 — angka lebih kecil = lebih ketat), dipasangkan dengan tingkat kualitas weld ISO 5817 (B/C/D). Jadi ISO 9934 = CARA, ISO 23278 = accept/reject. Ini paralel dengan ASME V Article 7 (cara) vs referencing code (acceptance). Level II harus memetakan dengan benar agar tidak salah menerapkan kriteria."},{"heading":"AWS D1.1 Clause 6 (Inspection)","body":"AWS D1.1 Structural Welding Code-Steel mengatur MT pada Clause 6 (Part F). Kriteria MT mengacu pada acceptance untuk statically vs cyclically (dynamically) loaded connections. Cyclically loaded jauh lebih ketat terhadap cacat linear (cracks tidak boleh; undercut & porosity limit lebih ketat) karena risiko fatigue. Yoke AC umum dipakai di lapangan; prod dihindari pada baja finished karena risiko arc strike. MT pada D1.1 hanya untuk surface/near-surface; diskontinuitas subsurface/volumetrik pakai UT/RT."},{"heading":"Reconciliation Praktis Antar-Code","body":"Skenario lapangan: satu komponen dapat tunduk pada beberapa dokumen. Aturan praktik Level II: (1) ikuti kode kontrak/PO yang paling spesifik & paling ketat bila ada konflik; (2) pisahkan dokumen CARA (E709, ISO 9934-1, ASME V Art 7) dari dokumen ACCEPTANCE (E1444+drawing, ISO 23278, Section VIII App 6, D1.1); (3) catat referensi exact (nomor klausa & edisi/tahun) di report; (4) bila kriteria tidak eksplisit, eskalasi ke Level III, jangan mengasumsikan. Konsistensi unit: 1 G = 0.1 mT; 30-60 G = 2.4-4.8 kA/m."}]}', 470, NULL),
  (6, 'quiz', 'Mini-quiz — Advanced Code Interpretation', '{"description":"7 soal interpretasi code MT Level II: ASME V Article 7, ASTM E709/E1444, ISO 9934/23278, dan AWS D1.1.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 8 mini-quiz (7 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam ASME BPVC Section V Article 7, dari mana acceptance criteria (accept/reject) untuk indikasi MT sebenarnya berasal?',
   '["Dari paragraf T-780 di dalam Article 7 itu sendiri","Dari referencing code section (mis. Section VIII Div 1 Mandatory Appendix 6), bukan dari Article 7","Dari ASTM E709 yang wajib dilampirkan pada setiap prosedur","Dari keputusan personal inspektor Level II di lapangan"]', 1,
   'Article 7 hanya menetapkan CARA pemeriksaan (teknik, kalibrasi, evaluasi prosedur). Kriteria accept/reject diambil dari referencing construction code, mis. Section VIII Div 1 Mandatory Appendix 6. Inilah pembeda kunci yang harus dipahami Level II.', 'ASME V Article 7', 'medium'),
  ('Sesuai T-762 ASME V, berapa lifting power minimum yang harus dibuktikan untuk AC yoke dan DC/permanent yoke?',
   '["AC dan DC keduanya minimal 10 kg","AC 18 kg (40 lb) dan DC 4.5 kg (10 lb)","AC 4.5 kg (10 lb) dan DC 18 kg (40 lb) pada jarak kaki maksimum yang dipakai","AC 4.5 kg (10 lb) dan DC 9 kg (20 lb)"]', 2,
   'AC yoke harus mengangkat minimal 10 lb (4.5 kg); DC/permanent yoke minimal 40 lb (18 kg), keduanya pada jarak antar-kaki maksimum yang akan dipakai. Test weight harus tertelusur. Lift test memverifikasi kemampuan, bukan menjamin field strength aktual.', 'ASME V Article 7', 'medium'),
  ('Pada wet method, settling (concentration) test per ASTM E1444 mensyaratkan volume sedimen berapa per 100 mL bath untuk partikel fluorescent dan visible?',
   '["Fluorescent 1.2-2.4 mL dan visible 0.1-0.4 mL","Fluorescent 0.1-0.4 mL dan visible 1.2-2.4 mL","Keduanya 0.5-1.0 mL","Fluorescent 0.4-0.8 mL dan visible 2.4-4.8 mL"]', 1,
   'Settling test memakai pear-shaped centrifuge tube: fluorescent 0.1-0.4 mL per 100 mL, visible 1.2-2.4 mL per 100 mL, dibaca setelah 30 menit (60 menit untuk petroleum carrier). Konsentrasi visible lebih tinggi karena partikel non-fluorescent butuh densitas lebih untuk kontras yang memadai.', 'ASTM E1444', 'medium'),
  ('Sebuah part silindris memiliki L/D = 4 dan diperiksa menempel dinding coil (low fill-factor). Berapa amp-turns yang dibutuhkan menurut formula ASTM E709/E1444 NI = 45000/(L/D)?',
   '["180000 amp-turns","45004 amp-turns","9000 amp-turns","11250 amp-turns"]', 3,
   'Untuk low fill-factor (part di dinding coil), NI = 45000/(L/D) = 45000/4 = 11250 amp-turns. Bila coil 5 lilitan, arus = 11250/5 = 2250 A. Formula valid untuk L/D 2-15; verifikasi akhir tetap dengan QQI/shim atau pie gauge.', 'ASTM E709', 'hard'),
  ('Apa perbedaan fundamental status dokumen antara ASTM E709 dan ASTM E1444?',
   '["E709 adalah Practice yang enforceable, E1444 hanya Guide informatif","Keduanya Specification dengan acceptance criteria numerik yang identik","E709 untuk fluorescent saja, E1444 untuk visible saja","E709 adalah Guide (informatif, opsi teknik), E1444 adalah Practice yang enforceable di kontrak"]', 3,
   'E709 adalah Standard GUIDE — menjelaskan opsi teknik tanpa mandat accept/reject, dipakai sebagai referensi. E1444 adalah Standard PRACTICE yang enforceable, sering dipanggil di kontrak aerospace/defense (menggantikan MIL-STD-1949) dan mengatur konsentrasi, performance Ketos ring, UV-A, demagnetisasi, dll.', 'ASTM E709', 'medium'),
  ('Dalam skema standar ISO untuk pemeriksaan MT pada las, dokumen mana yang menetapkan acceptance levels (accept/reject), bukan sekadar teknik?',
   '["ISO 9712 (sertifikasi personel)","ISO 23278 (acceptance levels), dipasangkan dengan tingkat kualitas ISO 5817","ISO 9934-1 (general principles/teknik)","ISO 9934-3 (equipment)"]', 1,
   'ISO 9934 mengatur CARA (teknik, media, equipment). Acceptance levels MT untuk weld berasal dari ISO 23278 (levels 1/2/3, makin kecil makin ketat), dipasangkan dengan tingkat kualitas weld ISO 5817 (B/C/D). ISO 9712 hanya soal sertifikasi personel.', 'ISO 9934', 'medium'),
  ('Mengapa AWS D1.1 menerapkan kriteria MT yang lebih ketat untuk struktur cyclically (dynamically) loaded dibanding statically loaded?',
   '["Karena struktur dinamis lebih murah sehingga butuh inspeksi lebih banyak","Karena beban statis tidak pernah menyebabkan kegagalan struktur","Karena cacat linear/crack memicu fatigue failure di bawah beban siklik sehingga toleransinya jauh lebih kecil","Karena MT secara teknis tidak dapat diterapkan pada struktur statis"]', 2,
   'Pada beban siklik, diskontinuitas permukaan seperti crack dan undercut bertindak sebagai stress raiser yang menginisiasi fatigue crack, sehingga AWS D1.1 menetapkan batas yang jauh lebih ketat (cracks dilarang; undercut/porosity lebih terbatas) untuk cyclically loaded dibanding statically loaded.', 'AWS D1.1', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 9 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'System Performance Check — Ketos/Betz Ring & Pie Gauge', '{"slides":[{"heading":"Ketos (Betz) Ring — Tool Audit Utama","body":"Tool steel ring (dahulu dikenal Ketos/Betz ring) per ASTM E1444 dan SAE AS 5282, dibuat dari baja AISI/SAE O1 tool steel (di-anil), memiliki 12 lubang subsurface (drilled holes) diameter 1.78 mm (0.07 in). Lubang-lubang ini berada pada jarak berurutan dari OD dengan kelipatan 1.78 mm (1.78 mm hingga 21.34 mm). Ring dimagnetisasi dengan central conductor yang dilewatkan bore tengah (12.7 mm). Jumlah lubang yang terlihat (counting holes) menentukan apakah performance keseluruhan sistem memenuhi minimum — bukan sekadar arus yang benar."},{"heading":"Acceptance Criteria Counting Holes","body":"Untuk wet continuous, tabel acceptance dalam spec yang berlaku menghubungkan arus magnetisasi dengan jumlah lubang minimum yang harus terlihat. Sebagai contoh praktik yang umum dikutip: dengan central conductor pada ~1400 A FWDC minimal 3 lubang terlihat untuk fluorescent; pada arus lebih tinggi jumlah lubang minimum bertambah. Untuk visible (non-fluorescent) threshold-nya berbeda. Nilai eksaknya BERVARIASI menurut edisi spec dan customer — selalu rujuk tabel pada controlling spec/procedure. Bila lubang kurang dari minimum, sistem (bath, lampu, atau equipment) bermasalah dan harus diinvestigasi sebelum produksi dilanjutkan."},{"heading":"Pie Gauge (Pie Field Indicator)","body":"Pie gauge: 8 segmen pie baja ferromagnetik yang di-furnace-braze dengan tembaga non-feromagnetik, lalu ditutup pelat tembaga tipis non-feromagnetik. Diletakkan copper-side UP di permukaan part selama magnetisasi sambil media diaplikasikan. Garis serbuk yang terbentuk di atas segmen menunjukkan arah field dan adanya flux yang cukup. CATATAN penting Level II: pie gauge hanya indikator arah/keberadaan field — TIDAK mengukur kuantitatif field strength dan TIDAK boleh dipakai sebagai bukti adequacy untuk procedure qualification."},{"heading":"Posisi & Limitasi Indikator","body":"Pie gauge dan QQI menampilkan flux leakage pada permukaan; karena field turun seiring jarak, indikator harus kontak langsung dengan area inspeksi. Pie gauge cocok untuk verifikasi cepat arah field di lapangan/yoke, tetapi untuk evaluasi adequacy yang kuantitatif gunakan QQI/shim dan/atau Hall-effect gaussmeter. ASME V Article 7 (T-764) dan ASTM E1444 lebih menyukai QQI/shim untuk demonstrasi adequacy karena lebih sensitif dan repeatable dibanding pie gauge."}]}', 470, NULL),
  (2, 'reading', 'QQI Shim, Hall-Effect Gaussmeter & Multidirectional Balance', '{"slides":[{"heading":"QQI / Artificial Flaw Shim","body":"QQI (Quantitative Quality Indicator) per SAE AS 5371 = shim baja AISI 1005 low-carbon, tebal tipikal 0.05 mm (0.002 in / 2 mil) atau 0.10 mm, dengan flaw artificial ter-etch (lingkaran/cross) berkedalaman fraksi tertentu dari tebal shim (mis. CX-230 = flaw 30% tebal). Shim dipasang flaw-side DOWN ke permukaan part (lem/tape pada sisi polos), lalu dimagnetisasi. Indikasi pada shim membuktikan field cukup kuat DAN arahnya benar (flaw yang tegak lurus field akan terbentuk). AS 5371 mendesain shim agar terindikasi pada minimal ~30 G tangential field."},{"heading":"Penggunaan untuk Multidirectional","body":"Untuk multidirectional/multi-shot, QQI dengan flaw cross (dua flaw saling tegak lurus) wajib: kedua tungkai cross harus membentuk indikasi yang seimbang, membuktikan KEDUA field (mis. head shot dan coil/central) adekuat dan balanced dalam satu lokasi. Inilah cara Level II men-set dan memverifikasi balance arus pada multidirectional bench sebelum produksi. Tempatkan shim pada lokasi yang paling kritis / field-nya paling lemah pada part."},{"heading":"Hall-Effect Gaussmeter / Tangential Field","body":"Gaussmeter Hall-effect mengukur tangential field strength di permukaan. Target tangential field yang umum disebut adalah 30–60 G (3–6 mT) pada permukaan untuk continuous wet method (referensi ASTM E1444 / praktik industri; konsisten dengan AS 5371 yang mensyaratkan minimal ~30 G untuk indikasi shim). Probe diorientasikan tangensial terhadap permukaan dan tegak lurus arah indikasi yang dicari. Sangat berguna untuk part bergeometri kompleks di mana perhitungan amp-turn tidak akurat. Catatan: ASTM E1444 lebih mengutamakan demonstrasi via QQI/shim daripada satu angka gaussmeter tetap."},{"heading":"Residual Field Check (Demagnetization)","body":"Setelah inspeksi, residual field harus diverifikasi rendah agar part tidak mengganggu machining/welding atau menarik chips. Batas umum residual field <= 3 G (sebagian spec lebih ketat, mis. 2 G) diukur dengan field indicator/gaussmeter. Bila melebihi, lakukan demagnetisasi (AC step-down atau DC reversing decay) lalu ukur ulang. Dokumentasikan nilai residual pada report untuk part kritis."}]}', 480, NULL),
  (3, 'reading', 'Daily/Shift Checks — Lift Test, Settling, Water Break, Light & UV', '{"slides":[{"heading":"Yoke Lift Test (Dead-Weight)","body":"Verifikasi adequacy yoke harian/sebelum first use: AC electromagnetic yoke harus mampu mengangkat beban 4.5 kg (10 lb) pada spasi leg maksimum yang akan dipakai; DC/permanent magnet yoke harus mengangkat 18 kg (40 lb). Untuk articulated yoke dengan kedua kaki menyentuh permukaan secara bersamaan, batasnya 22.7 kg (50 lb). Lift test memverifikasi gaya magnetomotif efektif pada gap aktual, bukan sekadar nilai nameplate."},{"heading":"Settling (Concentration) Test","body":"Untuk wet bath, ukur konsentrasi memakai centrifuge pear-shaped tube. Agitasi suspensi minimal 30 menit, ambil 100 mL, demagnetisasi sampel, lalu biarkan mengendap. WAKTU SETTLING ditentukan oleh CARRIER, bukan warna partikel: oil/petroleum-based minimal 60 menit; water-based minimal 30 menit. Rentang konsentrasi acceptable: fluorescent 0.1–0.4 mL per 100 mL bath; visible 1.2–2.4 mL per 100 mL. Frekuensi minimal tiap 8 jam atau pergantian shift. Periksa juga band kontaminan/brightness di atas settled layer — bila banding kontaminan berlebih, ganti bath."},{"heading":"Water Break Test (Wetting)","body":"Untuk water-based (water-suspendible) bath, lakukan water break test: basahi permukaan part yang bersih, bath harus membentuk film air kontinu tanpa pecah (break) selama >= 30 detik. Bila air pecah menjadi droplet, ada kontaminasi minyak atau wetting agent (conditioner) kurang — partikel tidak akan terdistribusi merata sehingga sensitivitas turun. Tambah conditioner/perbaiki cleaning, lalu uji ulang sebelum produksi."},{"heading":"UV-A & Ambient/White Light","body":"Fluorescent: UV-A irradiance minimal 1000 µW/cm² diukur pada 38 cm (15 in) dari filter; ambient white (visible) light di area inspeksi harus <= 20 lux (2 fc); operator harus dark-adapt minimal 1 menit (praktik umum 5 menit). Visible (kontras): white light minimal 1000 lux (100 fc) pada permukaan. Verifikasi output UV-A bulb harian dan cek white-light leak dari lampu UV-A (<= 2 fc). Radiometer/light meter harus terkalibrasi."}]}', 500, NULL),
  (4, 'reading', 'Audit Intervals, Calibration Certs & Recordkeeping', '{"slides":[{"heading":"Frekuensi Pemeriksaan (per ASTM E1444 practice)","body":"Daily/each shift: lighting (UV-A & white light), bath concentration & contamination, system performance check (Ketos ring atau QQI/shim). Setiap penggantian bath / saat dicurigai kontaminasi: water break + settling. Weekly: agitation & flow wet horizontal unit. Per 6 bulan: akurasi ammeter (terhadap calibrated shunt/reference meter). Timer/quick-break, dead-weight (lift) device, dan gaussmeter: kalibrasi per jadwal yang ditetapkan (umumnya tahunan)."},{"heading":"Ammeter & Timer Calibration","body":"Ammeter unit dikalibrasi terhadap certified reference meter minimal setiap 6 bulan; pembacaan harus dalam +-10% dari nilai sebenarnya pada minimal 3 titik dalam rentang operasi. Quick-break/short-shot timer dan dwell timer juga diverifikasi. Bila ammeter di luar toleransi, semua hasil sejak kalibrasi valid terakhir bisa dipertanyakan — implikasinya besar, sehingga Level II menjaga interval tetap ketat dan mendokumentasikannya."},{"heading":"Calibration Certificates & Traceability","body":"Setiap alat ukur (gaussmeter, light meter/radiometer, ammeter reference, timer, dead-weight) harus memiliki calibration certificate dengan traceability ke national standard (mis. NIST), mencantumkan tanggal kalibrasi, due date, dan toleransi. Radiometer/light meter biasanya dikalibrasi tahunan. Cert disimpan dan due date dimonitor; alat yang sudah melewati due date tidak boleh dipakai untuk acceptance decision."},{"heading":"Recordkeeping & Audit Trail","body":"Catat semua hasil daily/monthly check (log konsentrasi, UV-A reading, lift test pass/fail, Ketos ring/shim hole count) lengkap dengan tanggal, operator, dan nomor alat. Internal audit bulanan/triwulanan memverifikasi prosedur diikuti, log lengkap, cert masih valid, dan operator certified. Audit trail ini wajib untuk Nadcap/ISO 9712 serta saat customer/regulator audit; gap dalam record dapat membatalkan acceptance produk."}]}', 470, NULL),
  (5, 'quiz', 'Mini-quiz — Quality Control & Audit MT-L2', '{"description":"8 soal tentang system performance check, daily/shift verification, calibration & audit interval Level II.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 9
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 9 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada tool steel (Ketos/Betz) test ring per ASTM E1444 / SAE AS 5282, lubang artificial di-drill pada interval jarak berapa dari tepi (OD), dan berapa diameter tiap lubang?',
   '["Diameter 1.78 mm, pada kelipatan 1.78 mm dari OD","Diameter 2.50 mm, pada kelipatan 5.0 mm dari OD","Diameter 1.00 mm, pada kelipatan 1.0 mm dari OD","Diameter 3.18 mm, pada kelipatan 6.35 mm dari OD"]', 0,
   'Tool steel/Ketos ring memiliki 12 lubang berdiameter 1.78 mm (0.07 in) yang berada pada kelipatan 1.78 mm dari tepi (1.78 mm hingga 21.34 mm). Jumlah lubang yang terlihat pada arus tertentu menjadi ukuran performa sistem keseluruhan.', 'System Performance', 'hard'),
  ('Mana pernyataan yang BENAR tentang pie gauge (pie field indicator) menurut praktik Level II?',
   '["Memberikan pengukuran kuantitatif field strength dalam Gauss","Dipasang dengan sisi baja menghadap ke atas saat magnetisasi","Hanya menunjukkan arah dan keberadaan field, bersifat kualitatif, dan tidak boleh jadi bukti adequacy untuk qualification","Lebih sensitif daripada QQI/shim untuk demonstrasi field"]', 2,
   'Pie gauge diletakkan copper-side UP dan hanya menunjukkan arah/keberadaan flux di permukaan (kualitatif). Untuk demonstrasi adequacy yang kuantitatif dan repeatable digunakan QQI/shim atau Hall-effect gaussmeter, bukan pie gauge.', 'System Performance', 'medium'),
  ('Sebuah multidirectional (multi-shot) bench akan di-set up. Alat verifikasi paling tepat untuk membuktikan kedua field saling tegak lurus seimbang pada satu lokasi adalah:',
   '["Pie gauge tunggal di satu titik","QQI/shim dengan flaw cross, memastikan kedua tungkai cross terbentuk seimbang","Dead-weight lift test 4.5 kg","Settling tube centrifuge"]', 1,
   'QQI dengan flaw berbentuk cross digunakan untuk multidirectional: kedua tungkai cross harus membentuk indikasi yang seimbang, membuktikan dua field yang saling tegak lurus keduanya adekuat dan balanced pada lokasi kritis tersebut. Pie gauge hanya kualitatif dan lift test/settling tidak relevan dengan balance field.', 'Multidirectional QC', 'hard'),
  ('Spesifikasi yoke lift test (dead-weight). Mana yang benar?',
   '["AC yoke 18 kg; DC yoke 4.5 kg pada spasi maksimum","Semua yoke 22.7 kg tanpa memperhatikan spasi leg","AC dan DC yoke sama, 10 kg pada spasi minimum","AC yoke 4.5 kg (10 lb); DC/permanent yoke 18 kg (40 lb) pada spasi leg maksimum yang dipakai"]', 3,
   'AC electromagnetic yoke harus mengangkat 4.5 kg (10 lb); DC/permanent magnet yoke harus mengangkat 18 kg (40 lb); keduanya diuji pada spasi leg maksimum yang akan digunakan. Articulated yoke dengan kedua kaki menyentuh: 22.7 kg (50 lb).', 'Daily Checks', 'medium'),
  ('Pada settling (concentration) test wet bath per ASTM E1444, waktu settling minimum ditentukan oleh apa, dan berapa nilainya?',
   '["Ditentukan oleh warna partikel: fluorescent 30 menit, visible 60 menit","Selalu 10 menit untuk semua jenis bath","Ditentukan oleh carrier: oil/petroleum-based minimal 60 menit, water-based minimal 30 menit","Ditentukan oleh arus magnetisasi yang dipakai"]', 2,
   'Waktu settling bergantung pada CARRIER, bukan jenis partikel: oil/petroleum-based bath disettle minimal 60 menit, water-based minimal 30 menit. Fluorescent maupun visible bisa berbahan oil atau water, sehingga warna partikel bukan penentu waktu settling.', 'Daily Checks', 'hard'),
  ('Rentang KONSENTRASI yang dapat diterima pada settling test untuk masing-masing jenis partikel adalah:',
   '["Fluorescent 0.1–0.4 mL per 100 mL; visible 1.2–2.4 mL per 100 mL","Fluorescent 1.2–2.4 mL per 100 mL; visible 0.1–0.4 mL per 100 mL","Keduanya 0.5–1.0 mL per 100 mL","Fluorescent 2.0–3.0 mL per 100 mL; visible 4.0–5.0 mL per 100 mL"]', 0,
   'Fluorescent bath: 0.1–0.4 mL per 100 mL. Visible (non-fluorescent) bath: 1.2–2.4 mL per 100 mL, diukur dengan centrifuge pear-shaped tube. Rentang ini terpisah dari waktu settling (yang ditentukan oleh carrier).', 'Daily Checks', 'medium'),
  ('Untuk inspeksi FLUORESCENT, kombinasi nilai lighting yang benar adalah:',
   '["UV-A >= 1000 lux pada 15 cm; ambient white light <= 1000 lux","White light >= 1000 lux di permukaan; UV-A tidak diperlukan","UV-A >= 100 µW/cm² pada 38 cm; ambient white light <= 200 lux","UV-A >= 1000 µW/cm² pada 38 cm; ambient white light <= 20 lux"]', 3,
   'Fluorescent membutuhkan UV-A minimal 1000 µW/cm² diukur pada 38 cm (15 in) dan ambient white light <= 20 lux (2 fc). White light >= 1000 lux (100 fc) adalah syarat metode VISIBLE/kontras, bukan fluorescent.', 'Daily Checks', 'easy'),
  ('Mengenai kalibrasi ammeter dan recordkeeping, mana yang sesuai praktik Level II per ASTM E1444?',
   '["Ammeter cukup dikalibrasi sekali saat instalasi, tanpa toleransi spesifik","Ammeter dikalibrasi minimal tiap 6 bulan dengan toleransi +-10% dari reading, dan alat ukur harus punya calibration cert traceable ke national standard","Toleransi ammeter +-25% dan kalibrasi tahunan saja sudah memadai","Calibration certificate tidak diperlukan selama operator certified"]', 1,
   'Ammeter dikalibrasi minimal setiap 6 bulan terhadap reference meter tersertifikasi dengan toleransi +-10% dari reading pada beberapa titik rentang. Semua alat ukur (gaussmeter, radiometer, dll.) wajib memiliki calibration certificate traceable ke national standard (mis. NIST) dengan due date yang dimonitor.', 'Audit & Calibration', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 10 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Case 1 — Crankshaft fillet (wet fluorescent, multi-directional)', '{"slides":[{"heading":"Komponen & setup","body":"Forged 4340 crankshaft, journal fillet radius ~6 mm. Teknik: wet fluorescent continuous, multi-directional (head shot ~1200 A circular + central conductor untuk longitudinal). Konsentrasi bath fluorescent diverifikasi via settling test = 0.25 mL/100 mL (dalam rentang 0.1-0.4 mL/100 mL per ASTM E1444). UV-A 1350 uW/cm2 at 38 cm (>= 1000), ambient 12 lux (<= 20). Acceptance per AMS spec komponen dengan ASTM E1444 sebagai standar proses."},{"heading":"Indikasi yang ditemukan","body":"Indikasi linear menyala terang panjang 4 mm tepat di fillet radius, tegak lurus sumbu poros. Cross-check: tetap muncul setelah cleaning ringan dan re-bath, dan TIDAK hilang/berpindah saat arah shot diputar — artinya bukan magnetic writing/non-relevant. Lokasi fillet = zona stress concentration tinggi (fatigue-prone)."},{"heading":"Evaluasi vs code","body":"Verifikasi sebagai indikasi relevan: linear (L/W >= 3), tegak lurus arah principal stress (rawan fatigue). Untuk komponen rotating fatigue-critical, setiap indikasi linear crack-like adalah rejectable tanpa toleransi panjang. Demagnetize lalu residual field dicek = 1.5 G (< 3 G batas umum)."},{"heading":"Keputusan & verifikasi repair","body":"REJECT — fatigue crack di fillet pada crankshaft critical umumnya tidak dapat di-repair; komponen di-scrap (bukan kandidat blend/grind). Jika drawing mengizinkan blend pada kasus serupa, repair-verify: grind hingga radius minimum yang diizinkan, MT ulang full multi-directional, konfirmasi clean, demag dan residual < 3 G, dokumentasikan kedalaman blend vs allowable."}]}', 460, NULL),
  (2, 'reading', 'Case 2 — Weld toe pipa/struktur (AWS D1.1 / ASME V Article 7)', '{"slides":[{"heading":"Komponen & setup","body":"Fillet weld struktur baja A36, sambungan dynamic-loaded bracket. Teknik: yoke AC, dry magnetic powder, continuous technique. Lift check yoke AC = 4.6 kg (memenuhi >= 4.5 kg AC), white light >= 1100 lux, leg/pole spacing yoke ~100-150 mm, dua arah ortogonal (rotasi yoke 90 deg) agar menangkap diskontinuitas segala orientasi."},{"heading":"Indikasi yang ditemukan","body":"Indikasi linear sepanjang weld toe panjang 9 mm dan satu cluster rounded di crater. AWS D1.1 kriteria visual/MT untuk sambungan cyclically/dynamically loaded: (1) tidak boleh ada crack/indikasi linear; (2) rounded indication > 5 mm (3/16 in) tidak diperbolehkan; rounded yang lebih kecil dibatasi jumlah/spacing."},{"heading":"Evaluasi vs code","body":"Indikasi toe = crack linear -> rejectable mutlak pada beban dinamis (no crack allowance). Crater cluster: ukur tiap rounded; satu indikasi terukur 6 mm -> melebihi 5 mm -> reject. ASME V Article 7 mensyaratkan: evaluasi hanya setelah indikasi diverifikasi relevan (bukan magnetic noise) dan setelah pencahayaan serta lift power dikonfirmasi memenuhi sebelum sign-off."},{"heading":"Keputusan & verifikasi repair","body":"REJECT, kirim ke repair welding. Repair-verify: gouge/grind cacat hingga tuntas, re-weld, lalu MT ulang pada area repair + overlap ~25 mm kedua sisi, dua arah ortogonal, demag dan residual < 3 G bila komponen akan di-machining/dirakit lanjut. Report Level II memuat: lokasi, panjang/ukuran, kriteria yang dilanggar, dan hasil re-inspect PASS dengan tanda tangan."}]}', 480, NULL),
  (3, 'reading', 'Case 3 — False call: non-relevant vs relevant', '{"slides":[{"heading":"Komponen & gejala","body":"Splined shaft carburized. Operator melaporkan banyak indikasi lurus halus paralel pada permukaan. Tugas Level II: bedakan relevant, non-relevant, dan false indication SEBELUM accept/reject agar tidak over-reject komponen yang sebenarnya baik."},{"heading":"Analisis indikasi","body":"(a) Garis lurus paralel mengikuti grain flow & uniform = non-relevant (flow line / section change), bukan crack. (b) Indikasi di akar spline yang mengikuti pola geometri = magnetic writing / flux leakage di perubahan penampang. (c) Bubuk menumpuk di scratch tanpa magnetic hold = false indication (mekanis), hilang saat re-clean & re-mag."},{"heading":"Verifikasi teknik","body":"Demag total, re-clean, set amperage ke level yang benar (over-magnetization menimbulkan furring / indikasi non-relevant). Re-test: indikasi non-relevant melemah/hilang dengan arah & level yang tepat; crack relevan tetap tajam dan reproducible. Cek field adequacy dengan pie gauge / QQI shim."},{"heading":"Keputusan","body":"ACCEPT untuk indikasi non-relevant & false setelah dikonfirmasi; hanya satu indikasi melintang non-geometris yang tetap muncul = relevant -> dievaluasi vs code. Dokumentasikan justifikasi non-relevant (geometri/flow) agar audit-traceable. Level II yang bertanggung jawab atas keputusan evaluasi ini, bukan operator Level I."}]}', 460, NULL),
  (4, 'reading', 'Case 4 — System performance failure saat audit', '{"slides":[{"heading":"Skenario QC","body":"Saat verifikasi harian, Ketos / KOWA ring (ASTM E1444 Tool No. 3) dengan central conductor di-shot pada amperage standar. Jumlah hole indication yang terlihat lebih sedikit dari minimum yang dipersyaratkan untuk amperage tsb. Ini menandakan degradasi sensitivitas sistem secara keseluruhan."},{"heading":"Diagnosis akar masalah","body":"Cek berurutan: settling test bath fluorescent (target 0.1-0.4 mL/100 mL) ternyata 0.05 mL -> bath lemah/terkontaminasi. UV-A diukur 820 uW/cm2 at 38 cm (< 1000 minimum) -> bulb menurun. Ambient 28 lux (> 20 lux batas untuk fluorescent) -> kontras buruk. Ketiganya menurunkan deteksi."},{"heading":"Tindakan koreksi","body":"Quarantine sistem (tidak boleh dipakai inspeksi). Replenish/ganti bath lalu ukur ulang konsentrasi; ganti bulb UV-A & re-verify >= 1000 uW/cm2; kurangi cahaya ambient hingga <= 20 lux. Re-run Ketos ring dan pie gauge sampai jumlah indikasi memenuhi standar sebelum sistem dikembalikan ke produksi."},{"heading":"Implikasi & dokumentasi","body":"Komponen yang diinspeksi sejak kalibrasi terakhir yang valid harus dievaluasi untuk re-inspeksi (impact assessment). Level II menandatangani corrective action record + calibration cert baru. Prinsip: keputusan ''accept'' dari sistem out-of-cal tidak sah dan harus ditelusuri."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — MT-L2 field case studies', '{"description":"6 soal studi kasus lapangan: evaluasi indikasi, keputusan accept/reject/repair-verify, dan diagnosis QC sistem.","questionCount":6,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 10
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 10 mini-quiz (6 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada crankshaft 4340, ditemukan indikasi linear 4 mm tegak lurus sumbu tepat di fillet radius journal, tetap muncul setelah re-clean dan re-bath serta tidak berpindah saat arah shot diputar. Apa keputusan Level II yang paling tepat?',
   '["Reject — fatigue crack di fillet komponen rotating critical, umumnya di-scrap","Accept, karena panjang < 5 mm masih dalam toleransi umum","Abaikan sebagai non-relevant karena berada di perubahan penampang","Tingkatkan amperage lalu re-test untuk menghilangkan indikasi"]', 0,
   'Indikasi linear crack-like di fillet (zona stress concentration) pada komponen fatigue-critical rotating bersifat rejectable tanpa toleransi panjang; karena tidak berpindah saat arah diputar, ia relevan (bukan magnetic writing). Crankshaft critical umumnya di-scrap. Menaikkan amperage tidak menghilangkan crack relevan, justru memperburuk indikasi non-relevant.', 'Case Studies', 'medium'),
  ('Pada fillet weld dynamically loaded yang dievaluasi dengan AWS D1.1, ditemukan indikasi linear (crack) di weld toe dan satu rounded indication terukur 6 mm di crater. Bagaimana evaluasi yang benar?',
   '["Accept keduanya selama total panjang gabungan < 25 mm","Reject crack toe, tapi accept rounded karena rounded selalu diizinkan","Reject keduanya: crack linear tidak diizinkan dan rounded > 5 mm melebihi batas","Accept crack toe karena dangkal, reject hanya rounded"]', 2,
   'Untuk sambungan cyclically/dynamically loaded, AWS D1.1 tidak mengizinkan crack/indikasi linear sama sekali, dan rounded indication melebihi 5 mm (3/16 in) tidak diperbolehkan. Indikasi 6 mm melampaui batas tersebut, jadi keduanya reject.', 'Case Studies', 'medium'),
  ('Indikasi lurus paralel yang mengikuti grain flow / perubahan penampang dan melemah saat amperage diturunkan ke level yang benar paling tepat diklasifikasikan sebagai:',
   '["Relevant indication (crack) yang harus di-reject","Non-relevant indication akibat geometri / flow line atau over-magnetization","False indication murni mekanis tanpa magnetic hold","Subsurface lack of fusion"]', 1,
   'Indikasi yang mengikuti grain flow atau perubahan penampang dan berkurang dengan amperage yang tepat adalah non-relevant (geometri/flow line, atau magnetic writing dari over-magnetization), bukan crack relevan. False indication adalah penumpukan bubuk mekanis tanpa kebocoran fluks magnetik.', 'Case Studies', 'medium'),
  ('Saat verifikasi harian, Ketos ring (ASTM E1444 Tool No. 3) menampilkan jumlah hole indication LEBIH SEDIKIT dari minimum untuk amperage tersebut. Apa makna dan tindakan pertama yang benar?',
   '["Sistem terlalu sensitif; turunkan konsentrasi bath dan lanjut inspeksi","Hasil normal selama minimal satu hole terlihat; lanjutkan produksi","Sensitivitas sistem menurun; quarantine sistem dan cari akar masalah sebelum inspeksi","Ganti Ketos ring karena ring sudah aus dan teruskan inspeksi"]', 2,
   'Ketos ring menguji performa sistem keseluruhan. Jika jumlah hole yang terlihat kurang dari minimum, sensitivitas turun. Sistem harus di-quarantine dan akar masalah (bath, UV-A, ambient lighting) ditemukan serta dikoreksi sebelum inspeksi dilanjutkan.', 'QC & Audit', 'medium'),
  ('Investigasi kegagalan Ketos ring menemukan: settling fluorescent 0.05 mL/100 mL, UV-A 820 uW/cm2 at 38 cm, ambient 28 lux. Manakah pernyataan yang benar tentang parameter ini untuk inspeksi wet fluorescent?',
   '["Hanya UV-A yang di luar batas; dua lainnya masih oke","Ketiganya di luar batas: bath < 0.1 mL/100 mL, UV-A < 1000 uW/cm2, ambient > 20 lux","Hanya bath yang di luar batas; UV-A dan ambient masih oke","Tidak ada yang di luar batas; kegagalan murni karena ring kotor"]', 1,
   'Settling fluorescent harus 0.1-0.4 mL/100 mL (0.05 terlalu rendah), UV-A minimum 1000 uW/cm2 at 38 cm (820 gagal), dan ambient untuk fluorescent maksimum 20 lux (28 gagal). Ketiganya menurunkan sensitivitas dan menjelaskan kegagalan Ketos ring.', 'QC & Audit', 'hard'),
  ('Setelah weld toe crack di-repair (gouge, re-weld, grind), bagaimana verifikasi MT ulang yang benar oleh Level II?',
   '["MT hanya pada satu arah di titik repair saja, tanpa overlap","Cukup pemeriksaan visual karena area sudah digerinda halus","Tidak perlu re-test; repair welding otomatis menghilangkan cacat","MT ulang area repair plus overlap ~25 mm kedua sisi, dua arah ortogonal, demag dan residual < 3 G bila perlu"]', 3,
   'Repair-verify menuntut MT ulang pada area repair ditambah overlap sekitar 25 mm di kedua sisi, dilakukan dua arah ortogonal untuk menangkap diskontinuitas segala orientasi, lalu demagnetize dan konfirmasi residual field < 3 G bila komponen akan dimachining/dirakit lanjut.', 'Case Studies', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 11 (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Recap A — Teori, magnetisasi & perhitungan field (Modul 1-4)', '{"slides":[{"heading":"Scope Level II & teori magnetik","body":"Sebagai pengingat Modul 1-2: Level II MT berwenang melakukan kalibrasi/setup peralatan, menyusun & me-review written procedure, mengevaluasi indikasi, dan menandatangani report formal — Level I tidak boleh sign-off. Dasar teorinya: material feromagnetik tersusun atas magnetic domain; saat applied field H dinaikkan, kurva B-H melewati region steep (Barkhausen jumps) menuju knee dan saturasi (baja karbon ~1.6-2.1 T). Operasi MT TIDAK perlu saturasi penuh; over-magnetization justru menimbulkan furring dan masking. Target praktis: tangential field 30-60 G (2.4-4.8 kA/m). Dari kurva histeresis kenali: retentivity Br (dasar Residual Technique — perlu material high-carbon/hardened), coercivity Hc (lebar loop; tinggi = magnetically hard, sulit di-demag), dan luas loop = hysteresis loss. Residual field pasca-inspeksi dibatasi tipikal <= 3 G (~240 A/m)."},{"heading":"Demagnetisasi & multi-directional","body":"Demagnetisasi (Modul 2-3) bekerja dengan menerapkan medan reversing yang amplitudonya diturunkan bertahap menuju nol sehingga loop B-H mengecil ke origin; field awal harus >= level magnetisasi sebelumnya (melampaui Hc). AC demag cepat tetapi terbatas skin effect (permukaan saja) sehingga part tebal butuh reversing DC step-down. Multi-directional: karena leakage field maksimum saat defect tegak lurus (90 derajat) dan praktis hilang saat sejajar (0 derajat), perlu minimal dua arah saling tegak lurus — circular (untuk longitudinal defect) + longitudinal (untuk transverse defect). Sequential = field bergiliran terpisah; simultaneous/true multidirectional = beberapa field di-pulse cepat & overlap (umumnya 3-fasa FWDC) sehingga satu shot mendeteksi semua arah — WAJIB wet continuous, tidak bisa residual. Balance tiap arah wajib diverifikasi dengan QQI/shim (bukan sekadar angka arus)."},{"heading":"Perhitungan field strength (Modul 4)","body":"Level II menghitung, bukan menebak, arus — lalu memvalidasi dengan QQI/shim atau Hall-probe Gaussmeter. Circular (head shot): 300-800 A/inch OD (mulai ~500). Prod: 90-110 A/inch spacing untuk tebal < 0.75 in, dan 100-125 A/inch spacing untuk tebal >= 0.75 in; spacing dijaga 2-8 inch; risiko utama arc burn. Central conductor: centered memberi coverage penuh sekali shot (basis OD), sedangkan offset hanya efektif sektor ~4x diameter conductor sehingga part harus diputar. Longitudinal (coil) memakai Ampere-Turns NI = N x I: low fill factor offset NI = 45,000/(L/D); high fill factor NI = 35,000/(L/D+2); L/D dibatasi 2-15. Yang membentuk indikasi adalah komponen tangential field (target window 30-60 G), bukan arus itu sendiri."}]}', 480, NULL),
  (2, 'reading', 'Recap B — Specialty, sizing, prosedur & code (Modul 5-8)', '{"slides":[{"heading":"Specialty techniques & AC vs DC (Modul 5)","body":"Underwater MT (acuan acceptance AWS D3.6M) memakai wet fluorescent + UV-A waterproof lamp dan encapsulated yoke; lift test tetap wajib (AC yoke 4.5 kg / 10 lb, DC yoke 18 kg / 40 lb pada leg spacing maksimum). Cryogenic: hanya material feromagnetik (mis. 9% Ni steel) yang bisa di-MT; austenitic stainless 300-series non-magnetik -> pakai PT/ET. Untuk suhu di bawah titik beku gunakan dry powder; batas WET method ~57 derajat C (carrier menguap), dry method toleran hingga ~315 derajat C dengan high-temp particle. AC vs DC: AC terkonsentrasi di permukaan (skin effect) -> terbaik untuk surface crack dan mudah di-demag; DC/FWDC penetrasi lebih dalam -> subsurface; HWDC memberi agitation pulsatil -> ideal dry powder pada casting/forging kasar."},{"heading":"Indication sizing & evaluation (Modul 6)","body":"Lebar build-up serbuk SELALU lebih besar dari lebar fisik crack (leakage field melebar) — maka acceptance memakai PANJANG indikasi; lebar hanya untuk klasifikasi. Linear bila length > 3 x width; rounded bila length <= 3 x width. Indikasi segaris dengan gap <= 1.6 mm (1/16 in) edge-to-edge dijumlahkan sebagai satu indikasi (aturan summing). Per ASME VIII Div 1 App 6: relevant = berdimensi > 1.6 mm; SEMUA relevant linear = reject; relevant rounded > 5 mm (3/16 in) = reject; empat+ rounded segaris dengan jarak <= 1.6 mm = reject. Bedakan relevant vs non-relevant (geometri) vs false (scale/fingerprint/magnetic writing). MT TIDAK mengukur kedalaman kuantitatif — hanya estimasi kualitatif (tinggi/ketebalan/persistensi build-up); verifikasi true depth dengan UT atau grind-and-recheck. Sizing sah hanya pada field tangential terverifikasi (30-60 G)."},{"heading":"Procedure development & code interpretation (Modul 7-8)","body":"Written procedure Level II harus menyatakan essential variables dengan RANGE yang di-qualify: material/scope, teknik (wet/dry, fluorescent/visible, continuous/residual), jenis arus & waveform (AC/HWDC/FWDC), arah & urutan magnetisasi, amperage/ampere-turns, metode verifikasi field (QQI/shim, Gaussmeter), surface prep & lighting, demagnetisasi & batas residual, acceptance code+edisi, dan personnel qualification. Procedure baru di-demonstrate/qualify sebelum dipakai. Code interpretation: ASME V Article 7 = metode (dipasangkan acceptance ASME VIII App 6 atau B31.x); ASTM E709 (guide teknik) + E1444 (practice); ISO 9934 (metode) + ISO 23278 (acceptance level 1/2/3); AWS D1.1 membedakan statically vs cyclically loaded — pada edisi 2015/lebih lama bagian Inspection ada di Clause 6/Table 6.1, lalu DI-RENUMBER menjadi Clause 8/Table 8.1 mulai edisi 2020 (tetap Clause 8 di edisi 2020 & 2025). Code & edisi WAJIB dipilih SEBELUM mengukur dan dicatat di report."}]}', 480, NULL),
  (3, 'reading', 'Recap C — QC/audit, case studies & kesiapan exam (Modul 9-10)', '{"slides":[{"heading":"Quality control & audit (Modul 9)","body":"System performance check harian (per ASTM E1444) yang harus hafal: lift test (AC yoke >= 4.5 kg / 10 lb; DC/HWDC yoke >= 18 kg / 40 lb pada leg spacing maksimum); akurasi ammeter dalam +/-10%; quick-break check; bath concentration via settling test pada centrifuge tube 100 mL selama ~30 menit — fluorescent 0.1-0.4 mL/100 mL, visible 1.2-2.4 mL/100 mL; UV-A >= 1000 microW/cm2 pada 38 cm (15 in) dengan ambient white light <= 20 lux (~2 fc) untuk fluorescent; white light >= 1000 lux untuk visible/colour-contrast; residual field <= 3 G. System performance/overall verification (Ketos/Betz ring per ASTM E1444) dan pie gauge/QQI memverifikasi kemampuan sistem mendeteksi. Semua hasil dicatat sebagai auditable quality record; calibration cert peralatan diperbarui sesuai jadwal."},{"heading":"Field inspection case studies (Modul 10)","body":"Pelajaran kunci dari studi kasus lapangan: pilih waveform/teknik sesuai defek & geometri (AC untuk fatigue/grinding/weld-toe crack permukaan; HWDC+dry untuk weld kasar; central conductor untuk komponen berlubang menghindari arc burn). Selalu magnetisasi dua arah dan verifikasi balance dengan shim sebelum menilai. Pisahkan non-relevant (perubahan section, keyway, fusion line) dari relevant. Setelah repair (grind/weld), lakukan inspeksi BARU lengkap — bukan spot-check — termasuk demagnetisasi dan verifikasi residual <= 3 G. Disposisi: ACCEPT / REJECT / REPAIR & RE-INSPECT; hanya Level II+ yang menandatangani final accept/reject. Report wajib mencatat lokasi (sketch), panjang & klasifikasi tiap relevant indication, arah magnetisasi, field terverifikasi, teknik, code+edisi, disposisi, dan estimasi kedalaman dengan catatan keterbatasan MT."},{"heading":"Kesiapan practice exam","body":"Setelah recap ini Anda akan mengerjakan PRACTICE EXAM 25 soal yang mencakup SELURUH silabus MT-L2 (Modul 1-10): teori magnetik & histeresis, demagnetisasi, multi-directional, perhitungan ampere-turns/prod/circular, specialty (underwater/cryo/AC-DC), sizing & klasifikasi, procedure development, code interpretation (ASME/ASTM/ISO/AWS), serta QC/audit & disposisi. Tips: baca pertanyaan hitungan dengan cermat (NI vs I; cap L/D 2-15; threshold tebal prod 0.75 in), ingat angka kunci (30-60 G, 1.6 mm, 5 mm, 4.5/18 kg, 1000 microW/cm2 @ 38 cm, <= 3 G), dan bedakan length-untuk-acceptance vs width-untuk-klasifikasi. Latihan ini menyiapkan Anda untuk Final Assessment (60 soal, 120 menit, minimal 80%)."}]}', 440, NULL),
  (4, 'quiz', 'Practice Exam — MT Level II (25 soal, seluruh silabus)', '{"description":"Practice exam komprehensif 25 soal mencakup seluruh silabus MT Level II (Modul 1-10): teori magnetik & histeresis, demagnetisasi, multi-directional, perhitungan field strength, specialty techniques, indication sizing & evaluation, procedure development, code interpretation, serta QC/audit & disposisi. Persiapan menuju Final Assessment.","questionCount":25,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 11
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 11 mini-quiz (25 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Manakah kewenangan yang membedakan MT Level II dari Level I?',
   '["Mengaplikasikan magnetic particle bath ke permukaan","Membersihkan part sebelum inspeksi","Menyusun/me-review written procedure dan menandatangani final accept/reject report","Memposisikan yoke pada weld"]', 2,
   'Level II berwenang menyusun & me-review written procedure, kalibrasi/setup, evaluasi indikasi, dan menandatangani final accept/reject report. Aplikasi bath, cleaning, dan pemosisian yoke adalah tugas yang juga dapat dilakukan Level I; sign-off formal tidak boleh dilakukan Level I.', 'Scope & Authority', 'easy'),
  ('Pada kurva B-H, coercive force (Hc) yang tinggi pada baja menunjukkan bahwa material tersebut:',
   '["Magnetically hard — sulit didemagnetisasi dan butuh reverse field besar","Memiliki permeability sangat tinggi sehingga mudah jenuh","Tidak dapat menahan residual field sama sekali","Hanya cocok untuk continuous technique, tidak pernah residual"]', 0,
   'Coercivity tinggi = loop lebar pada sumbu H = material magnetically hard yang sulit didemagnetisasi (butuh reverse field besar) dan biasanya berkorelasi dengan kekerasan mekanik serta retentivity tinggi. High-carbon/hardened steel yang Hc tinggi justru cocok untuk residual technique.', 'Magnetic Theory', 'medium'),
  ('Mengapa Residual Technique hanya cocok untuk material seperti high-carbon atau hardened steel?',
   '["Karena permeability-nya mendekati nol","Karena retentivity (Br) tinggi sehingga menahan field sisa cukup kuat setelah arus dimatikan","Karena retentivity-nya rendah sehingga field cepat hilang","Karena hanya material lunak yang mampu menahan flux"]', 1,
   'Residual technique mengandalkan field sisa setelah arus mati, jadi membutuhkan retentivity (Br) tinggi seperti pada baja keras. Material soft/low-carbon retentivity rendah sehingga harus memakai Continuous Technique.', 'Magnetic Theory', 'medium'),
  ('Apa prinsip dasar proses demagnetisasi yang benar?',
   '["Menerapkan DC konstan satu arah hingga part jenuh","Menaikkan H terus-menerus melampaui saturasi tanpa pembalikan","Menerapkan satu pulsa tunggal berlawanan arah lalu berhenti","Menerapkan medan bolak-balik (reversing) dengan amplitudo diturunkan bertahap menuju nol, dengan field awal >= level magnetisasi sebelumnya"]', 3,
   'Demagnetisasi menggambar hysteresis loop yang makin mengecil ke origin: medan dibalik polaritasnya berulang sambil amplitudonya diturunkan bertahap ke nol, mengacak ulang orientasi domain sehingga Br mendekati nol. Field awal harus >= level magnetisasi sebelumnya (melampaui Hc).', 'Demagnetization', 'medium'),
  ('Untuk part tebal yang dimagnetisasi DC, mengapa AC coil demagnetization mungkin tidak sepenuhnya efektif?',
   '["AC mengalami skin effect sehingga hanya efektif di lapisan permukaan, meninggalkan residual di inti","AC tidak membalik polaritas sehingga tidak mengacak domain","AC menghasilkan field yang terlalu kuat untuk part tebal","AC tidak dapat diturunkan amplitudonya secara bertahap"]', 0,
   'Karena skin effect, arus AC terkonsentrasi di permukaan dan kurang menembus inti part tebal sehingga residual bisa tertinggal di cross-section dalam. Reversing DC step-down penetrasinya lebih dalam dan lebih sesuai untuk part tebal.', 'Demagnetization', 'hard'),
  ('Mengapa inspeksi MT konvensional memerlukan minimal dua arah magnetisasi yang saling tegak lurus?',
   '["Untuk menggandakan kuat field agar penetrasi lebih dalam","Agar residual field tersimpan lebih kuat di material","Karena defect terdeteksi paling baik saat tegak lurus terhadap field dan praktis hilang saat sejajar, sehingga arah kedua mencakup orientasi yang terlewat","Karena satu arah hanya bekerja untuk material feromagnetik dan arah lain untuk non-feromagnetik"]', 2,
   'Sensitivitas maksimum saat defect tegak lurus (90 derajat) terhadap flux dan hilang saat sejajar (0 derajat). Maka diperlukan circular field (untuk longitudinal defect) dan longitudinal field (untuk transverse defect) agar semua orientasi tercover.', 'Multi-Directional', 'easy'),
  ('Apa perbedaan inti antara metode sequential (two-shot) dan simultaneous (true multidirectional)?',
   '["Sequential memakai AC sedangkan simultaneous selalu memakai HWDC","Sequential mengaplikasikan tiap field secara terpisah bergantian, sementara simultaneous men-switch dua/tiga field cepat & overlap sehingga satu aplikasi mendeteksi semua arah","Sequential hanya untuk part kecil, simultaneous hanya untuk part besar","Sequential tidak memerlukan wet bath sedangkan simultaneous memerlukannya"]', 1,
   'Sequential = field diaplikasikan satu per satu dalam langkah terpisah. Simultaneous/true multidirectional = beberapa field di-pulse sangat cepat dan overlapping sehingga partikel basah sempat build-up pada tiap arah, menghasilkan deteksi semua orientasi dalam satu shot. Keduanya memerlukan wet continuous.', 'Multi-Directional', 'medium'),
  ('Menurut ASTM E1444, alat utama untuk memverifikasi bahwa seluruh arah field pada shot multidirectional adekuat dan seimbang adalah:',
   '["Pengukuran arus puncak saja dengan ammeter","Pie gauge tunggal di tengah part","Visual estimate dari kepadatan partikel","QQI / artificial flaw shim (mis. 3C2/4C2) ditempel di beberapa lokasi dengan slot menghadap arah berbeda"]', 3,
   'E1444 mensyaratkan QQI/artificial flaw shim untuk verifikasi multidirectional. Bila semua arah field adekuat dan seimbang, seluruh kaki slot shim terisi indikasi merata; bila satu arah lemah, kaki slot pada arah itu tidak terbentuk. Angka arus saja tidak membuktikan adequacy pada geometri nyata.', 'Multi-Directional', 'medium'),
  ('Untuk head shot (direct circular) pada poros baja solid, rule praktis amperage ASTM E1444 adalah:',
   '["300-800 A per inch outside diameter (OD), umumnya mulai ~500 A/inch","90-125 A per inch spacing","35,000 A per inch panjang","45,000 A dibagi L/D"]', 0,
   'Head shot circular memakai 300-800 A per inch OD (umumnya mulai ~500 A/inch), lalu divalidasi dengan QQI/shim. 90-125 A/inch spacing adalah prod; 45,000/(L/D) adalah ampere-turns coil low fill factor.', 'Field Calculation', 'medium'),
  ('Shaft L = 12 inch, D = 3 inch diinspeksi dalam coil 4-turn dengan low fill factor (offset, dekat dinding coil). Berapa arus yang harus di-set?',
   '["11,250 A","2,812 A","2,250 A","9,000 A"]', 1,
   'L/D = 12/3 = 4 (dalam range 2-15). NI = 45,000/(L/D) = 45,000/4 = 11,250 ampere-turns. I = NI/N = 11,250/4 = 2,812.5 A ~ 2,812 A. 11,250 A adalah NI bukan arus.', 'Field Calculation', 'hard'),
  ('Part dengan L/D = 5 dililit rapat dalam cable wrap (high fill factor) memakai coil 5-turn. Berapa arus yang dibutuhkan?',
   '["1,800 A","9,000 A","1,000 A","5,000 A"]', 2,
   'High fill factor: NI = 35,000/(L/D+2) = 35,000/(5+2) = 5,000 ampere-turns. I = NI/N = 5,000/5 = 1,000 A. 1,800 A adalah hasil low fill factor untuk L/D=5 (45,000/5=9,000 dibagi 5 turn); 5,000 A adalah NI bukan arus.', 'Field Calculation', 'hard'),
  ('Pelat baja tebal 1 inch diinspeksi dengan prods berjarak (spacing) 6 inch. Arus yang sesuai memakai 125 A/inch adalah:',
   '["540 A","600 A","1,250 A","750 A"]', 3,
   'Tebal 1 in >= 0.75 in maka gunakan 100-125 A/inch spacing. Pada 125 A/inch: 125 x 6 = 750 A. Rentang 90-110 A/inch hanya berlaku untuk tebal < 0.75 in.', 'Field Calculation', 'medium'),
  ('Pada magnetisasi sirkular dengan central conductor offset (menempel ID part berlubang), kapan coverage keliling penuh tercapai?',
   '["Hanya sektor efektif ~4x diameter conductor per shot, sehingga part harus diputar beberapa posisi","Selalu — satu shot mencakup seluruh keliling part","Hanya jika arus dinaikkan 2x","Tidak pernah — teknik offset dilarang ASTM"]', 0,
   'Offset (distributed) conductor hanya efektif menginspeksi sektor ~4x diameter conductor di sekitar titik kontak per shot; part harus diputar beberapa kali (dengan overlap) untuk full circumferential coverage. Centered conductor memberi coverage merata dalam satu shot.', 'Field Calculation', 'hard'),
  ('Mengapa AC lebih unggul daripada DC untuk mendeteksi surface-breaking crack pada MT?',
   '["Skin effect membuat flux AC terkonsentrasi di permukaan, menguatkan leakage field crack permukaan","AC menembus jauh lebih dalam ke bawah permukaan daripada DC","AC menghasilkan residual field yang jauh lebih tinggi sehingga indikasi lebih kuat","AC tidak memerlukan partikel untuk membentuk indikasi"]', 0,
   'Karena skin effect, arus AC terkonsentrasi di permukaan sehingga flux paling kuat tepat di permukaan dan optimal untuk surface-breaking discontinuity. Penetrasi AC justru dangkal; DC/FWDC yang lebih sensitif untuk subsurface.', 'Specialty Techniques', 'easy'),
  ('Komponen cryogenic dari austenitic stainless steel 304 perlu diperiksa retak permukaan. Metode yang tepat adalah:',
   '["MT dengan dry powder karena tidak membeku","MT dengan wet fluorescent dan UV lamp","PT atau ET karena 304 bersifat non-magnetik (non-feromagnetik)","MT dengan central conductor untuk field melingkar"]', 2,
   'Austenitic stainless 300-series umumnya non-magnetik sehingga MT tidak berlaku. Gunakan PT atau ET. MT hanya valid pada material feromagnetik seperti 9% Ni steel atau martensitic/duplex.', 'Specialty Techniques', 'medium'),
  ('Pernyataan mana yang BENAR mengenai batas suhu metode MT?',
   '["Di atas 57 derajat C baja kehilangan sifat feromagnetik sehingga MT tidak bisa dilakukan","Baik wet maupun dry method sama-sama dibatasi 57 derajat C","Dry powder otomatis menghilangkan ice film pada permukaan dingin","~57 derajat C adalah batas WET method (carrier menguap); dry method toleran lebih tinggi, high-temp dry particle hingga ~315 derajat C"]', 3,
   'Batas ~57 derajat C (135 derajat F) berlaku untuk WET method karena carrier menguap. Dry powder method jauh lebih toleran; high-temp dry particle khusus berfungsi hingga ~315 derajat C. Curie point baja jauh di atas itu (~770 derajat C).', 'Specialty Techniques', 'hard'),
  ('Pada underwater MT, mengapa lift test yoke tetap wajib dan berapa nilainya?',
   '["Tidak wajib karena air membantu mengangkat yoke","Wajib: AC yoke minimal 4.5 kg (10 lb) dan DC yoke minimal 18 kg (40 lb) pada leg spacing maksimum, diverifikasi sebelum dive","Wajib: AC dan DC yoke sama-sama minimal 18 kg","Wajib hanya untuk permanent magnet, bukan electromagnet"]', 1,
   'Lift test membuktikan kemampuan angkat yoke: AC yoke minimal 4.5 kg (10 lb) dan DC yoke minimal 18 kg (40 lb) pada leg spacing maksimum yang akan dipakai, diverifikasi di permukaan sebelum dive. Air tidak membantu, dan lift test tidak mengukur field strength kuantitatif.', 'Specialty Techniques', 'medium'),
  ('Mengapa lebar build-up serbuk magnetik tidak boleh dipakai langsung sebagai lebar fisik crack?',
   '["Karena leakage field melebar di atas permukaan sehingga build-up lebih lebar dari crack","Karena serbuk selalu lebih sempit dari crack sebenarnya","Karena lebar tidak pernah dapat diukur dengan scale","Karena lebar hanya relevan pada subsurface indication"]', 0,
   'Magnetic leakage field menyebar di atas permukaan sehingga lebar akumulasi serbuk hampir selalu lebih besar dari lebar fisik crack. Karena itu evaluasi acceptance memakai PANJANG indikasi; lebar hanya untuk klasifikasi linear vs rounded.', 'Indication Sizing', 'easy'),
  ('Sebuah indikasi memiliki panjang 9 mm dan lebar 2 mm. Bagaimana klasifikasinya (linear bila length > 3 x width)?',
   '["Rounded, karena lebar < 3 mm","Non-relevant, karena disebabkan geometri","Linear, karena 9 mm > 3 x 2 mm (6 mm)","False indication, karena rasio terlalu besar"]', 2,
   'Linear bila length > 3 x width. Di sini 9 mm > 6 mm (rasio L/W = 4.5), jadi linear, dan dievaluasi dengan acceptance criteria untuk linear indication.', 'Indication Sizing', 'medium'),
  ('Dua indikasi segaris dipisahkan gap 1.2 mm edge-to-edge. Menurut konvensi summing ASME (Section VIII App 6 / E1444), bagaimana keduanya dievaluasi?',
   '["Sebagai dua indikasi terpisah, masing-masing diukur sendiri","Sebagai satu indikasi tunggal dengan panjang dijumlahkan termasuk gap","Diabaikan karena gap menandakan non-relevant","Otomatis reject tanpa pengukuran"]', 1,
   'Indikasi segaris yang dipisah gap <= 1.6 mm (1/16 in) edge-to-edge diperlakukan sebagai satu indikasi tunggal dan panjangnya dijumlahkan termasuk gap. Mengukurnya terpisah bisa keliru meloloskan indikasi yang sebenarnya rejectable.', 'Indication Sizing', 'medium'),
  ('Manakah pernyataan yang BENAR tentang kemampuan MT mengukur kedalaman diskontinuitas?',
   '["MT memberikan kedalaman kuantitatif akurat seperti UT","MT mengukur kedalaman dari lebar build-up secara presisi","MT hanya bisa mengukur kedalaman pada material non-feromagnetik","MT tidak mengukur kedalaman secara langsung; hanya estimasi kualitatif dari karakter indikasi"]', 3,
   'MT adalah metode permukaan/dekat-permukaan dan tidak memberi kedalaman kuantitatif. Kedalaman hanya diestimasi kualitatif (tinggi/ketebalan/ketajaman & persistensi build-up); verifikasi true depth memakai UT atau grind-and-recheck.', 'Indication Sizing', 'easy'),
  ('Per ASME VIII Div 1 App 6, manakah pernyataan acceptance yang BENAR untuk relevant indication?',
   '["Semua relevant linear indication adalah rejectable; relevant rounded rejectable bila > 5 mm (3/16 in)","Linear indication acceptable selama panjangnya <= 1.6 mm","Rounded indication selalu rejectable, linear selalu acceptable","Hanya indikasi subsurface yang dievaluasi terhadap acceptance criteria"]', 0,
   'Per ASME VIII App 6, indikasi relevant berdimensi > 1.6 mm (1/16 in). Semua relevant linear indication adalah rejectable; relevant rounded acceptable kecuali > 5 mm (3/16 in), atau bila ada empat+ rounded segaris dengan jarak edge-to-edge <= 1.6 mm. Indikasi <= 1.6 mm justru tergolong non-relevant, bukan ''linear acceptable''.', 'Code Interpretation', 'hard'),
  ('Mengenai standar MT, pasangan mana yang BENAR?',
   '["ASME V Article 7 adalah acceptance criteria, sedangkan ASME VIII App 6 adalah metode","ASTM E709 adalah practice wajib, sedangkan ASTM E1444 hanya guide non-mandatory","ASME V Article 7 = metode (acceptance dari ASME VIII App 6 / B31.x); ISO 9934 = metode dengan acceptance di ISO 23278; AWS D1.1 membedakan statically vs cyclically loaded","ISO 23278 mengatur metode pengujian dan ISO 9934 mengatur acceptance level"]', 2,
   'ASME V Article 7 menetapkan metode dan dipasangkan dengan acceptance dari ASME VIII App 6 atau B31.x; ISO 9934 (metode) dipasangkan ISO 23278 (acceptance level 1/2/3); AWS D1.1 membedakan statically vs cyclically loaded. Catatan: E709 adalah guide dan E1444 adalah standard practice (sering mandatory bila dirujuk kontrak).', 'Code Interpretation', 'medium'),
  ('Saat menyusun written procedure MT Level II, manakah yang merupakan essential variable yang HARUS dinyatakan dengan range yang di-qualify?',
   '["Warna seragam operator dan merek senter","Jenis arus/waveform, arah & urutan magnetisasi, amperage/ampere-turns, metode verifikasi field, dan acceptance code+edisi","Nama pelanggan dan nomor purchase order saja","Suhu ruangan kantor administrasi"]', 1,
   'Essential variables dalam written procedure mencakup teknik (wet/dry, fluorescent/visible, continuous/residual), jenis arus & waveform, arah & urutan magnetisasi, amperage/ampere-turns, metode verifikasi field (QQI/Gaussmeter), surface prep & lighting, demagnetisasi & batas residual, serta acceptance code+edisi. Procedure baru di-demonstrate/qualify sebelum dipakai.', 'Procedure Development', 'medium'),
  ('Saat system performance / overall verification harian pada booth MT fluorescent (per ASTM E1444), kombinasi nilai mana yang BENAR?',
   '["UV-A >= 100 microW/cm2 pada 1 m; white light tak dibatasi; settling test fluorescent 1.2-2.4 mL/100 mL","UV-A >= 5000 microW/cm2 pada 10 cm; residual field <= 50 G; settling test 0.5-1.0 mL/100 mL","UV-A >= 1000 microW/cm2 pada 38 cm (15 in); ambient white light <= 20 lux (~2 fc); settling test fluorescent 0.1-0.4 mL/100 mL; residual field <= 3 G","UV-A >= 1000 microW/cm2 pada 38 cm; ambient white light >= 1000 lux; settling test fluorescent 1.2-2.4 mL/100 mL"]', 2,
   'Per ASTM E1444 untuk fluorescent: UV-A >= 1000 microW/cm2 pada ~38 cm (15 in), ambient white light <= 20 lux (~2 fc), settling test fluorescent 0.1-0.4 mL/100 mL (visible 1.2-2.4 mL/100 mL), dan residual field <= 3 G. White light >= 1000 lux justru syarat untuk visible/colour-contrast, bukan booth fluorescent.', 'QC & Audit', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


