-- MT-L2 Module 12 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'quiz', 'FINAL ASSESSMENT — MT Level II', '{"description":"Ujian sertifikasi MT Level II — 60 soal · 120 menit · minimal 80% lulus.","questionCount":60,"passingScore":80}', 7200, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 12
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 12 mini-quiz (60 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada kurva histeresis B-H bahan feromagnetik, retentivitas (Br) didefinisikan sebagai:',
   '["Densitas fluks residual yang tertinggal saat gaya magnetisasi H dikembalikan ke nol","Gaya magnetisasi yang diperlukan untuk membawa B kembali ke nol","Densitas fluks maksimum saat saturasi","Kemiringan kurva pada titik asal"]', 0,
   'Retentivitas (remanensi, Br) adalah densitas fluks yang tersisa di dalam material setelah H diturunkan ke nol. Gaya untuk membawa B ke nol adalah koersivitas (Hc), bukan retentivitas.', 'Advanced Magnetic Theory', 'easy'),
  ('Koersivitas (Hc) suatu bahan menggambarkan:',
   '["Densitas fluks residual setelah H = 0","Gaya demagnetisasi (H berlawanan arah) yang diperlukan untuk membawa B kembali ke nol","Permeabilitas maksimum bahan","Titik saturasi magnetik"]', 1,
   'Koersivitas Hc adalah besarnya gaya magnetisasi berlawanan arah yang dibutuhkan untuk menghilangkan densitas fluks residual (membawa B ke nol). Material dengan Hc tinggi sulit didemagnetisasi.', 'Advanced Magnetic Theory', 'easy'),
  ('Permeabilitas magnetik (µ) suatu material didefinisikan sebagai:',
   '["Selisih antara B dan H","Hasil kali B dan H","Luas di dalam loop histeresis","Rasio B terhadap H (µ = B/H)"]', 3,
   'Permeabilitas µ = B/H, yaitu kemudahan suatu material menghantarkan fluks magnetik. Material berpermeabilitas tinggi mudah dimagnetisasi pada H rendah.', 'Advanced Magnetic Theory', 'easy'),
  ('Luas yang terkurung di dalam loop histeresis (hysteresis loop) sebanding dengan:',
   '["Permeabilitas awal material","Konduktivitas listrik material","Energi yang hilang sebagai panas tiap siklus magnetisasi","Densitas fluks saturasi"]', 2,
   'Luas loop histeresis menyatakan rugi energi (hysteresis loss) yang terdisipasi sebagai panas pada setiap siklus magnetisasi-demagnetisasi. Loop lebar = rugi energi besar = material magnetik keras.', 'Advanced Magnetic Theory', 'medium'),
  ('Material yang ideal untuk magnet permanen umumnya memiliki:',
   '["Retentivitas tinggi dan koersivitas tinggi (magnetik keras)","Retentivitas rendah dan koersivitas rendah (magnetik lunak)","Permeabilitas tak hingga","Koersivitas nol"]', 0,
   'Magnet permanen membutuhkan Br tinggi (mempertahankan fluks) dan Hc tinggi (sulit didemagnetisasi) — ciri material magnetik keras. Material lunak (Hc rendah) justru cocok untuk inti transformator.', 'Advanced Magnetic Theory', 'medium'),
  ('Demagnetisasi paling efektif dicapai dengan:',
   '["Menerapkan DC searah secara perlahan","Memberikan medan AC bolak-balik yang amplitudonya diturunkan bertahap menuju nol","Memanaskan benda hingga 100 °C","Memberikan medan DC konstan yang besar"]', 1,
   'Demagnetisasi dilakukan dengan membalik arah medan berulang sambil menurunkan amplitudonya hingga nol, sehingga loop histeresis mengecil menuju titik asal. AC step-down adalah metode paling umum dan praktis.', 'Advanced Magnetic Theory', 'medium'),
  ('Suatu benda perlu didemagnetisasi karena medan residual berlebih dapat:',
   '["Meningkatkan permeabilitas material secara permanen","Menyebabkan material kehilangan kekuatan tarik","Selalu tidak berpengaruh apa pun terhadap kinerja komponen","Mengganggu proses pemesinan, pengelasan busur (arc blow), atau menarik serbuk besi saat servis"]', 3,
   'Medan residual tinggi dapat menyebabkan arc blow saat pengelasan, menarik gram/serbuk feromagnetik ke permukaan bearing, dan mengganggu instrumen. Karena itu banyak spesifikasi membatasi residual (mis. ≤3 G).', 'Advanced Magnetic Theory', 'hard'),
  ('Hubungan konversi satuan densitas fluks yang benar adalah:',
   '["1 T = 100 G","1 T = 1000 G","1 T = 10000 G","1 T = 1 G"]', 2,
   '1 Tesla = 10.000 Gauss. Konversi ini penting saat menerjemahkan persyaratan kuat medan tangensial yang dinyatakan dalam Gauss ke Tesla atau sebaliknya.', 'Advanced Magnetic Theory', 'easy'),
  ('Kuat medan tangensial yang direkomendasikan pada permukaan benda untuk MT umumnya berada pada rentang:',
   '["5–10 G","30–60 G (sekitar 2,4–4,8 kA/m)","200–400 G","1000–2000 G"]', 1,
   'Kuat medan tangensial yang memadai untuk membentuk indikasi adalah 30–60 G (≈2,4–4,8 kA/m), sering diverifikasi dengan Hall-effect gaussmeter atau shim/QQI.', 'Advanced Magnetic Theory', 'medium'),
  ('Magnetisasi multi-arah (multidirectional) bertujuan utama untuk:',
   '["Mengurangi konsumsi arus total","Mendeteksi diskontinuitas dengan berbagai orientasi dalam satu pengaturan tanpa reposisi berulang","Menghilangkan kebutuhan demagnetisasi","Menggantikan kebutuhan partikel feromagnetik"]', 1,
   'Multidirectional magnetization membangkitkan medan dengan arah bergantian cepat sehingga diskontinuitas pada berbagai orientasi terdeteksi dalam satu shot, mempercepat inspeksi pada bench/automated units.', 'Multi-Directional Magnetization', 'easy'),
  ('Agar magnetisasi multi-arah efektif, syarat krusialnya adalah:',
   '["Kedua/lebih medan diterapkan dengan amplitudo sangat berbeda jauh","Hanya satu medan boleh aktif selama seluruh proses","Partikel harus kering dan tidak boleh basah","Medan-medan diterapkan bergantian (sequenced) cukup cepat sehingga partikel tetap mobile untuk semua arah"]', 3,
   'Pada multidirectional, beberapa medan dibangkitkan secara bergantian/superposisi dengan timing cepat sehingga vektor resultan menyapu berbagai arah selama partikel masih bergerak, memastikan deteksi semua orientasi.', 'Multi-Directional Magnetization', 'medium'),
  ('Verifikasi kecukupan medan pada SETIAP arah dalam teknik multidirectional paling tepat dilakukan dengan:',
   '["Hanya menghitung ampere-turns satu kali","Menempatkan shim/QQI artificial-flaw pada beberapa lokasi & orientasi kritis dan memastikan semua membentuk indikasi","Mengandalkan pie gauge tunggal di tengah","Mengukur suhu permukaan benda"]', 1,
   'Karena medan resultan multidirectional bervariasi di seluruh permukaan, kecukupan tiap arah harus dibuktikan dengan shim/QQI (artificial flaw) pada beberapa lokasi & orientasi, bukan sekadar perhitungan tunggal.', 'Multi-Directional Magnetization', 'hard'),
  ('Pada unit otomatis multidirectional, kombinasi yang umum dipakai untuk menghasilkan dua arah medan ortogonal adalah:',
   '["Dua sumber penetran berbeda warna","Head shot (arus melalui benda) dikombinasikan dengan coil/central conductor","Dua lampu UV-A","Dua gaussmeter Hall"]', 1,
   'Medan sirkular (head shot/central conductor) yang berorientasi melingkar dikombinasikan dengan medan longitudinal (coil) memberi dua arah ortogonal — dasar magnetisasi multidirectional pada bench/automated units.', 'Multi-Directional Magnetization', 'medium'),
  ('Kelemahan utama bila amplitudo salah satu medan multidirectional terlalu dominan dibanding yang lain adalah:',
   '["Konsumsi partikel meningkat drastis","Benda menjadi terlalu panas","Vektor resultan condong ke satu arah sehingga diskontinuitas tegak lurus arah lemah dapat terlewat","Lampu UV-A padam"]', 2,
   'Jika satu medan jauh lebih kuat, resultan akan didominasi arah tersebut dan sensitivitas untuk orientasi yang tegak lurus terhadap medan lemah menurun, berisiko miss. Karena itu balancing amplitudo penting.', 'Multi-Directional Magnetization', 'hard'),
  ('Untuk koil dengan fill-factor rendah (low fill-factor) per ASTM E1444, jumlah ampere-turns dihitung dengan:',
   '["NI = 45000 / (L/D)","NI = 35000 / (L/D + 2)","NI = 300 × D","NI = 90 × spacing"]', 0,
   'Untuk low fill-factor, NI = 45000/(L/D), berlaku pada rentang L/D 2–15. Rumus 35000/(L/D + 2) adalah untuk high fill-factor.', 'Field Strength Calculation', 'easy'),
  ('Untuk koil dengan fill-factor tinggi (high fill-factor) per ASTM E1444, rumus ampere-turns yang benar adalah:',
   '["NI = 45000 / (L/D)","NI = 35000 / (L/D + 2)","NI = 800 × D","NI = 125 × spacing"]', 1,
   'High fill-factor: NI = 35000/(L/D + 2), valid untuk L/D 2–15. Low fill-factor memakai 45000/(L/D).', 'Field Strength Calculation', 'easy'),
  ('Sebuah batang dengan L/D = 5 diinspeksi pada koil low fill-factor. Ampere-turns yang diperlukan ≈:',
   '["5000 A·turns","9000 A·turns","11250 A·turns","4500 A·turns"]', 1,
   'Low fill-factor: NI = 45000/(L/D) = 45000/5 = 9000 A·turns. (Untuk high fill-factor hasilnya 35000/(5+2) = 5000.)', 'Field Strength Calculation', 'medium'),
  ('Batang yang sama dengan L/D = 5 jika diletakkan rapat di dinding koil (high fill-factor) membutuhkan ampere-turns ≈:',
   '["9000 A·turns","11250 A·turns","5000 A·turns","2917 A·turns"]', 2,
   'High fill-factor: NI = 35000/(L/D + 2) = 35000/(5+2) = 35000/7 = 5000 A·turns. Fill-factor tinggi membutuhkan ampere-turns lebih rendah karena kopling magnetik lebih baik.', 'Field Strength Calculation', 'hard'),
  ('Sebuah koil 5 lilitan akan memberi 9000 A·turns. Arus yang harus dialirkan adalah:',
   '["450 A","1800 A","9000 A","45000 A"]', 1,
   'Ampere-turns = N × I, maka I = 9000/5 = 1800 A. Penambahan jumlah lilitan menurunkan arus yang dibutuhkan untuk NI yang sama.', 'Field Strength Calculation', 'medium'),
  ('Untuk magnetisasi sirkular langsung (head shot) pada poros berdiameter 3 inci, rentang arus tipikal 300–800 A per inci diameter memberi:',
   '["100–267 A","300–800 A","3000–8000 A","900–2400 A"]', 3,
   'Sirkular: 300–800 A/in diameter × 3 in = 900–2400 A. Nilai awal yang sering dipakai ~500 A/in, lalu disesuaikan dengan verifikasi shim/gaussmeter.', 'Field Strength Calculation', 'medium'),
  ('Pada teknik prod dengan jarak antar-prod (spacing) 6 inci, rentang arus 90–125 A per inci spacing menghasilkan:',
   '["15–21 A","540–750 A","90–125 A","5400–7500 A"]', 1,
   'Prod: 90–125 A/in spacing × 6 in = 540–750 A. Nilai 100–125 A/in dipakai untuk pelat tebal ≥19 mm; 90–110 A/in untuk yang lebih tipis.', 'Field Strength Calculation', 'medium'),
  ('Rumus ampere-turns koil ASTM E1444 (low & high fill-factor) hanya valid pada rentang rasio L/D:',
   '["0,5–2","2–15","15–50","Tidak ada batas"]', 1,
   'Kedua rumus koil berlaku untuk L/D antara 2 dan 15. Untuk benda dengan L/D <2, panjang efektif harus diperpanjang dengan pole pieces, atau pendekatan lain dipakai.', 'Field Strength Calculation', 'hard'),
  ('Bila L/D sebuah benda lebih kecil dari 2 saat inspeksi koil, tindakan yang tepat adalah:',
   '["Memakai rumus apa adanya tanpa koreksi","Memasang pole pieces (perpanjangan feromagnetik) untuk menaikkan L efektif ke rentang valid","Menggandakan arus secara sembarang","Mengganti partikel basah dengan kering"]', 1,
   'Untuk benda pendek (L/D <2), dipasang pole pieces feromagnetik di kedua ujung agar rasio L/D efektif masuk rentang valid 2–15 sebelum rumus diterapkan.', 'Field Strength Calculation', 'hard'),
  ('Keunggulan central conductor (konduktor pusat) untuk benda berongga seperti pipa adalah:',
   '["Menghasilkan medan longitudinal sepanjang sumbu","Menghilangkan kebutuhan medan tangensial","Hanya bekerja dengan partikel kering","Memagnetisasi permukaan dalam (ID) maupun luar (OD) secara sirkular tanpa kontak listrik langsung ke benda"]', 3,
   'Central conductor mengalirkan arus melalui rongga benda, menciptakan medan sirkular yang melingkupi ID dan OD tanpa kontak prod (menghindari arc burn) — ideal untuk pipa, ring, dan fitting.', 'Field Strength Calculation', 'medium'),
  ('Perbedaan utama arus AC dibanding DC dalam magnetisasi MT adalah:',
   '["AC memberi penetrasi lebih dalam ke subsurface","AC terkonsentrasi di permukaan (skin effect) sehingga lebih sensitif untuk diskontinuitas permukaan","DC hanya bisa dipakai untuk demagnetisasi","AC tidak dapat memagnetisasi baja"]', 1,
   'Karena skin effect, arus AC mengonsentrasikan medan di dekat permukaan sehingga unggul mendeteksi diskontinuitas permukaan. DC/HWDC memberi penetrasi lebih dalam untuk subsurface.', 'Specialty Techniques', 'easy'),
  ('Untuk mendeteksi diskontinuitas subsurface (sedikit di bawah permukaan), pilihan arus yang lebih tepat adalah:',
   '["AC murni","DC atau half-wave DC (HWDC) karena penetrasi lebih dalam","Frekuensi radio","Tegangan tinggi tanpa arus"]', 1,
   'DC penuh dan HWDC menembus lebih dalam dibanding AC, sehingga lebih cocok untuk diskontinuitas subsurface. HWDC juga memberi mobilitas partikel kering yang baik.', 'Specialty Techniques', 'medium'),
  ('Pada inspeksi MT bawah air (underwater MT), pertimbangan khusus yang penting adalah:',
   '["Tidak boleh memakai partikel sama sekali","Wajib memakai lampu pijar 40 W","Hanya boleh DC tegangan rendah tanpa partikel","Memakai partikel/medium yang sesuai dan kontras (mis. fluorescent dengan UV-A subsea) serta kontrol arus dan grounding yang aman"]', 3,
   'Underwater MT biasanya memakai yoke/prod kedap air dengan partikel khusus (sering fluorescent dengan UV-A subsea) dan perhatian pada keselamatan listrik, viskositas medium, serta visibilitas di kondisi bawah air.', 'Specialty Techniques', 'medium'),
  ('Half-wave DC (HWDC) dengan partikel kering sering disukai untuk inspeksi lapangan karena:',
   '["Memberi getaran/pulse yang meningkatkan mobilitas partikel kering sekaligus penetrasi subsurface","Tidak memerlukan kuat medan tangensial","Menghilangkan kebutuhan demagnetisasi","Hanya bekerja pada material non-magnetik"]', 0,
   'HWDC menghasilkan pulsa yang menggetarkan partikel kering sehingga mobilitasnya naik (membantu mereka berkumpul di kebocoran fluks), plus penetrasi subsurface yang lebih baik daripada AC.', 'Specialty Techniques', 'hard'),
  ('Continuous technique (teknik kontinu) pada MT basah berarti:',
   '["Partikel diaplikasikan hanya setelah arus dimatikan","Arus mengalir terus-menerus selama berhari-hari","Aplikasi bath partikel dilakukan saat arus magnetisasi masih mengalir, dan aliran dihentikan sebelum arus dimatikan","Tidak memerlukan medan magnet"]', 2,
   'Pada continuous wet technique, bath partikel dialirkan selama arus aktif dan dihentikan tepat sebelum arus dimatikan, memberi sensitivitas tertinggi. Residual technique mengandalkan Br setelah arus mati (hanya untuk material Br tinggi).', 'Specialty Techniques', 'medium'),
  ('Teknik residual hanya cocok dipakai pada material yang memiliki:',
   '["Permeabilitas sangat tinggi tetapi retentivitas rendah","Retentivitas (Br) cukup tinggi sehingga medan residual mampu menahan partikel di indikasi","Koersivitas nol","Konduktivitas listrik rendah"]', 1,
   'Residual technique mengandalkan medan residual setelah arus mati, sehingga hanya valid untuk material berretentivitas tinggi (mis. baja keras). Material lunak Br rendah harus pakai continuous technique.', 'Specialty Techniques', 'hard'),
  ('Saat melakukan sizing indikasi linier, panjang yang dilaporkan adalah:',
   '["Panjang area basah partikel terlebar","Panjang aktual diskontinuitas yang diukur sepanjang sumbu indikasi (build-up partikel)","Diameter benda uji","Jarak antar dua indikasi"]', 1,
   'Sizing dilakukan dengan mengukur panjang indikasi sepanjang sumbunya. Perlu diingat indikasi MT bisa lebih besar dari flaw sebenarnya akibat magnification, sehingga interpretasi mengikuti kriteria kode.', 'Indication Sizing & Evaluation', 'easy'),
  ('Indikasi diklasifikasikan sebagai relevant bila:',
   '["Disebabkan oleh perubahan geometri atau permeabilitas, bukan diskontinuitas","Selalu < 1,6 mm","Hanya muncul saat arus dimatikan","Disebabkan oleh diskontinuitas aktual dan ukurannya melebihi ambang yang ditetapkan kode (umumnya ≥1,6 mm / 1/16 in)"]', 3,
   'Relevant indication berasal dari diskontinuitas aktual dan biasanya berukuran ≥1,6 mm (1/16 in) per kode seperti ASME V Art 7. Yang dari geometri/permeabilitas adalah non-relevant; yang dari teknik buruk adalah false.', 'Indication Sizing & Evaluation', 'medium'),
  ('Menurut kriteria penerimaan ASME Section V/VIII untuk MT, indikasi linier didefinisikan sebagai indikasi yang:',
   '["Panjangnya kurang dari atau sama dengan tiga kali lebarnya","Panjangnya lebih dari tiga kali lebarnya (L > 3W)","Berbentuk bulat sempurna","Selalu non-relevant"]', 1,
   'Indikasi linier: panjang > 3 × lebar (L > 3W). Indikasi rounded: panjang ≤ 3 × lebar. Klasifikasi ini menentukan kriteria penerimaan yang berlaku.', 'Indication Sizing & Evaluation', 'medium'),
  ('Contoh indikasi non-relevant yang umum pada MT adalah:',
   '["Crack pada toe of weld","Akumulasi partikel pada perubahan penampang, ulir, atau keyway akibat kebocoran fluks geometris","Lack of fusion","Porositas subsurface"]', 1,
   'Non-relevant indications muncul dari kebocoran fluks akibat geometri (perubahan penampang, ulir, keyway, sudut tajam) atau batas permeabilitas, bukan dari cacat. Tetap harus dievaluasi untuk memastikan tidak menutupi cacat nyata.', 'Indication Sizing & Evaluation', 'medium'),
  ('Indikasi ''false'' (palsu) pada MT paling sering disebabkan oleh:',
   '["Diskontinuitas subsurface dalam","Crack permukaan halus","Aplikasi partikel berlebih, kontaminasi, atau gravitasi/aliran sehingga partikel menempel tanpa kebocoran fluks","Kebocoran fluks geometris"]', 2,
   'False indication tidak berkaitan dengan kebocoran fluks: misalnya partikel berlebih, kontaminasi permukaan, scale, atau partikel terjebak gravitasi. Dibedakan dari non-relevant (yang punya kebocoran fluks dari geometri).', 'Indication Sizing & Evaluation', 'hard'),
  ('Menurut kriteria umum ASME (mis. Sec. VIII App. tipikal), indikasi linier dengan panjang melebihi batas (mis. >1,5 mm tergantung kode) biasanya:',
   '["Selalu diterima tanpa evaluasi","Ditolak (rejectable) karena indikasi crack-like linier umumnya tidak diizinkan","Diabaikan jika fluorescent","Hanya dicatat tanpa konsekuensi"]', 1,
   'Indikasi linier (crack-like) umumnya rejectable pada kebanyakan kode karena berpotensi sebagai retak. Kriteria pasti (panjang/jumlah) bergantung kode/spesifikasi spesifik yang diacu.', 'Indication Sizing & Evaluation', 'medium'),
  ('Sebelum mengevaluasi ukuran/relevansi indikasi yang meragukan, Level II sebaiknya:',
   '["Langsung menolak benda","Mengecat indikasi agar lebih terlihat","Mengabaikan indikasi yang lemah","Membersihkan area, melakukan re-magnetisasi atau re-test untuk mengonfirmasi apakah indikasi reproducible/relevant"]', 3,
   'Indikasi meragukan dikonfirmasi dengan membersihkan dan mengulang pengujian; indikasi relevant akan muncul kembali (reproducible). Ini membedakan relevant dari false sebelum keputusan penerimaan.', 'Indication Sizing & Evaluation', 'hard'),
  ('Menurut ASME Section V Article 7, dokumen yang mengatur ''essential variables'' dalam suatu prosedur MT tertulis terdapat pada paragraf:',
   '["T-150","T-721","T-910","T-200"]', 1,
   'ASME V Article 7 mengatur persyaratan prosedur tertulis dan daftar essential/nonessential variables pada T-721. Perubahan essential variable di luar rentang yang dikualifikasi memerlukan kualifikasi ulang prosedur.', 'Procedure Development', 'medium'),
  ('Yang termasuk essential variable dalam prosedur MT (ASME V Art 7) adalah:',
   '["Nama operator","Warna sarung tangan inspektur","Teknik magnetisasi, jenis arus, jenis partikel/medium, dan teknik aplikasi","Tanggal kalibrasi gaussmeter saja"]', 2,
   'Essential variables mencakup teknik magnetisasi, jenis arus (AC/DC/HWDC), jenis partikel (wet/dry, visible/fluorescent), dan teknik aplikasi (continuous/residual). Perubahannya wajib requalification prosedur.', 'Procedure Development', 'medium'),
  ('Perubahan suatu nonessential variable dalam prosedur MT:',
   '["Selalu memerlukan kualifikasi ulang prosedur penuh","Tidak memerlukan kualifikasi ulang, namun perlu revisi dokumen prosedur","Membatalkan seluruh sertifikasi personel","Tidak boleh dilakukan dalam kondisi apa pun"]', 1,
   'Perubahan nonessential variable tidak mengharuskan requalification, tetapi tetap harus dicatat melalui revisi prosedur tertulis sesuai kontrol dokumen.', 'Procedure Development', 'easy'),
  ('Sebuah prosedur MT tertulis yang lengkap menurut ASME V Art 7 minimal harus mencakup:',
   '["Hanya nama metode","Hanya kriteria penerimaan","Hanya daftar peralatan","Ruang lingkup, persiapan permukaan, teknik magnetisasi & arus, partikel & medium, teknik aplikasi, pencahayaan, interpretasi/evaluasi, dan demagnetisasi"]', 3,
   'Prosedur tertulis harus merinci seluruh variabel proses: scope, surface prep, teknik & arus magnetisasi, partikel/medium, teknik aplikasi, pencahayaan, evaluasi/kriteria, demagnetisasi, dan pelaporan.', 'Procedure Development', 'easy'),
  ('Saat mengembangkan prosedur untuk benda tertentu, urutan pemeriksaan untuk dua arah medan ortogonal sebaiknya disusun sehingga:',
   '["Hanya satu arah yang diperiksa untuk efisiensi","Kedua arah (mis. sirkular lalu longitudinal) diperiksa sehingga diskontinuitas pada orientasi tegak lurus keduanya terdeteksi","Arah medan dibuat acak tanpa rencana","Demagnetisasi dilakukan di antara setiap partikel"]', 1,
   'Karena MT paling sensitif untuk diskontinuitas tegak lurus medan, prosedur harus mencakup dua arah ortogonal (mis. sirkular + longitudinal) agar semua orientasi diskontinuitas tercakup.', 'Procedure Development', 'easy'),
  ('Standar ASTM yang merupakan GUIDE/panduan umum untuk pemeriksaan partikel magnetik adalah:',
   '["ASTM E709","ASTM E94","ASTM E165","ASTM E1417"]', 0,
   'ASTM E709 adalah Standard Guide for Magnetic Particle Testing (bersifat panduan/tutorial). ASTM E1444 adalah Standard Practice (persyaratan ''shall''). E165/E1417 untuk penetran, E94 untuk RT.', 'Code Interpretation', 'easy'),
  ('Standar internasional ISO yang mengatur pemeriksaan partikel magnetik (general principles) adalah:',
   '["ISO 9712","ISO 9934","ISO 3452","ISO 17636"]', 1,
   'ISO 9934 (seri) mengatur magnetic particle testing — Part 1 general principles, Part 2 detection media, Part 3 equipment. ISO 9712 adalah kualifikasi personel; ISO 3452 untuk penetran.', 'Code Interpretation', 'medium'),
  ('Untuk pengujian sambungan las struktur baja, kode AWS yang umum mengatur kriteria penerimaan (termasuk MT) adalah:',
   '["AWS D1.1 (Structural Welding Code — Steel)","AWS A2.4","AWS D17.1","AWS B2.1"]', 0,
   'AWS D1.1 Structural Welding Code — Steel memuat persyaratan dan kriteria penerimaan inspeksi las baja struktural, termasuk MT untuk koneksi statis dan dinamis (cyclic).', 'Code Interpretation', 'medium'),
  ('ASTM E1444 dibanding ASTM E709 paling tepat dideskripsikan sebagai:',
   '["E1444 panduan informatif, E709 wajib kontraktual","E1444 Standard Practice (persyaratan, sering kontraktual), sedangkan E709 Standard Guide (informatif/tutorial)","Keduanya identik dan dapat dipertukarkan tanpa perbedaan","E1444 hanya untuk penetran"]', 1,
   'E1444 adalah Standard Practice berisi persyaratan ''shall'' yang sering dipakai kontraktual; E709 adalah Standard Guide bersifat tutorial/informatif. Keduanya saling melengkapi tetapi berbeda status normatifnya.', 'Code Interpretation', 'hard'),
  ('ASME Section V Article 7 berisi:',
   '["Kualifikasi personel NDT","Kriteria penerimaan akhir untuk semua komponen","Spesifikasi material partikel saja","Metode dan persyaratan pelaksanaan Magnetic Particle Examination"]', 3,
   'ASME Section V Article 7 menetapkan metode & persyaratan pelaksanaan MT. Kriteria penerimaan biasanya berada di code konstruksi yang mengacu (mis. Sec. VIII, B31.x). Kualifikasi personel mengacu SNT-TC-1A/CP-189.', 'Code Interpretation', 'medium'),
  ('Bila suatu kontrak menyebut ''MT per ASME V Art 7'' tetapi tidak menyebut kriteria penerimaan, maka kriteria penerimaan diambil dari:',
   '["Article 7 itu sendiri","Code konstruksi/spesifikasi yang mengacu (referencing code), mis. Sec. VIII Div.1","Pendapat operator MT","ASTM E709"]', 1,
   'Article 7 hanya menetapkan metode; kriteria penerimaan ditetapkan oleh referencing code/spesifikasi (mis. ASME Sec. VIII, B31.3, AWS D1.1). Inilah sebabnya prosedur harus mencantumkan kriteria penerimaan yang berlaku.', 'Code Interpretation', 'hard'),
  ('Ketos ring (Tool Steel Ring) standar digunakan untuk:',
   '["Mengukur intensitas UV-A","Mengevaluasi keseluruhan kinerja sistem (system performance) MT dengan lubang artificial pada arus tertentu","Mengukur viskositas bath","Demagnetisasi benda kecil"]', 1,
   'Ketos ring memiliki lubang sub-surface pada kedalaman bervariasi; jumlah lubang yang termunculkan pada arus central-conductor tertentu memverifikasi kinerja keseluruhan sistem MT (partikel, arus, prosedur).', 'QC & Audit', 'medium'),
  ('Lift test untuk yoke memerlukan yoke mampu mengangkat beban minimal:',
   '["4,5 kg (10 lb) untuk AC dan 18 kg (40 lb) untuk DC","1 kg untuk AC dan 5 kg untuk DC","18 kg untuk AC dan 4,5 kg untuk DC","10 kg untuk keduanya"]', 0,
   'Yoke AC harus mengangkat ≥4,5 kg (10 lb) pada spasi maksimum; yoke DC/permanen ≥18 kg (40 lb). Ini verifikasi gaya angkat (lifting power) sebagai cek fungsional medan.', 'QC & Audit', 'medium'),
  ('Intensitas minimum UV-A pada permukaan benda untuk MT fluorescent adalah:',
   '["≥100 µW/cm²","≥500 µW/cm²","≥1000 µW/cm² (10 W/m²)","≥5000 µW/cm²"]', 2,
   'UV-A minimum di permukaan = 1000 µW/cm² (10 W/m²) diukur pada jarak kerja. Cahaya tampak ambient harus dijaga rendah agar kontras fluorescent maksimal.', 'QC & Audit', 'easy'),
  ('Cahaya tampak ambient (white light) maksimum di area inspeksi fluorescent adalah:',
   '["≤2 lux","≤20 lux","≤200 lux","≤1000 lux"]', 1,
   'Untuk MT fluorescent, ambient visible light harus ≤20 lux agar kontras indikasi fluorescent terhadap latar maksimal. Mata juga perlu adaptasi gelap ~1 menit sebelum inspeksi.', 'QC & Audit', 'medium'),
  ('Untuk MT dengan partikel visible (non-fluorescent), pencahayaan white light minimum di permukaan adalah:',
   '["≥100 lux","≥500 lux","≥1000 lux","≥3000 lux"]', 2,
   'Visible (contrast) technique membutuhkan white light ≥1000 lux (≈100 fc) di permukaan benda untuk kontras yang memadai antara indikasi dan latar.', 'QC & Audit', 'medium'),
  ('Pada uji settling (settling test) untuk konsentrasi partikel fluorescent, volume endapan yang dapat diterima per 100 mL bath adalah:',
   '["0,1–0,4 mL","1,2–2,4 mL","3–5 mL","0,01–0,05 mL"]', 0,
   'Settling test fluorescent: 0,1–0,4 mL per 100 mL. Untuk partikel visible rentangnya lebih tinggi, yaitu 1,2–2,4 mL per 100 mL, karena ukuran/jenis partikel berbeda.', 'QC & Audit', 'hard'),
  ('Pada settling test untuk partikel VISIBLE, volume endapan yang dapat diterima per 100 mL bath adalah:',
   '["0,1–0,4 mL","1,2–2,4 mL","5–10 mL","0,5–0,8 mL"]', 1,
   'Visible particles: 1,2–2,4 mL per 100 mL. Fluorescent jauh lebih rendah (0,1–0,4 mL). Konsentrasi di luar rentang menurunkan sensitivitas atau menimbulkan latar berlebih.', 'QC & Audit', 'hard'),
  ('Batas medan residual yang umum disyaratkan setelah demagnetisasi (mis. ASTM E1444) adalah:',
   '["≤3 G","≤30 G","≤300 G","≤0,3 G"]', 0,
   'Residual magnetism umumnya dibatasi ≤3 G (kecuali kontrak menentukan lain), diukur dengan field indicator/gaussmeter. Nilai lebih tinggi dapat menyebabkan arc blow atau menarik gram saat servis.', 'QC & Audit', 'medium'),
  ('QQI (shim) ditempatkan dengan sisi beralur menghadap permukaan benda karena:',
   '["Agar mudah dilepas","Agar tidak ada kebocoran fluks sama sekali","Agar arus mengalir lewat shim","Agar artificial flaw kontak langsung dengan benda sehingga kebocoran fluks merepresentasikan medan tangensial pada permukaan"]', 3,
   'QQI dipasang dengan sisi beralur (artificial flaw) menempel ke permukaan benda dan direkatkan rata, sehingga fluks benda menembus alur dan menghasilkan indikasi yang merepresentasikan arah & kecukupan medan tangensial nyata.', 'QC & Audit', 'hard'),
  ('Studi kasus: poros baja keras (Br tinggi) gagal dideteksi retaknya saat memakai teknik residual dengan AC. Penyebab paling mungkin:',
   '["AC tidak menghasilkan retentivitas yang berguna untuk residual karena nilainya bergantung pada titik gelombang saat mati","Poros tidak feromagnetik","Partikel terlalu kecil","UV-A terlalu tinggi"]', 0,
   'Pada residual technique, medan residual bergantung nilai arus saat dimatikan; AC dapat mati di titik mendekati nol sehingga residual tak menentu/rendah. Residual sebaiknya memakai DC (atau pakai continuous technique).', 'Case Studies', 'hard'),
  ('Studi kasus: pada pengelasan, sambungan mengalami arc blow parah setelah MT prod sebelumnya. Tindakan korektif yang tepat:',
   '["Menambah arus las","Mendemagnetisasi benda sebelum pengelasan karena medan residual menyebabkan arc blow","Mengganti elektroda dengan diameter lebih besar saja","Mengabaikan karena arc blow tidak terkait magnet"]', 1,
   'Medan residual dari MT dapat menyebabkan arc blow (busur menyimpang) saat pengelasan DC. Solusinya adalah demagnetisasi benda sebelum dilas dan memverifikasi residual ≤3 G.', 'Case Studies', 'medium'),
  ('Studi kasus: inspeksi pipa memakai offset central conductor satu shot, lalu ditemukan retak terlewat di sisi berlawanan konduktor. Penyebabnya:',
   '["Partikel kedaluwarsa","Arus terlalu tinggi","Hanya busur ~4× diameter konduktor yang termagnetisasi memadai per shot; benda harus diputar dengan overlap","UV-A terlalu rendah"]', 2,
   'Dengan offset central conductor, hanya keliling ~4× diameter konduktor yang memiliki medan memadai per shot. Untuk meliput seluruh keliling pipa, benda/konduktor harus diputar dengan tumpang-tindih yang cukup.', 'Case Studies', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- MT-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — MT-L2 scope', '{"description":"5 soal scope dan persyaratan Level II MT.","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- MT-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'MT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'MT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Manakah aktivitas berikut yang merupakan tanggung jawab MT Level II tetapi BUKAN kewenangan Level I menurut SNT-TC-1A?',
   '["Mengaplikasikan magnetic particle bath dan membersihkan permukaan part","Mengoperasikan peralatan dan memproses part sesuai instruksi tertulis","Menyusun/me-review written procedure, mengevaluasi indikasi terhadap acceptance criteria, dan menandatangani final accept/reject report","Menempatkan yoke pada lasan dan menyalakan arus magnetisasi"]', 2,
   'Menurut SNT-TC-1A, Level I melakukan kalibrasi spesifik, pengujian, dan mencatat hasil sesuai instruksi tertulis, tetapi tidak melakukan evaluasi independen maupun sign-off. Level II berwenang menyusun dan me-review prosedur tertulis, mengevaluasi indikasi terhadap acceptance criteria, melakukan disposisi accept/reject, serta menandatangani laporan final. Mengaplikasikan bath, membersihkan, mengoperasikan peralatan sesuai instruksi, dan memposisikan yoke adalah tugas yang juga dapat dilakukan Level I.', 'Scope & Authority', 'easy'),
  ('Manakah tugas berikut yang BERADA DI LUAR kewenangan MT Level II dan justru menjadi tanggung jawab Level III menurut SNT-TC-1A?',
   '["Mengevaluasi indikasi MT terhadap acceptance criteria dan menandatangani laporan hasil","Memilih teknik MT yang tepat untuk part tertentu sesuai prosedur yang berlaku","Memberikan on-the-job training serta panduan teknis kepada trainee dan personel Level I","Membangun/menetapkan sistem NDT, meng-approve prosedur, serta menguji dan mengkualifikasi (examine) personel NDT"]', 3,
   'Per SNT-TC-1A, Level II dapat mengevaluasi dan mendisposisi indikasi, memilih teknik yang sesuai prosedur, dan membimbing trainee/Level I. Namun penetapan/approval sistem dan prosedur NDT tingkat tinggi, interpretasi code/standard, serta pelaksanaan training, ujian, dan kualifikasi (examination) personel NDT adalah tanggung jawab Level III. Karena itu meng-examine dan mengkualifikasi personel berada di luar kewenangan Level II.', 'Scope & Authority', 'medium'),
  ('Manakah pernyataan yang paling tepat mengenai kewenangan MT Level II dalam pengembangan prosedur dibanding Level III?',
   '["Level II dapat menyusun dan me-review prosedur kerja/teknik MT, namun otoritas penuh atas sistem NDT, kualifikasi/approval prosedur, dan training/examination personel berada pada Level III","Level II memiliki seluruh kewenangan Level III termasuk meng-approve seluruh sistem NDT fasilitas","Level II tidak boleh terlibat sama sekali dalam penyusunan prosedur; itu sepenuhnya tugas Level III","Level II hanya boleh menjalankan prosedur dan tidak pernah me-review-nya"]', 0,
   'Level II dapat menyusun dan me-review prosedur/teknik MT untuk lingkup metodenya serta mengevaluasi dan menandatangani hasil. Namun tanggung jawab penuh atas sistem NDT, pengembangan/kualifikasi dan persetujuan prosedur tingkat tinggi, serta training dan examination/kualifikasi personel adalah kewenangan Level III. Jadi Level II berperan aktif dalam prosedur tetapi tidak menggantikan otoritas Level III.', 'Procedure Development', 'medium'),
  ('Menurut ISO 9712, agar dapat melakukan tanggung jawab penuh Level II MT, seorang kandidat yang tersertifikasi pada umumnya harus memenuhi syarat utama apa?',
   '["Cukup lulus ujian tertulis umum saja tanpa praktik maupun pengalaman","Memiliki sertifikasi pada metode/level tetapi tidak memerlukan medical/vision check","Memenuhi training minimum, pengalaman industri terdokumentasi, lulus ujian (general, specific, practical), serta pemeriksaan penglihatan (near-vision dan color/contrast) yang valid","Hanya perlu rekomendasi tertulis dari Level I tanpa ujian formal"]', 2,
   'ISO 9712 mensyaratkan kombinasi pelatihan minimum sesuai metode/level, pengalaman industri terdokumentasi, dan kelulusan ujian general, specific, serta practical. Selain itu kandidat harus lulus pemeriksaan penglihatan dekat (near-vision, mis. membaca Jaeger No.1/Times Roman N4.5 pada ~30 cm) dan kemampuan membedakan warna/kontras, yang harus diperiksa secara berkala. Sertifikasi tidak diberikan hanya berdasarkan ujian tertulis umum atau rekomendasi tanpa ujian.', 'Certification Requirements', 'medium'),
  ('Sebuah fasilitas memakai SNT-TC-1A sebagai dasar program kualifikasi. Manakah pernyataan yang paling akurat mengenai status dokumen ini dan bagaimana persyaratan Level II ditetapkan?',
   '["SNT-TC-1A adalah standar wajib (mandatory) yang menetapkan jam training dan pengalaman secara mutlak untuk semua perusahaan","SNT-TC-1A adalah recommended practice; persyaratan spesifik (jam training, pengalaman, ujian, recertification) untuk Level II ditetapkan dalam Written Practice tertulis milik employer","Persyaratan Level II sepenuhnya ditentukan oleh ASME Section V Article 7, bukan oleh Written Practice","SNT-TC-1A melarang employer menambah persyaratan apa pun di atas nilai yang tercantum di dalamnya"]', 1,
   'SNT-TC-1A adalah recommended practice ASNT, bukan spesifikasi/standar wajib; nilai-nilai di dalamnya (jam training, pengalaman, dsb.) bersifat panduan. Penerapan aktualnya dituangkan dalam Written Practice tertulis employer yang menetapkan persyaratan spesifik kualifikasi dan sertifikasi Level II, termasuk training, pengalaman, ujian, dan recertification, dan employer boleh memperketatnya. Berbeda dengan ISO 9712 (skema sertifikasi pihak ketiga) atau CP-189 yang lebih preskriptif, di skema SNT-TC-1A employer-lah yang mensertifikasi personelnya sesuai Written Practice. ASME V Article 7 mengatur metode pemeriksaan, bukan kualifikasi personel.', 'Certification Requirements', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'MT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;
